def db_conn():
    c = sqlite3.connect(
        DB,
        timeout=5,
        check_same_thread=False
    )
    c.row_factory = sqlite3.Row
    c.execute("PRAGMA busy_timeout=3000")
    return c


def init_db():
    with db_conn() as c:
        # WAL allows the home page to READ saved data while background
        # threads perform short WRITES. This greatly reduces lock errors.
        try:
            c.execute("PRAGMA journal_mode=WAL")
            c.execute("PRAGMA synchronous=NORMAL")
        except sqlite3.OperationalError as e:
            print("SQLite WAL setup warning:", e)


        # Independent Weekly -> Daily reversal arrows. Old CCI tables are kept
        # untouched for safe rollback, but no CCI calculations or alerts run.
        c.execute("""CREATE TABLE IF NOT EXISTS weekly_daily_inline (
            symbol TEXT NOT NULL, grp TEXT NOT NULL,
            state TEXT NOT NULL DEFAULT '', level REAL, confirmed_at TEXT,
            updated TEXT, PRIMARY KEY(symbol,grp)
        )""")
        c.execute("""CREATE TABLE IF NOT EXISTS weekly_daily_inline_sound_log (
            symbol TEXT NOT NULL, grp TEXT NOT NULL, direction TEXT NOT NULL,
            event_key TEXT NOT NULL, sent_at TEXT NOT NULL,
            PRIMARY KEY(symbol,grp,direction,event_key)
        )""")

        # Diagnostic-only scanner history (persistent through Railway redeploys).
        c.execute("""
        CREATE TABLE IF NOT EXISTS scanner_health (
            scanner TEXT PRIMARY KEY,
            last_attempt TEXT NOT NULL DEFAULT '',
            last_success TEXT NOT NULL DEFAULT '',
            last_error_at TEXT NOT NULL DEFAULT '',
            last_error TEXT NOT NULL DEFAULT '',
            last_symbol TEXT NOT NULL DEFAULT '',
            last_interval TEXT NOT NULL DEFAULT '',
            last_signal_at TEXT NOT NULL DEFAULT '',
            last_signal TEXT NOT NULL DEFAULT '',
            attempts INTEGER NOT NULL DEFAULT 0,
            successes INTEGER NOT NULL DEFAULT 0,
            failures INTEGER NOT NULL DEFAULT 0
        )
        """)

        c.execute('''
        CREATE TABLE IF NOT EXISTS alerts(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            symbol TEXT,
            grp TEXT,
            direction TEXT,
            target REAL,
            triggered INTEGER DEFAULT 0,
            last_price REAL,
            created TEXT,
            note TEXT
        )
        ''')

        c.execute('''
        CREATE TABLE IF NOT EXISTS favorites(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            symbol TEXT NOT NULL,
            grp TEXT NOT NULL,
            UNIQUE(symbol,grp)
        )
        ''')

        c.execute('''
        CREATE TABLE IF NOT EXISTS trend_status(
            symbol TEXT PRIMARY KEY,
            status TEXT NOT NULL DEFAULT '',
            updated TEXT
        )
        ''')
        c.execute('''
        CREATE TABLE IF NOT EXISTS trend_snapshot(
            symbol TEXT PRIMARY KEY,
            weekly TEXT,
            daily TEXT,
            h12 TEXT,
            h8 TEXT,
            h4 TEXT,
            h1 TEXT,
            updated TEXT
        )
        ''')
        c.execute('''
        CREATE TABLE IF NOT EXISTS trailing_stops(
            id INTEGER PRIMARY KEY AUTOINCREMENT, symbol TEXT NOT NULL, grp TEXT NOT NULL,
            side TEXT NOT NULL, interval TEXT NOT NULL, distance_pips REAL NOT NULL,
            stop_price REAL NOT NULL, last_candle_start TEXT DEFAULT '', last_candle_time TEXT DEFAULT '',
            triggered INTEGER DEFAULT 0, created TEXT, note TEXT, distance_mode TEXT DEFAULT 'PRICE', entry_price REAL
        )
        ''')

        c.execute('''
        CREATE TABLE IF NOT EXISTS pattern_notifications(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            symbol TEXT NOT NULL,
            interval TEXT NOT NULL,
            pattern_name TEXT NOT NULL,
            direction TEXT NOT NULL,
            confirmation_date TEXT NOT NULL,
            sent_at TEXT NOT NULL,
            UNIQUE(symbol, interval, pattern_name, direction, confirmation_date)
        )
        ''')
        # Notification transparency: previous sent_at was written BEFORE Pushover
        # was called. Preserve it as a historical log timestamp, not proof of delivery.
        for col, dtype in (
            ("push_attempted_at", "TEXT"),
            ("push_accepted_at", "TEXT"),
            ("push_status", "TEXT"),
        ):
            try:
                c.execute(f"ALTER TABLE pattern_notifications ADD COLUMN {col} {dtype}")
            except sqlite3.OperationalError:
                pass

        c.execute("""
        CREATE TABLE IF NOT EXISTS pair_daily_pushes(
            grp TEXT NOT NULL,
            symbol TEXT NOT NULL,
            local_day TEXT NOT NULL,
            signal_name TEXT NOT NULL,
            direction TEXT NOT NULL,
            sent_at TEXT NOT NULL,
            PRIMARY KEY(grp, symbol, local_day)
        )
        """)

        c.execute("""
        CREATE TABLE IF NOT EXISTS pattern_daily_pushes(
            grp TEXT NOT NULL,
            symbol TEXT NOT NULL,
            signal_family TEXT NOT NULL,
            direction TEXT NOT NULL,
            local_day TEXT NOT NULL,
            pattern_name TEXT NOT NULL,
            sent_at TEXT NOT NULL,
            PRIMARY KEY(grp, symbol, signal_family, direction, local_day)
        )
        """)

        c.execute("""
        CREATE TABLE IF NOT EXISTS pattern_monitor_state(
            grp TEXT NOT NULL,
            symbol TEXT NOT NULL,
            interval TEXT NOT NULL,
            last_closed_date TEXT NOT NULL DEFAULT '',
            updated TEXT,
            PRIMARY KEY(grp, symbol, interval)
        )
        """)

        c.execute("""
        CREATE TABLE IF NOT EXISTS price_action_status(
            grp TEXT NOT NULL,
            symbol TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'WAIT',
            direction TEXT NOT NULL DEFAULT '',
            confirmation_date TEXT NOT NULL DEFAULT '',
            acknowledged_date TEXT NOT NULL DEFAULT '',
            updated TEXT,
            PRIMARY KEY(grp, symbol)
        )
        """)

        # Independent unread READY state for each Price Action timeframe.
        c.execute("""
        CREATE TABLE IF NOT EXISTS price_action_timeframe_status(
            grp TEXT NOT NULL, symbol TEXT NOT NULL, interval TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'WAIT', direction TEXT NOT NULL DEFAULT '',
            confirmation_date TEXT NOT NULL DEFAULT '', acknowledged_date TEXT NOT NULL DEFAULT '',
            updated TEXT, PRIMARY KEY(grp,symbol,interval)
        )
        """)

        # Blink acknowledgement is independent from timeframe NEW/read state.
        c.execute("""
        CREATE TABLE IF NOT EXISTS price_action_blink_ack(
            grp TEXT NOT NULL, symbol TEXT NOT NULL, interval TEXT NOT NULL,
            confirmation_date TEXT NOT NULL DEFAULT '',
            PRIMARY KEY(grp,symbol,interval)
        )
        """)

        # Migration for existing EdoSignal databases: remember which READY setup Edo has opened.
        try:
            c.execute("ALTER TABLE price_action_status ADD COLUMN acknowledged_date TEXT NOT NULL DEFAULT ''")
        except sqlite3.OperationalError:
            pass

        c.execute("""
        CREATE TABLE IF NOT EXISTS weekly_spike_notifications(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            grp TEXT NOT NULL,
            symbol TEXT NOT NULL,
            candle_date TEXT NOT NULL,
            side TEXT NOT NULL,
            wick_ratio REAL,
            sent_at TEXT NOT NULL,
            UNIQUE(grp, symbol, candle_date, side)
        )
        """)

        c.execute("""
        CREATE TABLE IF NOT EXISTS economic_news(
            event_id TEXT PRIMARY KEY,
            event_time_utc TEXT NOT NULL,
            country TEXT,
            currency TEXT,
            event_name TEXT NOT NULL,
            category TEXT,
            importance INTEGER NOT NULL DEFAULT 3,
            fetched_at TEXT NOT NULL
        )
        """)

        c.execute("""
        CREATE INDEX IF NOT EXISTS idx_economic_news_time
        ON economic_news(event_time_utc)
        """)

        c.execute("""
        CREATE TABLE IF NOT EXISTS economic_news_pushes(
            event_id TEXT PRIMARY KEY,
            sent_at TEXT NOT NULL
        )
        """)

        c.execute("""
        CREATE TABLE IF NOT EXISTS economic_news_reactions(
            event_id TEXT PRIMARY KEY,
            reaction_15 TEXT,
            score_15 REAL,
            reaction_30 TEXT,
            score_30 REAL,
            updated TEXT
        )
        """)

        c.execute("""
        CREATE TABLE IF NOT EXISTS economic_news_pair_reactions(
            event_id TEXT NOT NULL,
            symbol TEXT NOT NULL,
            grp TEXT NOT NULL,
            display_symbol TEXT NOT NULL,
            reaction_15 TEXT,
            score_15 REAL,
            reaction_30 TEXT,
            score_30 REAL,
            updated TEXT,
            PRIMARY KEY(event_id, symbol, grp)
        )
        """)

        # Keep older persistent Railway databases compatible with the
        # 15m / 30m news-reaction feature. CREATE TABLE IF NOT EXISTS does
        # not add columns to an already existing table, so migrate safely.
        for _col, _type in (
            ("reaction_15", "TEXT"),
            ("score_15", "REAL"),
            ("reaction_30", "TEXT"),
            ("score_30", "REAL"),
            ("updated", "TEXT"),
        ):
            try:
                c.execute(f"ALTER TABLE economic_news_reactions ADD COLUMN {_col} {_type}")
            except sqlite3.OperationalError:
                pass

        c.execute("""
        CREATE TABLE IF NOT EXISTS economic_news_status(
            id INTEGER PRIMARY KEY CHECK(id=1),
            last_attempt TEXT,
            last_success TEXT,
            last_error TEXT,
            source_url TEXT
        )
        """)
        c.execute("""
        INSERT OR IGNORE INTO economic_news_status(
            id,last_attempt,last_success,last_error,source_url
        )
        VALUES(1,'','','','')
        """)

        # Forex-only Monthly Abnormal Spike detector; independent of Weekly.
        c.execute("""
        CREATE TABLE IF NOT EXISTS monthly_spike_state(
            grp TEXT NOT NULL, symbol TEXT NOT NULL,
            last_closed_date TEXT NOT NULL DEFAULT '', updated TEXT,
            PRIMARY KEY(grp, symbol)
        )
        """)
        c.execute("""
        CREATE TABLE IF NOT EXISTS monthly_spike_notifications(
            grp TEXT NOT NULL, symbol TEXT NOT NULL,
            candle_date TEXT NOT NULL, side TEXT NOT NULL,
            wick_ratio REAL, sent_at TEXT NOT NULL,
            PRIMARY KEY(grp, symbol, candle_date, side)
        )
        """)

        c.execute("""
        CREATE TABLE IF NOT EXISTS weekly_spike_state(
            grp TEXT NOT NULL,
            symbol TEXT NOT NULL,
            last_closed_date TEXT NOT NULL DEFAULT '',
            updated TEXT,
            PRIMARY KEY(grp, symbol)
        )
        """)

        try:
            c.execute("ALTER TABLE alerts ADD COLUMN note TEXT")
        except sqlite3.OperationalError:
            pass

        # Trailing-stop migration: older records were entered as pips/points.
        # Keep them identifiable so they are never silently reinterpreted as a price distance.
        try:
            c.execute("ALTER TABLE trailing_stops ADD COLUMN distance_mode TEXT DEFAULT 'PIPS'")
        except sqlite3.OperationalError:
            pass

        # Entry-price trailing-stop migration. New trails use the user's actual trade entry
        # price to lock the permanent raw price distance to the starting stop.
        try:
            c.execute("ALTER TABLE trailing_stops ADD COLUMN entry_price REAL")
        except sqlite3.OperationalError:
            pass

        # Full Trend uses 4H with a two-closed-candle confirmation; 3H and 8H are not part of Full Trend.
        # Adding h3 is our one-time migration marker. Clear the old FULL status
        # so a badge calculated under the previous 1H rule is never shown as
        # if it were a 3H result after deployment.
        try:
            c.execute("ALTER TABLE trend_snapshot ADD COLUMN h3 TEXT")
            c.execute("UPDATE trend_status SET status='', updated=NULL")
        except sqlite3.OperationalError:
            pass

        # CFD Full Trend migration: Daily is now a CFD signal timeframe.
        try:
            c.execute("ALTER TABLE trend_snapshot ADD COLUMN daily TEXT")
        except sqlite3.OperationalError:
            pass
        c.commit()


