def fxcm_service_get_ohlc(symbol, interval, outputsize=140):
    """Read FXCM Bid candles from EdoSignal's private Railway FXCM service."""
    if not FXCM_SERVICE_URL:
        return None, "FXCM service URL is not configured."

    timeframe_map = {
        "4h": "H4",
        "8h": "H8",
        "12h": "H12",
        "1day": "D1",
    }
    tf = timeframe_map.get(str(interval).lower())
    if not tf:
        return None, f"FXCM service does not provide {interval}."

    try:
        r = requests.get(
            FXCM_SERVICE_URL + "/candles",
            params={
                "symbol": symbol,
                "timeframe": tf,
                "count": max(10, min(int(outputsize), 500)),
            },
            timeout=20
        )
        r.raise_for_status()
        payload = r.json()

        if not payload.get("ok"):
            return None, "FXCM service error: " + str(payload.get("error", "Unknown error"))

        candles = []
        for row in payload.get("rows") or []:
            candles.append({
                "datetime": str(row.get("datetime", "")),
                "open": float(row["open"]),
                "high": float(row["high"]),
                "low": float(row["low"]),
                "close": float(row["close"]),
                "_source_symbol": symbol,
                "_source_label": "FXCM Bid",
                # Mark these as broker-native FXCM candles. Their labels must
                # not be shifted/rebucketed by generic UTC candle logic.
                "_fxcm_native": True,
            })

        candles.sort(key=lambda x: x["datetime"])
        # The FXCM helper has occasionally supplied a synthetic D1 candle
        # stamped on Saturday evening UTC (e.g. GBP/USD 2026-10-24 21:00Z).
        # Spot FX is closed then. Treating that row as an independent Daily
        # candle inflated Edo's consecutive red/green pullback counts.
        # Preserve the raw provider bars on all intraday timeframes; this
        # guard applies ONLY to Forex D1, not to crypto or index CFDs.
        if tf == "D1" and str(symbol).strip().upper() not in {
            "SPX500", "US30", "NAS100", "GER30", "UK100", "FRA40",
            "JPN225", "AUS200", "HK33", "US2000"
        }:
            kept = []
            for candle in candles:
                session_time = parse_candle_utc(candle.get("datetime"))
                if session_time is not None and session_time.weekday() == 5:
                    print("FXCM D1 closed-market Saturday bar excluded:",
                          symbol, candle.get("datetime"))
                    continue
                kept.append(candle)
            candles = kept
        if not candles:
            return None, "FXCM service returned no candles."

        # FXCM's newest row is the current live broker candle while Forex is
        # open. It must never confirm a setup.
        if not forex_weekend_closed():
            candles[-1]["_fxcm_forming"] = True

        return candles[-outputsize:], None

    except Exception as e:
        print("FXCM service OHLC error:", symbol, interval, e)
        return None, f"FXCM service error: {e}"


def get_ohlc(symbol, interval, outputsize=140, grp=None):
    """Download OHLC oldest -> newest. Forex and key CFDs use FXCM; Crypto uses Bybit; other data uses Twelve Data."""
    cache_key = (grp or "", symbol.upper().strip(), interval)
    now = time.time()
    ttl = ohlc_cache_seconds(interval)

    with _CACHE_LOCK:
        cached = _OHLC_CACHE.get(cache_key)
        if cached and now - cached["saved_at"] < ttl and len(cached["candles"]) >= outputsize:
            return cached["candles"][-outputsize:], None

    # FOREX: use the real FXCM Bid candle feed from the private Railway service.
    # Weekly remains reference-only and keeps the existing source because the
    # FXCM helper service currently exposes H4/H8/H12/D1.
    if grp == "FOREX" and interval in {"4h", "8h", "12h", "1day"}:
        fxcm_candles, fxcm_error = fxcm_service_get_ohlc(symbol, interval, outputsize)
        if fxcm_candles:
            # Keep FXCM H4/D1 candles exactly as supplied by the broker service.
            # Weekend notification suppression is handled separately and does
            # not alter the historical candle sequence.

            if len(fxcm_candles) < min(40, outputsize):
                return None, (
                    f"Not enough valid {interval} FXCM Forex session candles "
                    f"returned for {symbol}."
                )

            with _CACHE_LOCK:
                _OHLC_CACHE[cache_key] = {
                    "saved_at": now,
                    "candles": fxcm_candles
                }
            print("FOREX market source", symbol, "-> FXCM private service")
            return fxcm_candles[-outputsize:], None
        return None, fxcm_error

    # CFD: for the US indices Edo checks on FXCM, use the SAME broker-native
    # FXCM Bid candles instead of Twelve Data ETF proxies (SPY/DIA/QQQ).
    # This prevents a proxy ETF candle sequence from creating a Trend Pullback
    # that is not visible on Edo's FXCM SPX500/US30/NAS100 chart.
    if grp == "CFD" and interval in {"4h", "8h", "1day"}:
        fxcm_symbol = fxcm_cfd_symbol(symbol)
        fxcm_candles, fxcm_error = fxcm_service_get_ohlc(
            fxcm_symbol, interval, outputsize
        )
        if fxcm_candles:
            for c in fxcm_candles:
                c["_source_symbol"] = fxcm_symbol
                c["_source_label"] = f"FXCM {fxcm_symbol} Bid"
            if len(fxcm_candles) < min(40, outputsize):
                return None, (
                    f"Not enough valid {interval} FXCM CFD candles returned "
                    f"for {fxcm_symbol}."
                )
            with _CACHE_LOCK:
                _OHLC_CACHE[cache_key] = {
                    "saved_at": now,
                    "candles": fxcm_candles
                }
            print("CFD market source", symbol, "-> FXCM", fxcm_symbol)
            return fxcm_candles[-outputsize:], None

        # IMPORTANT: do not silently fall back to SPY/DIA/QQQ for these signal
        # timeframes. A proxy can have different candles and create false visual
        # matches. Show a data error instead of issuing a mismatched signal.
        return None, (
            f"FXCM CFD chart data unavailable for {fxcm_symbol}: {fxcm_error}"
        )

    # Crypto uses the same Bybit USDT perpetual market Edo trades.
    # The newest raw candle may still be forming. Signal logic continues to
    # pass through fully_closed_candles(), so a live candle cannot trigger.
    if grp == "CRYPTO":
        resolved_symbol = bybit_crypto_symbol(symbol)
        resolved_interval = bybit_interval(interval)
        if not resolved_interval:
            return None, f"Bybit interval {interval} is built synthetically by EdoSignal."

        try:
            j = bybit_get_json(
                "https://api.bybit.com/v5/market/kline",
                {
                    "category": "linear",
                    "symbol": resolved_symbol,
                    "interval": resolved_interval,
                    "limit": min(1000, max(40, int(outputsize))),
                },
                timeout=15
            )

            if int(j.get("retCode", -1)) != 0:
                return None, f"Bybit error for {resolved_symbol}: {j.get('retMsg', 'Unknown error')}"

            values = (j.get("result") or {}).get("list") or []
            candles = []

            # Bybit returns newest -> oldest. EdoSignal uses oldest -> newest.
            for row in reversed(values):
                try:
                    start_dt = datetime.fromtimestamp(
                        int(row[0]) / 1000.0, tz=timezone.utc
                    )
                    candles.append({
                        "datetime": start_dt.strftime("%Y-%m-%d %H:%M:%S"),
                        "open": float(row[1]),
                        "high": float(row[2]),
                        "low": float(row[3]),
                        "close": float(row[4]),
                        "_source_symbol": resolved_symbol,
                        "_source_label": f"Bybit {resolved_symbol} USDT Perpetual",
                    })
                except (IndexError, TypeError, ValueError, OverflowError):
                    pass

            if len(candles) < 40:
                return None, (
                    f"Not enough {interval} Bybit candle history returned "
                    f"for {resolved_symbol}."
                )

            with _CACHE_LOCK:
                old = _OHLC_CACHE.get(cache_key)
                if not old or len(candles) >= len(old["candles"]):
                    _OHLC_CACHE[cache_key] = {
                        "saved_at": now,
                        "candles": candles
                    }

            print("CRYPTO market source", symbol, "-> Bybit", resolved_symbol, interval)
            return candles[-outputsize:], None

        except Exception as e:
            print("Bybit setup scanner data error", symbol, interval, e)
            return None, "Could not download Bybit crypto setup data."

    if not TWELVE_KEY:
        return None, "Twelve Data API key is not configured."

    last_error = "Twelve Data returned no usable market data."

    try:
        for resolved_symbol in twelve_symbol_candidates(symbol, grp):
            j = twelve_get_json(
                "https://api.twelvedata.com/time_series",
                {
                    "symbol": resolved_symbol,
                    "interval": interval,
                    "outputsize": outputsize,
                    "apikey": TWELVE_KEY,
                    "format": "JSON",
                    "timezone": "UTC",
                },
                timeout=15
            )

            if j.get("status") == "error":
                last_error = j.get("message", "Twelve Data returned an error.")
                continue

            values = j.get("values") or []
            candles = []

            for row in reversed(values):
                try:
                    candles.append({
                        "datetime": row.get("datetime", ""),
                        "open": float(row["open"]),
                        "high": float(row["high"]),
                        "low": float(row["low"]),
                        "close": float(row["close"]),
                        "_source_symbol": resolved_symbol,
                        "_source_label": source_label_for(symbol, grp, resolved_symbol),
                    })
                except (KeyError, TypeError, ValueError):
                    pass

            if len(candles) < 40:
                last_error = f"Not enough {interval} candle history returned for {resolved_symbol}."
                continue

            with _CACHE_LOCK:
                old = _OHLC_CACHE.get(cache_key)
                if not old or len(candles) >= len(old["candles"]):
                    _OHLC_CACHE[cache_key] = {"saved_at": now, "candles": candles}

            if grp == "CFD":
                print("CFD market source", symbol, "->", resolved_symbol)

            return candles, None

        return None, last_error

    except TwelveDataCoolingDown:
        return None, "API cooling down — please try again in a few seconds."
    except Exception as e:
        print("setup scanner data error", symbol, interval, e)
        return None, "Could not download setup data."


def swing_points(candles, kind="low", left=2, right=2):
    """Return clear local swing highs/lows, excluding edge candles."""
    points = []
    key = "low" if kind == "low" else "high"

    for i in range(left, len(candles) - right):
        value = candles[i][key]
        before = [candles[j][key] for j in range(i-left, i)]
        after = [candles[j][key] for j in range(i+1, i+right+1)]

        if kind == "low":
            if value <= min(before) and value <= min(after):
                points.append((i, value))
        else:
            if value >= max(before) and value >= max(after):
                points.append((i, value))

    return points


def candle_colour(c):
    if c["close"] > c["open"]:
        return "green"
    if c["close"] < c["open"]:
        return "red"
    return "flat"


def interval_seconds(interval):
    mapping = {
        "1min": 60,
        "1h": 60 * 60,
        "2h": 2 * 60 * 60,
        "3h": 3 * 60 * 60,
        "4h": 4 * 60 * 60,
        "6h": 6 * 60 * 60,
        "8h": 8 * 60 * 60,
        "12h": 12 * 60 * 60,
        "1day": 24 * 60 * 60,
        "1week": 7 * 24 * 60 * 60,
    }
    return mapping.get(interval)


def parse_candle_utc(value):
    if not value:
        return None
    try:
        from datetime import timezone
        dt = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except Exception:
        return None


def fully_closed_candles(candles, interval, now_utc=None):
    """
    Keep only candles whose complete interval has elapsed.
    Twelve Data OHLC is requested in UTC, so this avoids accidentally
    accepting a still-forming 4H/8H/Daily candle as a trigger.
    """
    from datetime import timezone, timedelta

    if interval == "1month":
        return fully_closed_monthly_candles(candles, now_utc=now_utc)
    seconds = interval_seconds(interval)
    if not candles or not seconds:
        return []

    if now_utc is None:
        now_utc = datetime.now(timezone.utc)

    duration = timedelta(seconds=seconds)
    closed = []

    for c in candles:
        # FXCM rows already represent the broker's native chart candles.
        # Preserve those exact H4/D1 candle groupings instead of applying the
        # generic UTC start+duration rule, which can shift the broker session
        # and create a colour sequence that does not match the FXCM chart.
        if c.get("_fxcm_native"):
            # Preserve FXCM's exact broker candle grouping, but exclude the
            # newest live/forming candle from every signal calculation.
            if c.get("_fxcm_forming"):
                continue
            closed.append(c)
            continue

        start = parse_candle_utc(c.get("datetime", ""))
        if start is None:
            continue
        if start + duration <= now_utc:
            closed.append(c)

    return closed


def closed_candle_is_fresh(candle, interval, now_utc=None, grace_seconds=120):
    """
    Safety check for FULL TREND.

    A FULL BULLISH/BEARISH state must never be built from a candle that is
    one whole interval behind the newest completed candle. This can happen
    briefly when an API/cache still contains pre-close data just after a
    candle boundary.

    We accept the newest closed candle only while its close time is no more
    than one interval + a small API grace period behind current UTC time.
    """
    from datetime import timezone, timedelta

    if not candle:
        return False
    seconds = interval_seconds(interval)
    start = parse_candle_utc(candle.get("datetime", ""))
    if not seconds or start is None:
        return False
    if now_utc is None:
        now_utc = datetime.now(timezone.utc)

    close_time = start + timedelta(seconds=seconds)
    age = now_utc - close_time
    return age.total_seconds() <= (seconds + grace_seconds)


def clear_ohlc_cache_for_symbol(symbol, grp=None, intervals=None):
    """Force the next FULL TREND read to use fresh market data."""
    wanted = set(intervals or ())
    symbol_key = symbol.upper().strip()
    with _CACHE_LOCK:
        for key in list(_OHLC_CACHE.keys()):
            key_grp, key_symbol, key_interval = key
            if key_symbol != symbol_key:
                continue
            if grp is not None and key_grp != (grp or ""):
                continue
            if wanted and key_interval not in wanted:
                continue
            _OHLC_CACHE.pop(key, None)


def avg_range(candles, end=None, length=20):
    if end is None:
        end = len(candles)
    part = candles[max(0, end-length):end]
    if not part:
        return 0.0
    return sum(max(0.0, c["high"] - c["low"]) for c in part) / len(part)


def avg_body(candles, end=None, length=20):
    if end is None:
        end = len(candles)
    part = candles[max(0, end-length):end]
    if not part:
        return 0.0
    return sum(abs(c["close"] - c["open"]) for c in part) / len(part)


def confirmation_at(candles, i):
    """
    Edo NORMAL Trend Pullback confirmation.

    This is deliberately separate from the S/R gap-and-retest setup.

    NORMAL pullback rule:
      - previous candle and confirmation candle must be opposite colours
      - confirmation candle must be fully closed by the caller
      - NO 50% body-penetration requirement

    The minimum 2 same-colour pullback candles are checked separately by
    detect_trend_pullback().
    """
    if i <= 0 or i >= len(candles):
        return None

    prev = candles[i - 1]
    curr = candles[i]

    prev_colour = candle_colour(prev)
    curr_colour = candle_colour(curr)

    if prev_colour == "red" and curr_colour == "green":
        return {
            "direction": "bullish",
            "index": i,
            "date": curr.get("datetime", ""),
            "close": float(curr["close"]),
        }

    if prev_colour == "green" and curr_colour == "red":
        return {
            "direction": "bearish",
            "index": i,
            "date": curr.get("datetime", ""),
            "close": float(curr["close"]),
        }

    return None


def sr_confirmation_at(candles, i):
    """
    Edo S/R GAP-AND-RETEST confirmation — 50% RULE APPLIES HERE ONLY.

    Bearish resistance retest:
      - previous candle is green
      - next fully closed candle is red
      - red candle closes below the 50% midpoint of the previous green body

    Bullish support retest:
      - previous candle is red
      - next fully closed candle is green
      - green candle closes above the 50% midpoint of the previous red body

    This helper is NOT used by the normal minimum-2-candle pullback setup.
    """
    if i <= 0 or i >= len(candles):
        return None

    prev = candles[i - 1]
    curr = candles[i]

    prev_colour = candle_colour(prev)
    curr_colour = candle_colour(curr)

    body = abs(float(prev["close"]) - float(prev["open"]))
    if body <= 0:
        return None

    midpoint = (float(prev["open"]) + float(prev["close"])) / 2.0

    if prev_colour == "red" and curr_colour == "green":
        penetration = ((float(curr["close"]) - float(prev["close"])) / body) * 100.0
        if float(curr["close"]) > midpoint and penetration >= 50.0:
            return {
                "direction": "bullish",
                "index": i,
                "penetration": penetration,
                "date": curr.get("datetime", ""),
                "close": float(curr["close"]),
                "previous_midpoint": midpoint,
            }

    if prev_colour == "green" and curr_colour == "red":
        penetration = ((float(prev["close"]) - float(curr["close"])) / body) * 100.0
        if float(curr["close"]) < midpoint and penetration >= 50.0:
            return {
                "direction": "bearish",
                "index": i,
                "penetration": penetration,
                "date": curr.get("datetime", ""),
                "close": float(curr["close"]),
                "previous_midpoint": midpoint,
            }

    return None


def crypto_second_candle_sr_confirmation(candles, i):
    """Crypto-only: allow the second consecutive rejection candle to confirm.

    The first opposite-colour candle must FAIL the original 50% body
    midpoint. The second candle must close beyond that SAME original midpoint.
    This never accumulates percentage across candles and never treats a wick
    as a close. Callers provide fully closed candles only.
    """
    if i < 2 or i >= len(candles):
        return None
    reference, first, second = candles[i - 2:i + 1]
    reference_colour = candle_colour(reference)
    first_colour = candle_colour(first)
    second_colour = candle_colour(second)
    body = abs(float(reference['close']) - float(reference['open']))
    if body <= 0 or first_colour != second_colour:
        return None
    midpoint = (float(reference['open']) + float(reference['close'])) / 2.0
    if reference_colour == 'green' and first_colour == 'red':
        # First red close was insufficient; second red close must qualify.
        if float(first['close']) < midpoint or float(second['close']) >= midpoint:
            return None
        direction = 'bearish'
        penetration = (float(reference['close']) - float(second['close'])) / body * 100.0
    elif reference_colour == 'red' and first_colour == 'green':
        if float(first['close']) > midpoint or float(second['close']) <= midpoint:
            return None
        direction = 'bullish'
        penetration = (float(second['close']) - float(reference['close'])) / body * 100.0
    else:
        return None
    if penetration < 50.0:
        return None
    return {
        'direction': direction, 'index': i, 'penetration': penetration,
        'date': second.get('datetime', ''), 'close': float(second['close']),
        'previous_midpoint': midpoint, 'retest_candle_index': i - 2,
        'crypto_second_candle': True,
    }


def recent_sr_confirmations(candles, lookback=7, grp="FOREX"):
    """Newest-first 50% confirmations used ONLY for S/R gap-and-retest."""
    found = []
    first = max(1, len(candles) - lookback)

    for i in range(first, len(candles)):
        c = sr_confirmation_at(candles, i)
        if c is None and str(grp).upper() == "CRYPTO":
            c = crypto_second_candle_sr_confirmation(candles, i)
        if c:
            found.append(c)

    return list(reversed(found))


def recent_confirmations(candles, lookback=6):
    found = []
    first = max(1, len(candles) - lookback)

    for i in range(first, len(candles)):
        c = confirmation_at(candles, i)
        if c:
            found.append(c)

    # Newest first.
    return list(reversed(found))


def local_structure_trend(candles, end_index):
    """
    Edo recent price-structure direction BEFORE the pullback.

    Important: an older large move must not keep controlling the trend after
    price has established a genuine newer structure change.  Confirmed recent
    swing highs/lows therefore have priority over the older-window close move.
    No EMA/RSI is used.
    """
    if end_index < 12:
        return "mixed"

    # Use enough history to confirm structural swings, but judge direction from
    # the NEWEST confirmed swing pair.  This lets HH+HL / LH+LL establish a new
    # regime even when an older impulse in the same window was very large.
    start = max(0, end_index - 36)
    part = candles[start:end_index]
    if len(part) < 10:
        return "mixed"

    highs = swing_points(part, "high")
    lows = swing_points(part, "low")

    hh = len(highs) >= 2 and highs[-1][1] > highs[-2][1]
    hl = len(lows) >= 2 and lows[-1][1] > lows[-2][1]
    lh = len(highs) >= 2 and highs[-1][1] < highs[-2][1]
    ll = len(lows) >= 2 and lows[-1][1] < lows[-2][1]

    # Strongest evidence: the latest confirmed highs AND lows agree.
    if hh and hl:
        return "bullish"
    if lh and ll:
        return "bearish"

    # If only one side has printed a newer swing, do not fall back to the old
    # 28-candle impulse.  Use only recent price progress as supporting evidence.
    recent = part[-14:]
    first_n = min(3, max(1, len(recent) // 3))
    first_close = sum(c["close"] for c in recent[:first_n]) / first_n
    last_close = sum(c["close"] for c in recent[-first_n:]) / first_n
    recent_move = last_close - first_close
    recent_range = avg_range(recent, end=len(recent), length=len(recent))
    meaningful = max(recent_range * 1.25, abs(first_close) * 0.0015)

    # One matching structural swing + meaningful recent progress is enough to
    # recognise an established change; contradictory swing evidence stays MIXED.
    if recent_move > meaningful and (hh or hl) and not (lh or ll):
        return "bullish"
    if recent_move < -meaningful and (lh or ll) and not (hh or hl):
        return "bearish"

    return "mixed"



def trend_pullback_structure_trend(candles, end_index):
    """
    Trend direction used ONLY by the normal TREND PULLBACK detector.

    Purpose: identify the dominant RECENT structure before the pullback starts,
    without letting an old large impulse dominate after market structure has
    genuinely changed.  No EMA/RSI and no changes to other EdoSignal signals.

    Evidence is deliberately recent and layered:
      1) newest confirmed swing highs/lows (HH+HL or LH+LL),
      2) directional progress across 12/20/28-candle windows,
      3) conflicting evidence returns MIXED rather than forcing a direction.
    """
    if end_index < 12:
        return "mixed"

    history = candles[:end_index]
    if len(history) < 12:
        return "mixed"

    # Structural vote from the newest confirmed swings.  Use at most the last
    # 28 pre-pullback candles so a much older trend cannot control a new regime.
    structural = history[-28:]
    highs = swing_points(structural, "high", left=2, right=2)
    lows = swing_points(structural, "low", left=2, right=2)

    swing_vote = None
    if len(highs) >= 2 and len(lows) >= 2:
        hh = highs[-1][1] > highs[-2][1]
        hl = lows[-1][1] > lows[-2][1]
        lh = highs[-1][1] < highs[-2][1]
        ll = lows[-1][1] < lows[-2][1]
        if hh and hl:
            swing_vote = "bullish"
        elif lh and ll:
            swing_vote = "bearish"

    # Recent-progress votes.  Averaging three closes at each end reduces the
    # chance that one spike/wick or one unusually large candle flips the trend.
    progress_votes = []
    for n in (12, 20, 28):
        if len(history) < n:
            continue
        part = history[-n:]
        first = sum(float(c["close"]) for c in part[:3]) / 3.0
        last = sum(float(c["close"]) for c in part[-3:]) / 3.0
        move = last - first
        ar = avg_range(part, end=len(part), length=len(part))
        threshold = max(ar * 1.10, abs(first) * 0.0010)
        if move > threshold:
            progress_votes.append("bullish")
        elif move < -threshold:
            progress_votes.append("bearish")

    bulls = progress_votes.count("bullish")
    bears = progress_votes.count("bearish")

    # Recent-regime override for Trend Pullback only.  A strong fresh move can
    # establish a new trend before the slower 20/28-candle swing structure has
    # fully caught up.  This prevents an older bearish/bullish leg from causing
    # a pullback alert in the wrong direction after a clear reversal.
    recent_n = min(12, len(history))
    recent = history[-recent_n:]
    if len(recent) >= 8:
        k = min(3, max(2, len(recent) // 4))
        first_recent = sum(float(c["close"]) for c in recent[:k]) / k
        last_recent = sum(float(c["close"]) for c in recent[-k:]) / k
        recent_move = last_recent - first_recent
        recent_ar = avg_range(recent, end=len(recent), length=len(recent))
        strong_move = max(recent_ar * 2.25, abs(first_recent) * 0.0015)

        up_steps = sum(
            1 for j in range(1, len(recent))
            if float(recent[j]["close"]) > float(recent[j-1]["close"])
        )
        down_steps = sum(
            1 for j in range(1, len(recent))
            if float(recent[j]["close"]) < float(recent[j-1]["close"])
        )
        step_need = max(4, (len(recent) - 1) // 2 + 1)

        # Require both substantial displacement and a majority of progressing
        # closes, so one oversized candle alone cannot flip the trend.
        if recent_move > strong_move and up_steps >= step_need and up_steps > down_steps:
            return "bullish"
        if recent_move < -strong_move and down_steps >= step_need and down_steps > up_steps:
            return "bearish"

    # A confirmed newest HH+HL / LH+LL has priority unless recent price
    # progress clearly contradicts it in at least two windows.
    if swing_vote == "bullish" and bears < 2:
        return "bullish"
    if swing_vote == "bearish" and bulls < 2:
        return "bearish"

    # Without a complete swing pair, require agreement from at least two recent
    # windows.  Otherwise stay MIXED and suppress the Trend Pullback signal.
    if bulls >= 2 and bears == 0:
        return "bullish"
    if bears >= 2 and bulls == 0:
        return "bearish"

    return "mixed"

def previous_target(candles, direction, before_index, search_back=60):
    """
    BUY target = previous significant swing high.
    SELL target = previous significant swing low.
    """
    start = max(0, before_index - search_back)
    part = candles[start:before_index+1]
    if len(part) < 5:
        return None

    if direction == "bullish":
        pts = swing_points(part, "high")
        if pts:
            candidates = [p[1] for p in pts]
            above = [v for v in candidates if v > candles[before_index]["close"]]
            if above:
                return min(above)
            return max(candidates)
    else:
        pts = swing_points(part, "low")
        if pts:
            candidates = [p[1] for p in pts]
            below = [v for v in candidates if v < candles[before_index]["close"]]
            if below:
                return max(below)
            return min(candidates)

    return None


def sr_structure_targets(candles, direction, before_index, entry_price, search_back=80, min_separation=None):
    """
    Edo S/R Gap-Retest targets ONLY.

    Preferred method (Edo rule):
      Target 1 = nearest MEANINGFUL previous swing in the trade direction.
      Take Profit = the NEXT meaningful structural swing beyond Target 1.

    Important: do not jump to an ancient/extreme high or low when two nearer,
    clear swing points exist. Minor one-candle noise is filtered out by using
    wider swing confirmation and a minimum prominence/distance test.

    If price history does not provide clean structural levels, the caller may
    add calculated fallback targets from the setup's own move-away distance.
    These targets are NOT used for Trend Pullback or Weekly Spike.
    """
    start = max(0, before_index - search_back)
    part = candles[start:before_index + 1]
    if len(part) < 7:
        return None, None

    entry = float(entry_price)
    local_ar = avg_range(candles, before_index + 1, 20)
    local_ar = max(float(local_ar or 0.0), abs(entry) * 0.0005)

    if min_separation is None:
        # Keep T1/TP meaningfully separated from each other.
        min_separation = max(local_ar * 0.75, abs(entry) * 0.0005)

    # Wider pivot width removes many small noisy swings that Edo would not use
    # visually as a target.  A swing must also stand out from nearby candles.
    def meaningful_points(kind):
        pts = swing_points(part, kind, left=3, right=3)
        out = []
        key = "high" if kind == "high" else "low"
        for i, value in pts:
            v = float(value)
            lo = max(0, i - 3)
            hi = min(len(part), i + 4)
            nearby = part[lo:hi]
            if not nearby:
                continue
            if kind == "high":
                base = min(float(c["low"]) for c in nearby)
                prominence = v - base
            else:
                cap = max(float(c["high"]) for c in nearby)
                prominence = cap - v
            if prominence >= local_ar * 0.70:
                out.append((i, v))
        return out

    if direction == "bullish":
        pts = meaningful_points("high")
        # Ignore tiny nearby levels. Edo wants the first proper structural high.
        min_target_distance = max(local_ar * 1.00, abs(entry) * 0.00075)
        levels = sorted({v for _, v in pts if v >= entry + min_target_distance})
        if not levels:
            return None, None
        target1 = levels[0]
        farther = [v for v in levels[1:] if v >= target1 + min_separation]
        # Take Profit is the NEXT meaningful level, not the farthest old extreme.
        take_profit = farther[0] if farther else None
        return target1, take_profit

    pts = meaningful_points("low")
    min_target_distance = max(local_ar * 1.00, abs(entry) * 0.00075)
    levels = sorted({v for _, v in pts if v <= entry - min_target_distance}, reverse=True)
    if not levels:
        return None, None
    target1 = levels[0]
    farther = [v for v in levels[1:] if v <= target1 - min_separation]
    take_profit = farther[0] if farther else None
    return target1, take_profit


def sr_calculated_targets(direction, entry_price, zone_centre, departure_extreme, local_ar):
    """Fallback targets for S/R Gap-Retest when structure is unclear.

    They are based only on price action from the current setup:
      * the distance price previously travelled away from the S/R zone, and
      * recent average candle range as a minimum practical distance.

    Target 1 is conservative; Take Profit is the fuller measured-move target.
    """
    entry = float(entry_price)
    zone = float(zone_centre)
    departure = float(departure_extreme)
    ar = max(float(local_ar or 0.0), abs(entry) * 0.0005)

    if direction == "bullish":
        setup_move = max(departure - zone, ar * 2.0)
        t1_dist = max(setup_move * 0.50, ar * 1.50)
        tp_dist = max(setup_move * 0.90, ar * 3.00)
        target1 = entry + t1_dist
        take_profit = entry + tp_dist
    else:
        setup_move = max(zone - departure, ar * 2.0)
        t1_dist = max(setup_move * 0.50, ar * 1.50)
        tp_dist = max(setup_move * 0.90, ar * 3.00)
        target1 = entry - t1_dist
        take_profit = entry - tp_dist

    # Always keep Take Profit meaningfully farther than Target 1.
    min_gap = max(ar * 0.75, abs(entry) * 0.0005)
    if direction == "bullish" and take_profit < target1 + min_gap:
        take_profit = target1 + min_gap
    elif direction == "bearish" and take_profit > target1 - min_gap:
        take_profit = target1 - min_gap

    return target1, take_profit


def sr_gap_structure_is_messy(candles, old_i, retest_index, zone_centre, ar, direction):
    """Return True when an S/R gap-retest is too choppy to trust on this timeframe.

    Edo rule: if the gap/separation is messy, do not force a lower-timeframe
    signal. Let the normal higher-timeframe scanners (8H -> Daily -> Weekly)
    look for the same structure in a cleaner form.

    A clean separation should:
      * establish a run of candles clearly away from the S/R zone, and
      * avoid choppy back-and-forth CLOSING through the zone.

    IMPORTANT — repeated clean tests are allowed. The same meaningful S/R
    level may be tested a 2nd, 3rd, 4th (or later) time. Earlier failed
    confirmations do NOT invalidate the level. A later retest can signal if
    its newest fully closed opposite-colour confirmation satisfies Edo's 50%
    body rule and still leaves room to the nearest structural target.
    """
    if retest_index - old_i < 8 or ar <= 0:
        return True

    # Ignore the candles immediately surrounding the original touch and the
    # final retest. We are judging the quality of the separation in between.
    start = old_i + 2
    end = max(start, retest_index - 2)
    middle = candles[start:end]
    if len(middle) < 4:
        return True

    away_distance = ar * 0.55
    zone_band = ar * 0.45

    # Require at least three consecutive closes clearly away from the zone.
    best_run = run = 0
    for c in middle:
        close = float(c["close"])
        if direction == "bullish":
            away = close >= zone_centre + away_distance
        else:
            away = close <= zone_centre - away_distance
        if away:
            run += 1
            best_run = max(best_run, run)
        else:
            run = 0

    if best_run < 3:
        return True

    # After price has clearly departed, repeated CLEAN returns to the same
    # zone are valid in Edo's method (2nd / 3rd / 4th+ tests). We therefore
    # track revisit clusters for diagnostics only; we do NOT reject a setup
    # merely because the level has been touched several times. What makes the
    # structure messy is repeated CLOSES flipping through the level.
    departed = False
    revisit_clusters = 0
    in_revisit = False
    side_flips = 0
    previous_side = None

    for c in middle:
        close = float(c["close"])
        low = float(c["low"])
        high = float(c["high"])

        if direction == "bullish":
            clearly_away = close >= zone_centre + away_distance
        else:
            clearly_away = close <= zone_centre - away_distance

        if clearly_away:
            departed = True

        if not departed:
            continue

        overlaps_zone = low <= zone_centre + zone_band and high >= zone_centre - zone_band
        if overlaps_zone and not in_revisit:
            revisit_clusters += 1
            in_revisit = True
        elif not overlaps_zone:
            in_revisit = False

        if close > zone_centre + zone_band:
            side = 1
        elif close < zone_centre - zone_band:
            side = -1
        else:
            side = 0

        if side and previous_side and side != previous_side:
            side_flips += 1
        if side:
            previous_side = side

    # Repeated tests are valid only when they are genuinely SEPARATE tests.
    # Edo does not want a cluster of candles hanging around the level to be
    # called a clean Gap-Retest.  Between one revisit and the next there must
    # be another clean departure (minimum three consecutive closes clearly
    # away from the zone).  This rejects range/congestion such as several
    # candles repeatedly probing the same resistance/support without a fresh
    # move-away in between.
    post_departure = []
    seen_departure = False
    for c in middle:
        close = float(c["close"])
        low = float(c["low"])
        high = float(c["high"])
        if direction == "bullish":
            clearly_away = close >= zone_centre + away_distance
        else:
            clearly_away = close <= zone_centre - away_distance
        if clearly_away:
            seen_departure = True
        if seen_departure:
            post_departure.append((clearly_away, low <= zone_centre + zone_band and high >= zone_centre - zone_band))

    # Build revisit clusters and count the longest clean-away run separating
    # neighbouring clusters. A later 3rd/4th test is still allowed, but only
    # after price has clearly left the level again.
    clusters = []
    in_cluster = False
    for idx, (_away, overlaps) in enumerate(post_departure):
        if overlaps and not in_cluster:
            clusters.append([idx, idx])
            in_cluster = True
        elif overlaps and in_cluster:
            clusters[-1][1] = idx
        elif not overlaps:
            in_cluster = False

    # Too many candles living in/around the zone is congestion, not a gap.
    zone_candles = sum(1 for _away, overlaps in post_departure if overlaps)
    if post_departure and zone_candles / len(post_departure) > 0.38:
        return True
    if any((b - a + 1) >= 3 for a, b in clusters):
        return True

    # Every repeated revisit must have a fresh 3-close departure between it
    # and the previous revisit. This preserves Edo's valid 2nd/3rd/4th-test
    # rule while rejecting one prolonged choppy test.
    for n in range(1, len(clusters)):
        prev_end = clusters[n - 1][1]
        next_start = clusters[n][0]
        best_sep = run_sep = 0
        for away, _overlaps in post_departure[prev_end + 1:next_start]:
            if away:
                run_sep += 1
                best_sep = max(best_sep, run_sep)
            else:
                run_sep = 0
        if best_sep < 3:
            return True

    # Edo clean-gap filter: evaluate the whole intervening structure, not
    # just the two touches.  Multiple long two-sided tails and overlapping
    # bodies in a short cluster indicate indecision/range rather than a clean
    # move-away and retest.  One isolated rejection wick is acceptable.
    # Normalise by each candle's range and the timeframe's average range so
    # this behaves consistently on 8H/12H/Daily/Weekly and across assets.
    noisy_flags = []
    overlap_flags = []
    for k, c in enumerate(middle):
        op = float(c["open"])
        cl = float(c["close"])
        hi = float(c["high"])
        lo = float(c["low"])
        span = max(hi - lo, 1e-12)
        body = abs(cl - op)
        upper = max(0.0, hi - max(op, cl))
        lower = max(0.0, min(op, cl) - lo)
        # Reject clusters of large tails on BOTH ends; isolated long
        # rejection tails are deliberately not penalised on their own.
        two_sided_wicks = (upper >= span * 0.22 and lower >= span * 0.22)
        wick_dominated = (upper + lower >= span * 0.65 and span >= ar * 0.55)
        noisy_flags.append(two_sided_wicks or wick_dominated)
        if k:
            prev = middle[k - 1]
            prev_lo = min(float(prev["open"]), float(prev["close"]))
            prev_hi = max(float(prev["open"]), float(prev["close"]))
            body_lo = min(op, cl)
            body_hi = max(op, cl)
            overlap = max(0.0, min(body_hi, prev_hi) - max(body_lo, prev_lo))
            smaller_body = min(body, prev_hi - prev_lo)
            overlap_flags.append(smaller_body > ar * 0.10 and overlap >= smaller_body * 0.55)

    if len(noisy_flags) >= 5:
        for k in range(len(noisy_flags) - 4):
            if sum(noisy_flags[k:k + 5]) >= 3:
                return True
    if len(noisy_flags) >= 7 and sum(noisy_flags) / len(noisy_flags) >= 0.42:
        return True
    # A cluster of overlapping bodies is only disqualifying when it also
    # contains several wick-heavy candles: normal orderly pullbacks remain OK.
    if len(overlap_flags) >= 5:
        for k in range(len(overlap_flags) - 4):
            if sum(overlap_flags[k:k + 5]) >= 4 and sum(noisy_flags[k:k + 6]) >= 2:
                return True

    # Genuine back-and-forth closes through the level are also congestion.
    # A rejected 8H setup remains eligible to be found independently on
    # Daily, and a rejected Daily setup remains eligible on Weekly.
    return side_flips >= 3


# User-defined minimum depth for horizontal BUY and SELL Gap Retests.
# Retrace at least half the previous swing-low-to-high (or high-to-low) move.
# Keep separate from the 65% closed-candle body confirmation rule.
SR_HORIZONTAL_GAP_RETEST_MIN_DEPTH_PCT = 50.0


def detect_bounce_retest(candles, conf):
    """
    Edo S/R Gap-and-Retest trading rule.

    IMPORTANT:
      * If the lower-timeframe gap/separation is too messy, reject it on that
        timeframe and let the next higher scanner (8H -> Daily -> Weekly)
        provide the cleaner structural signal instead.
      * Historical HIGH = RESISTANCE only -> bearish/SELL confirmation only.
      * Historical LOW  = SUPPORT only    -> bullish/BUY confirmation only.
      * Retest must enter the 50%-to-100% area of the previous swing move;
        it does not need to touch the original level. A small move beyond the
        old level is allowed, but a large break is rejected.
      * Horizontal support BUY and resistance SELL retests require a fully
        closed opposite-colour candle penetrating at least 65% of the previous
        candle body. Other signal families retain their existing rules.
      * The same S/R level may be tested repeatedly (2nd / 3rd / 4th+). A
        failed earlier test does not retire the level; a later fully closed
        confirmation may qualify when all Gap-Retest rules are satisfied.
      * Reject the setup if the confirmation candle itself has already shot
        to/near the previous structural target (old high for BUY, old low for
        SELL). There must still be useful room after confirmation.

    These 50% rules apply ONLY to this S/R setup. They are not used by the
    normal minimum-2-candle Trend Pullback setup.
    """
    i = conf["index"]
    direction = conf["direction"]

    if i < 16:
        return None

    ar = avg_range(candles, i + 1, 20)
    if ar <= 0:
        return None

    # Edo near-level rule for BOTH horizontal support BUY and resistance SELL:
    # the fully closed opposite-colour candle must recover/reject at least 65%
    # of the preceding candle body. Diagonal, pullback and Star rules are unchanged.
    if float(conf.get("penetration", 0.0)) < 65.0:
        return None

    # The second touch must be immediately before/around the confirmation.
    touch_start = max(3, i - (5 if conf.get("crypto_second_candle") else 4))
    touch_end = i + 1
    touch_slice = candles[touch_start:touch_end]
    if not touch_slice:
        return None

    if direction == "bullish":
        # BUY can come ONLY from established SUPPORT (historical swing LOW).
        rel_touch_i = min(range(len(touch_slice)), key=lambda k: touch_slice[k]["low"])
        retest_price = float(touch_slice[rel_touch_i]["low"])
        retest_index = touch_start + rel_touch_i
        swings = swing_points(candles[:touch_start], "low")
        level_source = "historical swing low / support"
        confirm_close = float(candles[i]["close"])
        confirm_extreme = float(candles[i]["high"])
    else:
        # SELL can come ONLY from established RESISTANCE (historical swing HIGH).
        rel_touch_i = max(range(len(touch_slice)), key=lambda k: touch_slice[k]["high"])
        retest_price = float(touch_slice[rel_touch_i]["high"])
        retest_index = touch_start + rel_touch_i
        swings = swing_points(candles[:touch_start], "high")
        level_source = "historical swing high / resistance"
        confirm_close = float(candles[i]["close"])
        confirm_extreme = float(candles[i]["low"])

    # Both directions accept a retest inside the LOWER/UPPER HALF of the
    # previous swing move (50%-100% depth), with a limited overshoot beyond
    # the old swing price. No exact level touch is needed.
    # Existing clean-gap/spike, move-away, depth and target filters still apply.
    zone_tolerance = max(ar * 0.90, abs(retest_price) * 0.0030)

    candidates = []

    for old_i, old_price in swings:
        old_price = float(old_price)
        separation = touch_start - old_i

        if separation < 8 or separation > 120:
            continue

        # Edo's chart-demonstrated retest AREA is the second half of the
        # preceding swing move: from its 50% retracement to the original swing
        # support (BUY) or resistance (SELL). The retest need NOT reach the
        # original price exactly. A modest overshoot beyond the original
        # level is acceptable, but a materially deeper break is not.
        # The minimum 50% depth is verified against the actual departure
        # extreme below, independently of the 65% candle-body confirmation.
        if direction == "bullish" and retest_price < old_price - zone_tolerance:
            continue
        if direction == "bearish" and retest_price > old_price + zone_tolerance:
            continue

        # Original level must be a meaningful swing extreme, not a minor pivot.
        left = max(0, old_i - 6)
        right = min(touch_start, old_i + 7)
        neighbourhood = candles[left:right]
        if len(neighbourhood) < 5:
            continue

        if direction == "bullish":
            neighbourhood_extreme = min(float(c["low"]) for c in neighbourhood)
            if old_price > neighbourhood_extreme + ar * 0.15:
                continue
        else:
            neighbourhood_extreme = max(float(c["high"]) for c in neighbourhood)
            if old_price < neighbourhood_extreme - ar * 0.15:
                continue

        between = candles[old_i + 1:retest_index]
        if not between:
            continue

        # Price must first move materially AWAY from the old swing level.
        # Then the retest must enter the 50%-to-100% retracement area. A full
        # return or small overshoot beyond the old swing is allowed; a shallow
        # retracement or excessive level break is not.
        if direction == "bullish":
            departure_extreme = max(float(c["high"]) for c in between)
            move_distance = departure_extreme - old_price
            moved_away = move_distance
            if move_distance < ar * 2.0:
                continue
            retest_depth_pct = ((departure_extreme - retest_price) / move_distance) * 100.0
        else:
            departure_extreme = min(float(c["low"]) for c in between)
            move_distance = old_price - departure_extreme
            moved_away = move_distance
            if move_distance < ar * 2.0:
                continue
            retest_depth_pct = ((retest_price - departure_extreme) / move_distance) * 100.0

        if retest_depth_pct < SR_HORIZONTAL_GAP_RETEST_MIN_DEPTH_PCT:
            continue

        zone_centre = (old_price + retest_price) / 2.0

        # Edo higher-timeframe clarity rule: if this timeframe is too choppy,
        # do not force a gap-retest signal here. The 8H, Daily and Weekly
        # scanners already run independently, so the setup can be recognised
        # on the next higher timeframe when its structure is cleaner.
        if sr_gap_structure_is_messy(
            candles, old_i, retest_index, zone_centre, ar, direction
        ):
            continue

        # Before the second touch, price must approach the level from the
        # correct side, then confirmation must close back away from the zone.
        approach_start = max(old_i + 1, retest_index - 4)
        approach = candles[approach_start:retest_index]
        if not approach:
            continue

        if direction == "bullish":
            if max(float(c["close"]) for c in approach) <= zone_centre + ar * 0.20:
                continue
            if confirm_close <= zone_centre:
                continue
        else:
            if min(float(c["close"]) for c in approach) >= zone_centre - ar * 0.20:
                continue
            if confirm_close >= zone_centre:
                continue

        # Confirmation must not consume the whole trade in one candle.
        # For Edo's S/R Gap-Retest ONLY, calculate two structure targets:
        # T1 = nearest previous swing; Take Profit = farther major swing.
        target1, take_profit = sr_structure_targets(
            candles, direction, retest_index, confirm_close, search_back=120
        )
        target1_source = "structural" if target1 is not None else None
        take_profit_source = "structural" if take_profit is not None else None

        # Edo rule: Gap-Retest targets must come from real previous swing
        # structure only. Never invent/calculates a target when the chart does
        # not provide a meaningful swing level. Target 1 may be absent, and
        # Take Profit may be absent when there is no second valid swing.
        target_near_tol = ar * 0.35
        if target1 is not None:
            target1 = float(target1)
        if target1 is not None:
            if direction == "bullish":
                if target1 > zone_centre and confirm_extreme >= target1 - target_near_tol:
                    continue
            else:
                if target1 < zone_centre and confirm_extreme <= target1 + target_near_tol:
                    continue

        if take_profit is not None:
            take_profit = float(take_profit)

        closeness = 1.0 - min(1.0, abs(old_price - retest_price) / zone_tolerance)
        candidates.append((
            old_i, old_price, separation, closeness, moved_away,
            zone_centre, retest_depth_pct, departure_extreme, target1, take_profit
        ))

    if not candidates:
        return None

    (
        old_i, old_price, separation, closeness, moved_away,
        zone_centre, retest_depth_pct, departure_extreme, target1, take_profit
    ) = min(
        candidates,
        # Edo rule: use the CLOSEST valid previous structural S/R level.
        # BUY  -> closest qualifying historical swing LOW / support.
        # SELL -> closest qualifying historical swing HIGH / resistance.
        # If two levels are effectively equally close in price, prefer the
        # most recent structural swing rather than an older level.
        key=lambda x: (abs(float(x[1]) - float(retest_price)), -int(x[0]))
    )

    score = 6.0
    score += min(3.0, separation / 15.0)
    score += closeness * 2.0
    score += min(2.0, max(0.0, conf["penetration"] - 50.0) / 25.0)
    score += min(1.5, max(0.0, retest_depth_pct - 50.0) / 35.0)

    return {
        "name": "S/R GAP RETEST SETUP",
        "direction": direction,
        "confirmed": True,
        "score": score,
        "confirmation_date": conf["date"],
        "confirmation_close": conf["close"],
        "penetration": conf["penetration"],
        "retest_depth_pct": retest_depth_pct,
        "departure_extreme": departure_extreme,
        "level": zone_centre,
        "old_level": old_price,
        "retest_price": retest_price,
        "retest_date": candles[retest_index].get("datetime", ""),
        "level_source": level_source,
        "old_date": candles[old_i].get("datetime", ""),
        "separation": separation,
        "weak_retest": False,
        # Targets belong ONLY to S/R Gap-Retest.
        "target": target1,  # backward-compatible alias for Target 1
        "target1": target1,
        "target1_source": target1_source,
        "take_profit": take_profit,
        "take_profit_source": take_profit_source,
    }

def add_turning_point_gap_strength(candles, setup, interval):
    """Non-blocking confluence information for existing valid D1/W1 retests.

    Uses only historical, right-confirmed swing points preceding the retest.
    Never changes whether a setup meets Edo's existing confirmation rules.
    """
    if not setup or interval not in ("1day", "1week") or setup.get("name") != "S/R GAP RETEST SETUP":
        return setup
    setup = dict(setup)
    if setup.get("diagonal"):
        # The diagonal detector already counts historical anchors plus the new
        # retest; do not overwrite its STRONG / VERY STRONG label.
        return setup
    retest_time = parse_candle_utc(setup.get("retest_date"))
    limit = len(candles) - 4
    if retest_time is not None:
        for idx, c in enumerate(candles):
            dt = parse_candle_utc(c.get("datetime"))
            if dt is not None and dt >= retest_time:
                limit = min(limit, idx - 3)
                break
    history = candles[:max(0, limit)]
    if len(history) < 15:
        return setup
    kind = "low" if setup.get("direction") == "bullish" else "high"
    pivots = swing_points(history, kind, left=2, right=2)
    average = avg_range(history, end=len(history), length=min(20, len(history)))
    if average <= 0:
        return setup
    level = float(setup["level"])
    tolerance = average * 0.5
    matches = [(i, float(v)) for i,v in pivots if abs(float(v)-level) <= tolerance]
    # Count independent turning points, not neighbouring candle noise.
    separated=[]
    for point in matches:
        if not separated or point[0]-separated[-1][0]>=4:
            separated.append(point)
    if len(separated) >= 2:
        # The current confirmed retest is a further touch of the established level.
        touch_count = len(separated) + 1
        strength = "VERY STRONG" if touch_count >= 4 else "STRONG"
        setup["turning_point_strength"] = (
            f"{strength}: {touch_count} independent touches including current retest "
            f"support this {kind} / horizontal level (tolerance {tolerance:.5f})"
        )
        setup["strength_turning_points"] = [
            {"date":history[i].get("datetime",""), "price":val}
            for i,val in separated[-3:]
        ]
    return setup


# Independent Morning / Evening Star and single-candle rejection signals.
# These do not alter the separate Gap Retest or Trend Pullback detectors.
STAR_PATTERN_INTERVALS = frozenset({"3h", "4h", "1day", "1week"})
STAR_PATTERN_NAMES = frozenset({"MORNING STAR SETUP", "EVENING STAR SETUP",
                                "HAMMER REVERSAL SETUP", "SHOOTING STAR SETUP"})


def detect_trendline_star(candles, i):
    """Recognise a closed bullish/bearish star/rejection at a confirmed 3rd+ line touch.

    Two established, separated and chronologically confirmed swing anchors make
    the trendline. The current reversal test is touch three; earlier independent
    aligned contacts can raise it to VERY STRONG. Follow the pre-event market
    structure: bearish resistance sells, bullish support buys, range either.
    """
    if i < 35 or i >= len(candles):
        return None
    ar = avg_range(candles, i, 20)
    if ar <= 0:
        return None

    first = second = None
    pattern = None
    test_idx = i
    confirmed = candles[i]
    current_colour = candle_colour(confirmed)
    # The traditional three-candle Morning/Evening Star.
    if i >= 2:
        first, middle, third = candles[i-2:i+1]
        first_body = abs(float(first['close'])-float(first['open']))
        middle_body = abs(float(middle['close'])-float(middle['open']))
        third_body = abs(float(third['close'])-float(third['open']))
        midpoint = (float(first['open'])+float(first['close']))/2
        small_middle = middle_body <= max(first_body*.45, ar*.25)
        strong_first = first_body >= ar*.50
        if (candle_colour(first)=='red' and current_colour=='green' and
            strong_first and small_middle and third_body >= ar*.40 and
            float(third['close'])>midpoint):
            pattern = ('MORNING STAR SETUP','bullish')
            test_idx = i-1
        elif (candle_colour(first)=='green' and current_colour=='red' and
              strong_first and small_middle and third_body >= ar*.40 and
              float(third['close'])<midpoint):
            pattern = ('EVENING STAR SETUP','bearish')
            test_idx = i-1

    # Alternative closed-candle confirmation: a hammer/shooting star is followed
    # by a full closed candle in its rejection direction (as in Edo's screenshot).
    if pattern is None and i >= 1:
        rejection = candles[i-1]
        rbody = abs(float(rejection['close'])-float(rejection['open']))
        rbody = max(rbody, ar*.035)  # avoid zero-body division/false positives
        upper = float(rejection['high'])-max(float(rejection['open']),float(rejection['close']))
        lower = min(float(rejection['open']),float(rejection['close']))-float(rejection['low'])
        midpoint = (float(rejection['open'])+float(rejection['close']))/2
        if (upper >= max(rbody*2,ar*.45) and lower <= max(rbody*.7,ar*.18)
            and current_colour=='red' and float(confirmed['close'])<midpoint):
            pattern=('SHOOTING STAR SETUP','bearish')
            test_idx=i-1
        elif (lower >= max(rbody*2,ar*.45) and upper <= max(rbody*.7,ar*.18)
              and current_colour=='green' and float(confirmed['close'])>midpoint):
            pattern=('HAMMER REVERSAL SETUP','bullish')
            test_idx=i-1
    if pattern is None:
        return None
    name,direction=pattern
    trend=local_structure_trend(candles,test_idx)
    if trend in ('bullish','bearish') and direction != trend:
        return None
    kind='low' if direction=='bullish' else 'high'
    # Right-side confirmation of each pivot must precede the reaction candle.
    pivots=swing_points(candles[:max(0,test_idx-5)],kind,left=3,right=3)
    pivots=[(j,float(v)) for j,v in pivots if test_idx-110 <= j <= test_idx-8]
    if len(pivots)<2:
        return None
    candidates=[]
    for bp in range(len(pivots)-1,0,-1):
        b,vb=pivots[bp]
        for ap in range(bp-1,-1,-1):
            a,va=pivots[ap]
            if b-a<10 or test_idx-b>42:
                continue
            slope=(vb-va)/(b-a)
            tolerance=ar*.55
            # A resistance line can't be repeatedly violated before a sell,
            # or support repeatedly violated before a buy.
            anchors=[(a,va)]
            invalid=False
            for j,v in pivots[ap+1:bp+1]:
                expected=va+slope*(j-a)
                if abs(v-expected)>tolerance:
                    invalid=True;break
                if j-anchors[-1][0]>=5:
                    anchors.append((j,v))
            if invalid or len(anchors)<2 or anchors[-1][0]!=b:
                continue
            test_line=va+slope*(test_idx-a)
            wick=float(candles[test_idx][kind])
            if test_line<=0 or abs(wick-test_line)>tolerance:
                continue
            # Reject candles that close decisively through the opposite side.
            projection=va+slope*(i-a)
            close=float(confirmed['close'])
            if direction=='bullish' and close<projection-ar*.12:
                continue
            if direction=='bearish' and close>projection+ar*.12:
                continue
            broken=False
            for j in range(b+1,test_idx):
                projected=va+slope*(j-a)
                price=float(candles[j]['close'])
                if direction=='bullish' and price<projected-ar*.7:
                    broken=True;break
                if direction=='bearish' and price>projected+ar*.7:
                    broken=True;break
            if broken:
                continue
            # Distinct departure required before a fresh touch.
            departure=[(float(candles[j]['close'])-(va+slope*(j-a))) *
                       (1 if direction=='bullish' else -1)
                       for j in range(b+1,test_idx)]
            if not departure or max(departure)<ar*.8:
                continue
            touches=len(anchors)+1
            score=7+min(2,touches*.45)+min(1,(test_idx-b)/35)
            candidates.append((score,touches,anchors,a,va,test_line,wick))
    if not candidates:
        return None
    score,touches,anchors,a,va,level,wick=max(candidates,key=lambda x:(x[0],x[1]))
    t1,tp=sr_structure_targets(candles,direction,test_idx,float(confirmed['close']),search_back=110)
    return {
        'name':name, 'direction':direction, 'confirmed':True,
        'score':score,'confirmation_date':confirmed.get('datetime',''),
        'confirmation_close':float(confirmed['close']),
        'retest_date':candles[test_idx].get('datetime',''),
        'retest_price':wick,'level':level,
        'trendline_touches':touches,
        'turning_point_strength':'VERY STRONG' if touches>=4 else 'STRONG',
        'trendline_touch_points':[{'date':candles[j].get('datetime',''),'price':v}
                                  for j,v in anchors],
        'trendline_type':'support' if direction=='bullish' else 'resistance',
        'target1':t1,'take_profit':tp,
        'trend_at_retest':trend,
    }


def detect_diagonal_gap_retest(candles, conf):
    """Edo diagonal retest: TWO established pivots define a valid line.

    A subsequent confirmed retest is touch 3 (STRONG); 4+ independent
    touches are VERY STRONG. Preserves departure, clean-line, target and
    closed opposite-candle 50%-body confirmation restrictions.
    """
    i = conf["index"]
    direction = conf["direction"]
    if i < 35:
        return None
    ar = avg_range(candles, i + 1, 20)
    if ar <= 0:
        return None
    kind = "low" if direction == "bullish" else "high"
    pivots = swing_points(candles[:max(0, i - 5)], kind, left=3, right=3)
    pivots = [(j, float(v)) for j, v in pivots if i - 105 <= j <= i - 8]
    if len(pivots) < 2:
        return None

    candidates = []
    # Construct the line only from confirmed points before the retest.
    # Two prior pivots define it; other aligned independent pivots strengthen it.
    for bp in range(len(pivots)-1, 0, -1):
        b, vb = pivots[bp]
        for ap in range(bp-1, -1, -1):
            a, va = pivots[ap]
            if b-a < 10 or i-b > 32:
                continue
            slope = (vb-va)/(b-a)
            if abs(slope)*(b-a) < ar*0.8:
                continue  # horizontal detector retains horizontal/double-top/bottom
            tolerance = ar*0.48
            # Disallow conflicting intervening swings; count aligned independent ones.
            between = [(j,v) for j,v in pivots if a < j < b]
            if any(abs(v-(va+slope*(j-a))) > tolerance for j,v in between):
                continue
            anchors = [(a,va)]
            for j,v in between+[(b,vb)]:
                if j-anchors[-1][0] >= 5 and abs(v-(va+slope*(j-a))) <= tolerance:
                    anchors.append((j,v))
            if len(anchors)<2 or anchors[-1][0] != b:
                continue
            test_idx = int(conf.get("retest_candle_index", i-1))
            if test_idx<=b+3 or test_idx>=i:
                continue
            # Third-touch diagonal Gap Retest ONLY: follow the established
            # structure BEFORE this retest. A bearish market permits resistance
            # swing-high SELLs; bullish permits support swing-low BUYs.
            # When structure is genuinely mixed/ranging, allow either side.
            # The separate horizontal/double-top/double-bottom detector stays
            # unchanged. This function is called only on Gap Retest timeframes.
            market_trend = local_structure_trend(candles, test_idx)
            if market_trend in ("bullish", "bearish") and direction != market_trend:
                continue
            projected = va+slope*(i-a)
            if projected<=0:
                continue
            # Do not project through a clear counter-break before this retest.
            broken=False
            for j in range(a+1, test_idx):
                level = va+slope*(j-a)
                close=float(candles[j]["close"])
                if direction=="bullish" and close < level-ar*0.55:
                    broken=True;break
                if direction=="bearish" and close > level+ar*0.55:
                    broken=True;break
            if broken:
                continue
            gap=[]
            for j in range(b+2, test_idx):
                level=va+slope*(j-a)
                delta=(float(candles[j]["close"])-level)*(1 if direction=="bullish" else -1)
                gap.append(delta)
            if len(gap)<3 or max(gap)<ar*1.4:
                continue
            if not any(all(x>=ar*0.6 for x in gap[k:k+3]) for k in range(len(gap)-2)):
                continue
            wick=float(candles[test_idx][kind])
            test_line=va+slope*(test_idx-a)
            if abs(wick-test_line)>ar*0.55:
                continue
            confirmed_close=float(candles[i]["close"])
            if direction=="bullish" and confirmed_close<=projected+ar*0.10:
                continue
            if direction=="bearish" and confirmed_close>=projected-ar*0.10:
                continue
            target1,take_profit=sr_structure_targets(candles,direction,test_idx,confirmed_close,search_back=120)
            extreme=float(candles[i]["high" if direction=="bullish" else "low"])
            if target1 is not None:
                if direction=="bullish" and extreme>=target1-ar*0.35: continue
                if direction=="bearish" and extreme<=target1+ar*0.35: continue
            count=len(anchors)+1  # current retest is an additional independent touch
            score=7.5+min(1.5,(b-a)/35.0)+min(1.0,(max(gap)/ar-1.4)/3)+min(1.0,max(0,count-3)*0.3)
            candidates.append((score, count, a,va,b,vb,anchors,projected,wick,target1,take_profit,test_idx))
    if not candidates:
        return None
    score,count,a,va,b,vb,anchors,projected,wick,target1,take_profit,test_idx=max(candidates,key=lambda x:(x[0],x[1]))
    strength="VERY STRONG" if count>=4 else "STRONG"
    return {
        "name":"S/R GAP RETEST SETUP", "direction":direction,
        "confirmed":True,"score":score,"confirmation_date":conf["date"],
        "confirmation_close":conf["close"],"penetration":conf["penetration"],
        "retest_depth_pct":100.0,"departure_extreme":None,
        "level":projected,"old_level":va,"retest_price":wick,
        "retest_date":candles[test_idx].get("datetime",""),
        "level_source":"diagonal trendline "+("support" if direction=="bullish" else "resistance"),
        "old_date":candles[a].get("datetime",""),"separation":i-b,
        "weak_retest":False,"diagonal":True,"trendline_touches":count,
        "turning_point_strength":f"{strength}: {count} independent trendline touches including latest confirmed retest",
        "trendline_touch_points":[
            {"date":candles[j].get("datetime",""),"price":float(v)} for j,v in anchors
        ],
        "target":target1,"target1":target1,
        "target1_source":"structural" if target1 is not None else None,
        "take_profit":take_profit,
        "take_profit_source":"structural" if take_profit is not None else None,
    }


def count_same_colour_before(candles, i, colour):
    """Count ONLY the uninterrupted same-colour run immediately before i.

    Edo rule: the pullback candles must be directly adjacent to the confirmation.
    We never search farther back through mixed candles to manufacture a 2+ run.
    A doji/mixed/other-colour candle ends the run immediately.
    """
    if i <= 0 or i > len(candles):
        return 0, i

    count = 0
    j = i - 1
    while j >= 0:
        c = candle_colour(candles[j])
        if c != colour:
            break
        count += 1
        j -= 1

    return count, j + 1


def exact_adjacent_pullback_run(candles, run_start, confirm_index, run_colour):
    """Hard guard for Edo's minimum-2 candle setup.

    Every candle from run_start up to, but not including, the confirmation must
    be the required pullback colour and must be consecutive. The confirmation
    must be the very next candle and the opposite colour. This deliberately
    rejects separated red/green candles that only look like a run when older
    candles are searched farther back.
    """
    if run_start < 0 or confirm_index <= run_start or confirm_index >= len(candles):
        return False

    run = candles[run_start:confirm_index]
    if len(run) < 2:
        return False
    if any(candle_colour(c) != run_colour for c in run):
        return False

    confirm_colour = candle_colour(candles[confirm_index])
    expected_confirm = "red" if run_colour == "green" else "green"
    if confirm_colour != expected_confirm:
        return False

    # The candle directly before confirmation must belong to the run.
    return candle_colour(candles[confirm_index - 1]) == run_colour



def detect_support_resistance_signal(candles):
    """
    Edo Support / Resistance REACTION alert for 8H, Daily and Weekly.

    This is NOT a simple "price is near an old level" alert.

    A valid alert requires:
      1) an established support/resistance zone from prior swing reactions
      2) price moved clearly away from that zone after a prior reaction
      3) the newest fully CLOSED candle retests the same zone
      4) the newest candle shows rejection/bounce away from the zone

    Works in bullish, bearish and range-bound markets.
    """
    if not candles or len(candles) < 30:
        return []

    latest = candles[-1]
    history = candles[:-1]
    recent = history[-100:] if len(history) > 100 else history

    latest_open = float(latest["open"])
    latest_high = float(latest["high"])
    latest_low = float(latest["low"])
    latest_close = float(latest["close"])

    recent_ranges = [
        max(float(c["high"]) - float(c["low"]), 0.0)
        for c in recent[-24:]
    ]
    med_range = median_value(recent_ranges)
    if med_range <= 0:
        return []

    zone_tol = med_range * 0.35
    move_away_min = med_range * 1.20

    highs = swing_points(recent, "high")
    lows = swing_points(recent, "low")

    def grouped_zones(points):
        zones = []
        for idx, level in points:
            level = float(level)
            placed = False
            for z in zones:
                center = sum(x["level"] for x in z) / len(z)
                if abs(level - center) <= zone_tol:
                    z.append({"idx": idx, "level": level})
                    placed = True
                    break
            if not placed:
                zones.append([{"idx": idx, "level": level}])

        out = []
        for z in zones:
            if len(z) < 2:
                continue
            center = sum(x["level"] for x in z) / len(z)
            out.append({
                "level": center,
                "touches": len(z),
                "points": z,
            })
        return out

    support_zones = grouped_zones(lows)
    resistance_zones = grouped_zones(highs)

    found = []

    # SUPPORT retest + bounce
    for z in support_zones:
        level = z["level"]

        # newest candle must actually reach/retest support
        if latest_low > level + zone_tol:
            continue

        body_low = min(latest_open, latest_close)
        lower_wick = max(0.0, body_low - latest_low)
        body = abs(latest_close - latest_open)

        # close back above the zone with visible rejection
        rejection_ok = (
            latest_close > level
            and lower_wick >= max(body * 0.50, med_range * 0.12)
        )
        if not rejection_ok:
            continue

        valid_prior = None
        for pt in reversed(z["points"]):
            idx = pt["idx"]
            if idx >= len(recent) - 3:
                continue

            after = recent[idx + 1:]
            if not after:
                continue

            highest_after = max(float(c["high"]) for c in after)
            if highest_after - level >= move_away_min:
                valid_prior = pt
                break

        if valid_prior is None:
            continue

        found.append({
            "name": "SUPPORT RETEST / BOUNCE WATCH",
            "direction": "bullish",
            "confirmed": True,
            "score": 7.0 + min(2.0, z["touches"] * 0.4),
            "confirmation_date": latest.get("datetime", ""),
            "confirmation_close": latest_close,
            "level": level,
            "touches": z["touches"],
            "prior_reaction_index": valid_prior["idx"],
            "context": "support_resistance",
            "trend": local_structure_trend(candles, len(candles)-1),
            "target": None,
        })

    # RESISTANCE retest + rejection
    for z in resistance_zones:
        level = z["level"]

        if latest_high < level - zone_tol:
            continue

        body_high = max(latest_open, latest_close)
        upper_wick = max(0.0, latest_high - body_high)
        body = abs(latest_close - latest_open)

        rejection_ok = (
            latest_close < level
            and upper_wick >= max(body * 0.50, med_range * 0.12)
        )
        if not rejection_ok:
            continue

        valid_prior = None
        for pt in reversed(z["points"]):
            idx = pt["idx"]
            if idx >= len(recent) - 3:
                continue

            after = recent[idx + 1:]
            if not after:
                continue

            lowest_after = min(float(c["low"]) for c in after)
            if level - lowest_after >= move_away_min:
                valid_prior = pt
                break

        if valid_prior is None:
            continue

        found.append({
            "name": "RESISTANCE RETEST / REJECTION WATCH",
            "direction": "bearish",
            "confirmed": True,
            "score": 7.0 + min(2.0, z["touches"] * 0.4),
            "confirmation_date": latest.get("datetime", ""),
            "confirmation_close": latest_close,
            "level": level,
            "touches": z["touches"],
            "prior_reaction_index": valid_prior["idx"],
            "context": "support_resistance",
            "trend": local_structure_trend(candles, len(candles)-1),
            "target": None,
        })

    return found


def clean_pullback_run(candles, run_start, confirm_index, run_colour):
    """
    Edo clean-pullback quality filter for the normal 2+ candle signal.

    Purpose: reject tiny/overlapping same-colour candles sitting in congestion
    while keeping obvious 2, 3, 4+ candle retracements. This is price-action
    only; it does NOT add a 50% confirmation rule and uses no indicators.

    A clean run must:
      - make real net progress in the pullback direction;
      - have most closes continue in that direction instead of overlapping back;
      - have enough total body/progress compared with recent candle size.
    """
    if run_start < 0 or confirm_index <= run_start:
        return False, "invalid pullback run"

    run = candles[run_start:confirm_index]
    if len(run) < 2:
        return False, "fewer than 2 pullback candles"

    recent_range = avg_range(candles, end=run_start, length=20)
    recent_body = avg_body(candles, end=run_start, length=20)
    if recent_range <= 0:
        recent_range = avg_range(candles, end=confirm_index, length=20)
    if recent_body <= 0:
        recent_body = avg_body(candles, end=confirm_index, length=20)

    first_open = float(run[0]["open"])
    last_close = float(run[-1]["close"])
    net_progress = (last_close - first_open) if run_colour == "green" else (first_open - last_close)
    total_body = sum(abs(float(c["close"]) - float(c["open"])) for c in run)

    # The run must actually travel a meaningful distance. Two tiny candles in a
    # sideways cluster should not qualify just because their colours match.
    min_progress = max(recent_range * 0.70, recent_body * 1.10)
    if net_progress < min_progress:
        return False, f"pullback too small/choppy (progress {net_progress:.6g})"

    # Directional efficiency rejects runs whose same-colour bodies largely
    # overlap/cancel each other. A clean pullback should retain a good portion
    # of its body movement as net progress.
    efficiency = net_progress / total_body if total_body > 0 else 0.0
    if efficiency < 0.55:
        return False, f"pullback candles overlap too much (efficiency {efficiency:.0%})"

    # Reject heavy candle-range overlap/congestion. A visually clean pullback
    # should not have nearly all candles sitting on top of each other.
    if len(run) >= 2:
        overlap_ratios = []
        for a, b in zip(run, run[1:]):
            a_lo, a_hi = float(a["low"]), float(a["high"])
            b_lo, b_hi = float(b["low"]), float(b["high"])
            overlap = max(0.0, min(a_hi, b_hi) - max(a_lo, b_lo))
            smaller = min(max(a_hi - a_lo, 0.0), max(b_hi - b_lo, 0.0))
            if smaller > 0:
                overlap_ratios.append(overlap / smaller)
        if overlap_ratios and (sum(overlap_ratios) / len(overlap_ratios)) > 0.72:
            return False, "pullback is too congested/overlapping"

    # Most closes must continue to make progress in the pullback direction.
    progressive_steps = 0
    comparisons = 0
    for a, b in zip(run, run[1:]):
        comparisons += 1
        if run_colour == "green" and float(b["close"]) > float(a["close"]):
            progressive_steps += 1
        elif run_colour == "red" and float(b["close"]) < float(a["close"]):
            progressive_steps += 1

    if comparisons:
        required_steps = max(1, (comparisons + 1) // 2)
        if progressive_steps < required_steps:
            return False, "pullback closes are too sideways/overlapping"

    # Avoid qualifying a run made almost entirely from doji-sized bodies.
    avg_run_body = total_body / len(run)
    if recent_body > 0 and avg_run_body < recent_body * 0.55:
        return False, "pullback candles are too small relative to recent price action"

    return True, ""



def trend_pullback_retracement_preserves_structure(candles, run_start, confirm_index, trend):
    """
    Trend Pullback ONLY: reject a 2+ candle counter-trend run when that run has
    already broken the pre-existing trend structure.  The trend is measured
    strictly BEFORE run_start; the retracement itself is never allowed to
    manufacture the trend it is supposed to be pulling back against.

    Bearish continuation stays valid only while the bullish retracement does
    not close above the newest confirmed pre-pullback swing high.
    Bullish continuation stays valid only while the bearish retracement does
    not close below the newest confirmed pre-pullback swing low.

    A small average-range buffer avoids cancelling a valid pullback for a
    marginal/rounding touch.  If no confirmed swing is available, a very large
    counter-trend displacement is treated conservatively as a structure break.
    """
    if run_start < 4 or confirm_index <= run_start:
        return False

    pre = candles[:run_start]
    run = candles[run_start:confirm_index]
    if not pre or not run:
        return False

    recent_pre = pre[-24:]
    ar = avg_range(recent_pre, end=len(recent_pre), length=len(recent_pre))
    if ar <= 0:
        ar = avg_range(candles, end=run_start, length=20)
    buffer = ar * 0.10 if ar > 0 else 0.0

    highs = swing_points(recent_pre, "high", left=2, right=2)
    lows = swing_points(recent_pre, "low", left=2, right=2)
    run_closes = [float(c["close"]) for c in run]

    if trend == "bearish":
        if highs:
            last_swing_high = float(highs[-1][1])
            if max(run_closes) > last_swing_high + buffer:
                return False
        else:
            start_price = float(run[0]["open"])
            progress = max(run_closes) - start_price
            if ar > 0 and progress > ar * 3.0:
                return False

    elif trend == "bullish":
        if lows:
            last_swing_low = float(lows[-1][1])
            if min(run_closes) < last_swing_low - buffer:
                return False
        else:
            start_price = float(run[0]["open"])
            progress = start_price - min(run_closes)
            if ar > 0 and progress > ar * 3.0:
                return False
    else:
        return False

    return True

def detect_trend_pullback(candles, conf, allow_sr_exception=False, require_local_trend=True):
    """
    Edo Trend Pullback rule — NO 50% penetration requirement.

    BEARISH trend / possible SELL:
      1) Minimum 2 consecutive bullish fully CLOSED candles pull upward.
      2) Next fully CLOSED candle is bearish.
      3) Pullback candles must form a clean, meaningful retracement rather than
         tiny overlapping congestion.
      4) No minimum body-penetration percentage is required.

    BULLISH trend / possible BUY:
      1) Minimum 2 consecutive bearish fully CLOSED candles pull downward.
      2) Next fully CLOSED candle is bullish.
      3) Pullback candles must form a clean, meaningful retracement rather than
         tiny overlapping congestion.
      4) No minimum body-penetration percentage is required.

    No forming candle may trigger a signal.
    """
    i = conf["index"]
    if i < 2:
        return None

    direction = conf["direction"]
    confirm_candle = candles[i]
    confirm_close = float(confirm_candle["close"])

    if direction == "bearish":
        run_colour = "green"
        required_trend = "bearish"
        run_count, run_start = count_same_colour_before(candles, i, run_colour)
        if run_count < 2:
            return None

    elif direction == "bullish":
        run_colour = "red"
        required_trend = "bullish"
        run_count, run_start = count_same_colour_before(candles, i, run_colour)
        if run_count < 2:
            return None

    else:
        return None

    # Hard adjacency rule: only an uninterrupted 2+ run immediately before
    # the confirmation is valid. Never join separated same-colour candles.
    if not exact_adjacent_pullback_run(candles, run_start, i, run_colour):
        return None

    # Edo strong-trend rule for every normal Trend Pullback:
    # the 2+ opposite-colour candles must be a clean retracement AGAINST an
    # already established trend on the signal timeframe.  A ranging/mixed
    # structure is not a Trend Pullback.
    clean_ok, clean_reason = clean_pullback_run(
        candles, run_start, i, run_colour
    )
    if not clean_ok:
        return None

    # Trend Pullback ONLY: use the dominant recent-structure classifier.
    # Other EdoSignal signal families continue using their existing logic.
    trend = trend_pullback_structure_trend(candles, run_start)
    if require_local_trend and trend != required_trend:
        return None

    # The counter-trend run must remain a retracement.  If it has already
    # broken the pre-pullback swing structure, the old trend is invalidated and
    # the confirmation candle must NOT create a continuation signal.
    if not trend_pullback_retracement_preserves_structure(
        candles, run_start, i, required_trend
    ):
        return None

    score = 6.0 + min(3.0, (run_count - 2) * 0.75)
    target = previous_target(candles, direction, run_start)

    return {
        "name": "TREND PULLBACK SETUP",
        "direction": direction,
        "confirmed": True,
        "score": score,
        "confirmation_date": conf["date"],
        "confirmation_close": confirm_close,
        "run_count": run_count,
        "run_colour": run_colour,
        "run_start": run_start,
        "confirmation_index": i,
        "run_dates": [
            candles[j].get("datetime", "")
            for j in range(run_start, i)
        ],
        "trend": trend,
        "required_trend": required_trend,
        "normal_local_trend_ok": trend == required_trend,
        "context": "trend",
        "target": target,
    }


def trend_pullback_near_structural_sr(candles, setup, interval):
    """
    Edo 4H / 8H / Daily / Weekly Trend Pullback context rule.

    4H also requires support/resistance proximity in addition to its separate
    higher-timeframe direction filter. This keeps 4H entries at meaningful
    structural levels instead of signalling every 2+ candle retracement.

    Trend Pullback context may come from EITHER:
      * meaningful horizontal structural S/R ZONES (including support /
        resistance role reversal), OR
      * an established sloping trend-line built from at least two prior
        meaningful swing touches.

    Bullish confirmation must be at/near support; bearish confirmation must
    be at/near resistance. No 50% body rule is introduced here, and only
    fully closed candles supplied to this detector can qualify.
    """
    if not candles or not setup:
        return False, None, None

    direction = setup.get("direction")
    i = setup.get("confirmation_index")
    run_start = setup.get("run_start")

    if not isinstance(i, int) or not isinstance(run_start, int):
        return False, None, None
    if i <= 2 or run_start <= 2:
        return False, None, None

    ar = avg_range(candles, i + 1, 20)
    if ar <= 0:
        return False, None, None

    # S/R is an area rather than one exact price.
    zone_tolerance = max(
        ar * 0.85,
        abs(float(candles[i]["close"])) * 0.0015
    )

    search_start = max(0, run_start - 100)
    history = candles[search_start:run_start]
    if len(history) < 6:
        return False, None, None

    reaction_slice = candles[run_start:i + 1]

    if direction == "bullish":
        touch_price = min(float(c["low"]) for c in reaction_slice)
        swings = swing_points(history, "low", left=2, right=2)
        sr_kind = "support"
        wanted_slope = "up"
    elif direction == "bearish":
        touch_price = max(float(c["high"]) for c in reaction_slice)
        swings = swing_points(history, "high", left=2, right=2)
        sr_kind = "resistance"
        wanted_slope = "down"
    else:
        return False, None, None

    # 1) Existing horizontal structural S/R test.
    # A Trend Pullback must react at a level that existed BEFORE the pullback.
    # Do not let a fresh high/low manufacture its own S/R zone.
    candidates = []
    full_swings = []
    for local_i, level in swings:
        full_i = search_start + local_i
        full_swings.append((full_i, float(level)))
        separation = run_start - full_i
        if separation < 3:
            continue
        distance = abs(float(level) - touch_price)
        if distance <= zone_tolerance:
            candidates.append((distance, -full_i, float(level)))

    if candidates:
        candidates.sort()
        distance, _, level = candidates[0]
        setup["sr_context_ok"] = True
        setup["sr_kind"] = sr_kind
        setup["sr_level"] = level
        setup["sr_distance"] = distance
        setup["sr_zone_tolerance"] = zone_tolerance
        setup["sr_context_type"] = "horizontal"
        return True, sr_kind, level

    # 2b) Edo horizontal S/R ZONE / role-reversal test.
    #
    # Edo draws support/resistance as a BOX, not an exact-price line.  A prior
    # reaction area remains meaningful when price later returns anywhere inside
    # that area (or just through it within tolerance).  A former resistance can
    # also become support after price has broken above it, and former support can
    # become resistance after price has broken below it.
    #
    # Build zones only from PRIOR meaningful swing highs/lows.  The current
    # pullback/confirmation is never allowed to manufacture its own zone.
    zone_points = []
    for point_kind in ("low", "high"):
        for local_i, level in swing_points(history, point_kind, left=2, right=2):
            full_i = search_start + local_i
            if run_start - full_i < 3:
                continue
            level = float(level)

            # The old level must have produced a real reaction/move away.
            after_end = min(run_start, full_i + 9)
            after = candles[full_i + 1:after_end]
            if len(after) < 2:
                continue
            if point_kind == "low":
                reaction = max(float(c["high"]) for c in after) - level
            else:
                reaction = level - min(float(c["low"]) for c in after)
            if reaction < ar * 1.10:
                continue

            zone_points.append((full_i, level, point_kind))

    # Cluster nearby old reaction prices into the kind of horizontal boxes Edo
    # marks manually.  Multiple touches strengthen a zone but one strong old
    # reaction is enough when the later role-reversal is clear.
    zone_points.sort(key=lambda row: row[1])
    clusters = []
    for pt in zone_points:
        if not clusters or abs(pt[1] - clusters[-1][-1][1]) > zone_tolerance * 1.35:
            clusters.append([pt])
        else:
            clusters[-1].append(pt)

    zone_candidates = []
    for cluster in clusters:
        levels = [row[1] for row in cluster]
        zone_low = min(levels) - zone_tolerance * 0.35
        zone_high = max(levels) + zone_tolerance * 0.35
        zone_mid = sum(levels) / len(levels)

        # Current reaction may wick into or slightly through the box.
        if touch_price < zone_low - zone_tolerance or touch_price > zone_high + zone_tolerance:
            continue

        latest_anchor = max(row[0] for row in cluster)
        between = candles[latest_anchor + 1:run_start]
        if not between:
            continue

        # Accept same-role zones directly.  Also accept role reversal only when
        # price clearly crossed to the other side before this retest.
        kinds = {row[2] for row in cluster}
        role_ok = False
        role_reversal = False
        if direction == "bullish":
            if "low" in kinds:
                role_ok = True
            if "high" in kinds and max(float(c["close"]) for c in between) > zone_high + zone_tolerance * 0.20:
                role_ok = True
                role_reversal = True
        else:
            if "high" in kinds:
                role_ok = True
            if "low" in kinds and min(float(c["close"]) for c in between) < zone_low - zone_tolerance * 0.20:
                role_ok = True
                role_reversal = True

        if not role_ok:
            continue

        if touch_price < zone_low:
            distance = zone_low - touch_price
        elif touch_price > zone_high:
            distance = touch_price - zone_high
        else:
            distance = 0.0
        zone_candidates.append((distance, -len(cluster), -latest_anchor, zone_mid, zone_low, zone_high, role_reversal))

    if zone_candidates:
        zone_candidates.sort()
        distance, neg_touches, _, level, zone_low, zone_high, role_reversal = zone_candidates[0]
        setup["sr_context_ok"] = True
        setup["sr_kind"] = sr_kind
        setup["sr_level"] = float(level)
        setup["sr_zone_low"] = float(zone_low)
        setup["sr_zone_high"] = float(zone_high)
        setup["sr_zone_touches"] = int(-neg_touches)
        setup["sr_distance"] = float(distance)
        setup["sr_zone_tolerance"] = zone_tolerance
        setup["sr_context_type"] = "horizontal_role_reversal" if role_reversal else "horizontal_zone"
        return True, sr_kind, float(level)

    # 3) Trend-line S/R test. Use two meaningful PRIOR swing touches only.
    #    The current pullback is a later test; it is never used to invent
    #    the line. Resistance lines must slope down and support lines up.
    trend_candidates = []
    pts = full_swings[-14:]  # recent meaningful swings; avoids ancient lines
    for a in range(len(pts) - 1):
        x1, y1 = pts[a]
        for b in range(a + 1, len(pts)):
            x2, y2 = pts[b]
            if x2 - x1 < 3:
                continue
            slope = (y2 - y1) / float(x2 - x1)
            if wanted_slope == "down" and slope >= 0:
                continue
            if wanted_slope == "up" and slope <= 0:
                continue

            # Project the established line into the current pullback area.
            # Accept a touch by any pullback/confirmation wick within the
            # same adaptive S/R tolerance used for horizontal structure.
            best_dist = None
            best_level = None
            best_x = None
            for x in range(run_start, i + 1):
                projected = y1 + slope * (x - x1)
                wick = float(candles[x]["low"] if direction == "bullish" else candles[x]["high"])
                dist = abs(wick - projected)
                if best_dist is None or dist < best_dist:
                    best_dist, best_level, best_x = dist, projected, x

            if best_dist is not None and best_dist <= zone_tolerance:
                # Prefer the closest line touch, then the more recently
                # established second anchor.
                trend_candidates.append((best_dist, -x2, best_level, x1, y1, x2, y2, slope, best_x))

    if not trend_candidates:
        return False, None, None

    trend_candidates.sort(key=lambda row: (row[0], row[1]))
    distance, _, level, x1, y1, x2, y2, slope, touch_i = trend_candidates[0]

    setup["sr_context_ok"] = True
    setup["sr_kind"] = sr_kind
    setup["sr_level"] = float(level)
    setup["sr_distance"] = float(distance)
    setup["sr_zone_tolerance"] = zone_tolerance
    setup["sr_context_type"] = "trendline"
    setup["trendline_anchor_1"] = {"index": x1, "price": y1}
    setup["trendline_anchor_2"] = {"index": x2, "price": y2}
    setup["trendline_slope_per_candle"] = slope
    setup["trendline_touch_index"] = touch_i

    return True, sr_kind, float(level)


def sr_second_reaction_exception(candles, setup):
    """
    Edo 8H / Daily early-trend exception.

    Allows the normal 2+ same-colour + opposite-colour CLOSED confirmation setup before a
    strong trend is fully established ONLY when the SAME fully closed
    confirmation candle is also a genuine second separated reaction from an
    established historical S/R zone.

    Bullish setup -> second support retest/bounce with a real move-away gap.
    Bearish setup -> second resistance retest/rejection with a real move-away gap.

    This does not create a signal by itself. The normal 2+ / opposite-colour closed-candle
    pattern must already be valid.
    """
    if not candles or not setup:
        return None

    reactions = detect_support_resistance_signal(candles)
    wanted = "SUPPORT RETEST / BOUNCE WATCH" if setup.get("direction") == "bullish" \
        else "RESISTANCE RETEST / REJECTION WATCH"

    confirmation_date = setup.get("confirmation_date", "")

    matches = [
        r for r in reactions
        if r.get("name") == wanted
        and r.get("direction") == setup.get("direction")
        and r.get("confirmation_date", "") == confirmation_date
    ]

    if not matches:
        return None

    best = max(matches, key=lambda r: r.get("score", 0))
    return best


def apply_edo_8h_daily_context_rule(candles, interval, setups):
    """
    4H:
      handled elsewhere and remains STRONG-TREND ONLY.

    8H:
      normal strong-trend continuation is allowed;
      OR the second separated S/R reaction exception may allow the normal
      2+ / opposite-colour setup before the trend has become strong.

    Daily:
      normal local-trend retracement is allowed;
      OR the same second separated S/R reaction exception may allow the
      normal 2+ / opposite-colour setup while a new trend is developing.

    No forming candle can qualify.
    """
    if interval not in ("8h", "1day"):
        return setups

    out = []
    for p in setups:
        if p.get("name") != "TREND PULLBACK SETUP":
            out.append(p)
            continue

        # Normal local price-structure rule already agrees.
        if p.get("normal_local_trend_ok"):
            out.append(p)
            continue

        reaction = sr_second_reaction_exception(candles, p)
        if reaction:
            q = dict(p)
            q["sr_second_reaction_exception"] = True
            q["sr_exception_level"] = reaction.get("level")
            q["sr_exception_touches"] = reaction.get("touches", 2)
            q["context"] = "second_sr_reaction"
            # This is deliberately an early/developing-trend setup, not a
            # claim that the market is already strongly trending.
            q["trend"] = "developing"
            out.append(q)

    return out


def format_signal_time_perth(value):
    """Display a stored UTC candle timestamp in Perth local time (AWST)."""
    if not value:
        return ""
    try:
        raw = str(value).strip()
        if raw.endswith("Z"):
            raw = raw[:-1] + "+00:00"
        dt = datetime.fromisoformat(raw)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(ZoneInfo("Australia/Perth")).strftime("%d %b %Y • %H:%M Perth")
    except Exception:
        return str(value)


def detect_audusd_daily_railway_tracks(candles, confirmation_index):
    """
    Edo RR (Railway Tracks) reversal signal.

    Scope is enforced by the callers: AUD/USD, FOREX, Daily only.
    Pattern rules:
      - two adjacent fully closed candles of opposite colour;
      - real bodies are roughly similar (smaller >= 60% of larger);
      - both bodies are meaningful versus recent Daily bodies;
      - the pair appears after a clear directional run of at least 3 of the
        previous 5 candles, with net progress in that run direction;
      - bearish RR = bullish run then GREEN/RED pair near the run high;
      - bullish RR = bearish run then RED/GREEN pair near the run low.
    """
    i = int(confirmation_index)
    if i < 8 or i >= len(candles):
        return None

    first = candles[i - 1]
    second = candles[i]
    c1 = candle_colour(first)
    c2 = candle_colour(second)
    if c1 not in ("green", "red") or c2 not in ("green", "red") or c1 == c2:
        return None

    body1 = abs(float(first["close"]) - float(first["open"]))
    body2 = abs(float(second["close"]) - float(second["open"]))
    larger = max(body1, body2)
    smaller = min(body1, body2)
    if larger <= 0 or smaller / larger < 0.60:
        return None

    prior = candles[max(0, i - 8): i - 1]
    prior_bodies = [abs(float(c["close"]) - float(c["open"])) for c in prior]
    normal_body = median_value(prior_bodies)
    if normal_body > 0 and min(body1, body2) < normal_body * 0.70:
        return None

    run = candles[i - 6:i - 1]  # five candles immediately before first RR candle
    greens = sum(candle_colour(c) == "green" for c in run)
    reds = sum(candle_colour(c) == "red" for c in run)
    start_close = float(run[0]["close"])
    end_close = float(run[-1]["close"])
    recent_ranges = [max(0.0, float(c["high"]) - float(c["low"])) for c in prior]
    normal_range = median_value(recent_ranges)
    progress = abs(end_close - start_close)
    if normal_range > 0 and progress < normal_range * 1.25:
        return None

    if c1 == "green" and c2 == "red":
        if greens < 3 or end_close <= start_close:
            return None
        # Pair must be at the end/top of the bullish run, as in Edo's chart.
        run_high = max(float(c["high"]) for c in run)
        pair_high = max(float(first["high"]), float(second["high"]))
        tolerance = normal_range * 0.60 if normal_range > 0 else 0.0
        if pair_high + tolerance < run_high:
            return None
        direction = "bearish"
        run_direction = "bullish"
    elif c1 == "red" and c2 == "green":
        if reds < 3 or end_close >= start_close:
            return None
        # Pair must be at the end/bottom of the bearish run.
        run_low = min(float(c["low"]) for c in run)
        pair_low = min(float(first["low"]), float(second["low"]))
        tolerance = normal_range * 0.60 if normal_range > 0 else 0.0
        if pair_low - tolerance > run_low:
            return None
        direction = "bullish"
        run_direction = "bearish"
    else:
        return None

    return {
        "name": "RR — RAILWAY TRACKS",
        "direction": direction,
        "confirmation_date": second.get("datetime", ""),
        "confirmation_close": float(second["close"]),
        "first_date": first.get("datetime", ""),
        "first_colour": c1,
        "second_colour": c2,
        "body_similarity_pct": (smaller / larger) * 100.0,
        "run_direction": run_direction,
        "score": 90.0 + (smaller / larger) * 10.0,
    }


def describe_setup(p, interval=None):
    bullish = p["direction"] == "bullish"
    icon = "🟢" if bullish else "🔴"
    css = "buy" if bullish else "sell"
    direction_word = "Bullish" if bullish else "Bearish"

    if p["name"] in STAR_PATTERN_NAMES:
        icon, css = "💠", "starcyan"
        touches = int(p.get('trendline_touches',3))
        detail = (f"{p.get('trendline_type','Trendline').title()} retest • "
                  f"{touches} touches • {p.get('turning_point_strength','STRONG')} "
                  f"• {p.get('trend_at_retest','mixed').upper()} trend")
        level_text = (f"Trendline: {p['level']:.5f} • "
                      f"Rejection: {p['retest_price']:.5f} • "
                      f"Confirmed close: {p['confirmation_close']:.5f}")
        if p.get('target1') is not None:
            level_text += f" • Target 1: {p['target1']:.5f}"
        if p.get('take_profit') is not None:
            level_text += f" • Take Profit: {p['take_profit']:.5f}"
    elif p["name"] == "RR — RAILWAY TRACKS":
        icon, css = "🔵", "rrblue"
        detail = f"Railway Tracks • {p.get('body_similarity_pct',0):.0f}% body match"
        level_text = (
            f"First candle: {format_signal_time_perth(p.get('first_date',''))} • "
            f"Confirmed: {format_signal_time_perth(p.get('confirmation_date',''))} • "
            f"Close: {p['confirmation_close']:.5f}"
        )
    elif p["name"] == "S/R GAP RETEST SETUP":
        if p.get("diagonal"):
            count = p.get('trendline_touches', 3)
            strength = "VERY STRONG" if count >= 4 else "STRONG" if count >= 3 else "VALID"
            detail = f"Diagonal {p['level_source']} • {count} touches • {strength} • {p['penetration']:.0f}% candle confirmation"
            touches = p.get("trendline_touch_points") or []
            touch_text = (
                " • ".join(f"Touch {n}: {point['price']:.5f} ({format_signal_time_perth(point['date'])})"
                           for n, point in enumerate(touches, 1)) + " • "
            ) if touches else ""
            level_text = (
                touch_text +
                f"Trendline: {p['level']:.5f} • "
                f"Retest: {p['retest_price']:.5f} ({format_signal_time_perth(p['retest_date'])}) • "
                f"Close: {p['confirmation_close']:.5f}"
            )
        else:
            detail = f"Horizontal S/R retest • {p.get('retest_depth_pct', 0):.0f}% level retest • {p['penetration']:.0f}% candle confirmation"
            level_text = (
                f"S/R level: {p['level']:.5f} • "
                f"Earlier wick: {p['old_level']:.5f} ({format_signal_time_perth(p['old_date'])}) • "
                f"Retest: {p['retest_price']:.5f} ({format_signal_time_perth(p['retest_date'])}) • "
                f"Close: {p['confirmation_close']:.5f}"
            )
        if p.get("turning_point_strength"):
            detail += " • " + p["turning_point_strength"]
            if p.get("strength_turning_points"):
                level_text += " • Supporting pivots: " + "; ".join(
                    f"{pt['price']:.5f} ({format_signal_time_perth(pt['date'])})"
                    for pt in p["strength_turning_points"]
                )
        # Preserve both numerical profit targets and their structural sources.
        if p.get("target1") is not None:
            level_text += f" • Target 1: {p['target1']:.5f} ({p.get('target1_source', 'structural')})"
        if p.get("take_profit") is not None:
            level_text += f" • Take Profit: {p['take_profit']:.5f} ({p.get('take_profit_source', 'structural')})"
    elif p["name"] in ("SUPPORT RETEST / BOUNCE WATCH", "RESISTANCE RETEST / REJECTION WATCH"):
        zone_word = "Support" if bullish else "Resistance"
        detail = f"{zone_word} retest • {p.get('touches', 2)} touches • {str(p.get('trend', 'mixed')).upper()} trend"
        level_text = f"{zone_word}: {p['level']:.5f} • Close: {p['confirmation_close']:.5f}"
    elif p["name"] == "TREND PULLBACK SETUP":
        detail = f"{p['run_count']} {p['run_colour']} pullback candles • Confirmed close"
        if p.get("higher_tf_filter"):
            htf = p.get("higher_tf_states", {})
            detail += f" • D1: {htf.get('1D','?')} • W1: {htf.get('1W','?')}"
            if p.get('higher_tf_warning'):
                detail += f" • {p['higher_tf_warning']}"
        level_text = f"Close: {p['confirmation_close']:.5f}"
    else:
        detail = f"Range reversal • {p['run_count']} candles • {p['penetration']:.0f}% confirmation"
        level_text = f"Close: {p['confirmation_close']:.5f}"

    # Visual-only distinction: Edo uses 4H Trend Pullback mainly as an entry/re-entry
    # inside the larger trend. Detection rules are unchanged.
    display_name = p["name"]
    if interval == "4h" and p["name"] == "TREND PULLBACK SETUP":
        display_name = "4H PULLBACK ENTRY"
        icon = "⚪"
        css = "entry4h"

    return {
        "name": display_name,
        "detail": detail,
        "level_text": level_text,
        "icon": icon,
        "css": css,
        "direction": p["direction"],
        "confirmation_date": p.get("confirmation_date", ""),
        "confirmation_time_perth": format_signal_time_perth(p.get("confirmation_date", "")),
        "confirmed": True,
        "score": p.get("score", 0),
    }



def median_value(values):
    clean = sorted(float(v) for v in values if v is not None)
    if not clean:
        return 0.0
    n = len(clean)
    mid = n // 2
    if n % 2:
        return clean[mid]
    return (clean[mid - 1] + clean[mid]) / 2.0


def detect_weekly_spike(closed_weekly):
    """
    Edo Weekly Spike warning — TREND FILTERED.

    Warning only, never a BUY/SELL signal.

    The newest fully CLOSED Weekly candle can trigger only when there was a
    clear price-action trend BEFORE the spike candle:

      Prior Weekly trend BULLISH -> only an unusual UPPER wick can alert.
      Prior Weekly trend BEARISH -> only an unusual LOWER wick can alert.
      Prior Weekly trend MIXED   -> NO Weekly Spike alert.

    Trend is determined by EdoSignal's existing naked price-structure logic
    (recent close progress + swing highs/lows). No moving averages, RSI, etc.

    The wick itself must also be clearly out of ordinary:
      - at least 4.0x the recent median same-side wick
      - at least 75% of the recent median weekly range
      - at least 35% of the current candle's full range
      - at least 2.0x the current candle body

    Requiring both a strong historical ratio AND meaningful absolute size
    prevents a small wick from looking abnormal only because recent same-side
    wicks happened to be tiny.
    """
    if not closed_weekly or len(closed_weekly) < 14:
        return None

    spike_index = len(closed_weekly) - 1

    # IMPORTANT: this looks ONLY at candles BEFORE the spike candle.
    prior_trend = local_structure_trend(closed_weekly, spike_index)

    # Edo only wants weekly spike alerts after a clear bullish/bearish trend.
    if prior_trend not in ("bullish", "bearish"):
        return None

    current = closed_weekly[-1]
    history = closed_weekly[-13:-1]

    o = float(current["open"])
    h = float(current["high"])
    l = float(current["low"])
    c = float(current["close"])

    body = abs(c - o)
    current_range = max(h - l, 1e-12)
    upper = max(0.0, h - max(o, c))
    lower = max(0.0, min(o, c) - l)

    hist_upper = []
    hist_lower = []
    hist_ranges = []

    for x in history:
        xo = float(x["open"])
        xh = float(x["high"])
        xl = float(x["low"])
        xc = float(x["close"])
        hist_upper.append(max(0.0, xh - max(xo, xc)))
        hist_lower.append(max(0.0, min(xo, xc) - xl))
        hist_ranges.append(max(0.0, xh - xl))

    med_upper = max(median_value(hist_upper), 1e-12)
    med_lower = max(median_value(hist_lower), 1e-12)
    med_range = max(median_value(hist_ranges), 1e-12)

    body_floor = max(body, current_range * 0.06, 1e-12)

    upper_ratio = upper / med_upper
    lower_ratio = lower / med_lower

    # A real Weekly Spike should stand out visually as well as statistically.
    # The current-range test protects against inflated ratios caused by a tiny
    # historical same-side wick median.
    upper_hit = (
        upper_ratio >= 4.0
        and upper >= med_range * 0.75
        and upper >= current_range * 0.35
        and upper >= body_floor * 2.0
    )
    lower_hit = (
        lower_ratio >= 4.0
        and lower >= med_range * 0.75
        and lower >= current_range * 0.35
        and lower >= body_floor * 2.0
    )

    # Directional reversal filter:
    # bullish run -> rejection above
    # bearish run -> rejection below
    if prior_trend == "bullish":
        if not upper_hit:
            return None
        side = "upper"
        label = "UPPER"
        ratio = upper_ratio
        meaning = (
            "Weekly trend was BULLISH before this candle. "
            "Unusually long upper wick may show rejection at the top / possible bearish reversal area."
        )
    else:
        if not lower_hit:
            return None
        side = "lower"
        label = "LOWER"
        ratio = lower_ratio
        meaning = (
            "Weekly trend was BEARISH before this candle. "
            "Unusually long lower wick may show rejection at the bottom / possible bullish reversal area."
        )

    date = current.get("datetime", "")
    message = (
        f"{label} wick spike on the newest fully CLOSED Weekly candle ({date}). "
        f"Prior Weekly trend: {prior_trend.upper()}. "
        f"Wick is about {ratio:.1f}x its recent normal size. {meaning} "
        f"Warning only — wait for your normal candle confirmation before trading."
    )

    return {
        "side": side,
        "label": label,
        "ratio": ratio,
        "date": date,
        "prior_trend": prior_trend,
        "message": message,
        "upper_wick": upper,
        "lower_wick": lower,
        "body": body,
        "range": current_range,
    }


def notify_weekly_spike(symbol, grp, spike):
    """Send one Pushover confirmation per detected fully closed weekly spike."""
    if not spike:
        return

    candle_date = spike.get("date", "")
    side = spike.get("side", "")
    if not candle_date or not side:
        return

    try:
        with db_conn() as c:
            c.execute(
                """
                INSERT INTO weekly_spike_notifications(
                    grp, symbol, candle_date, side, wick_ratio, sent_at
                ) VALUES(?,?,?,?,?,?)
                """,
                (
                    grp,
                    symbol,
                    candle_date,
                    side,
                    float(spike.get("ratio", 0.0)),
                    datetime.utcnow().isoformat()
                )
            )
            c.commit()
    except sqlite3.IntegrityError:
        return

    send_push(
        f"🟣 {symbol} [{grp}] — WEEKLY SPIKE",
        spike["message"]
    )


def collect_weekly_spike(symbol, grp="FOREX"):
    candles, error = get_ohlc(symbol, "1week", outputsize=80, grp=grp)
    if error:
        return None, None, error

    closed = fully_closed_candles(candles, "1week")
    if len(closed) < 14:
        return None, None, "Not enough fully closed Weekly candle history."

    latest_closed_date = closed[-1].get("datetime", "")
    spike = detect_weekly_spike(closed)
    return spike, latest_closed_date, None


def weekly_spike_monitor():
    """
    Low-credit Weekly Spike monitor.

    It checks one saved market per minute. This gives regular coverage without
    competing heavily with the normal price/trend/pattern monitors.
    """
    time.sleep(210)
    index = 0

    while True:
        try:
            if manual_api_priority_active():
                time.sleep(15)
                continue

            with db_conn() as c:
                rows = c.execute(
                    "SELECT symbol, grp FROM favorites "
                    "WHERE grp IN ('FOREX','CRYPTO','CFD') ORDER BY grp,symbol"
                ).fetchall()

            if rows:
                if index >= len(rows):
                    index = 0

                row = rows[index]
                index = (index + 1) % len(rows)

                symbol = row["symbol"]
                grp = row["grp"]

                spike, latest_closed_date, error = collect_weekly_spike(symbol, grp)

                if error:
                    print("weekly spike monitor error", symbol, error)
                    record_scan_health("Weekly Spike", symbol, "1week", error=error)
                else:
                    record_scan_health("Weekly Spike", symbol, "1week",
                        signal=f"{symbol}: {spike.get('label') or spike.get('side') or 'Spike'}" if spike else '')
                if not error and latest_closed_date:
                    with db_conn() as c:
                        state = c.execute(
                            """
                            SELECT last_closed_date
                            FROM weekly_spike_state
                            WHERE grp=? AND symbol=?
                            """,
                            (grp, symbol)
                        ).fetchone()

                        previous = state["last_closed_date"] if state else ""

                        # A Railway restart/redeploy must never turn an already
                        # closed Weekly candle into a fresh phone alert. If the
                        # latest Weekly candle had already closed before this
                        # Python process started, silently baseline it.
                        weekly_close_utc = pattern_candle_close_utc(
                            latest_closed_date, "1week"
                        )
                        if (
                            weekly_close_utc is not None
                            and weekly_close_utc <= PROCESS_STARTED_UTC
                            and latest_closed_date != previous
                        ):
                            c.execute(
                                """
                                INSERT INTO weekly_spike_state(
                                    grp, symbol, last_closed_date, updated
                                ) VALUES(?,?,?,?)
                                ON CONFLICT(grp, symbol) DO UPDATE SET
                                    last_closed_date=excluded.last_closed_date,
                                    updated=excluded.updated
                                """,
                                (
                                    grp,
                                    symbol,
                                    latest_closed_date,
                                    datetime.utcnow().isoformat()
                                )
                            )
                            c.commit()
                            print(
                                "weekly spike baseline after restart",
                                grp, symbol, latest_closed_date
                            )
                            continue

                        if state is None:
                            c.execute(
                                """
                                INSERT INTO weekly_spike_state(
                                    grp, symbol, last_closed_date, updated
                                ) VALUES(?,?,?,?)
                                """,
                                (
                                    grp,
                                    symbol,
                                    latest_closed_date,
                                    datetime.utcnow().isoformat()
                                )
                            )
                            c.commit()

                            # First observation creates a baseline only.
                            # Historical Weekly spikes are never replayed.

                        elif latest_closed_date != previous:
                            c.execute(
                                """
                                UPDATE weekly_spike_state
                                SET last_closed_date=?, updated=?
                                WHERE grp=? AND symbol=?
                                """,
                                (
                                    latest_closed_date,
                                    datetime.utcnow().isoformat(),
                                    grp,
                                    symbol
                                )
                            )
                            c.commit()

                            if spike:
                                notify_weekly_spike(symbol, grp, spike)

        except Exception as e:
            print("weekly spike monitor error", e)

        time.sleep(60)



# -------------------------------------------------
# FOREX MONTHLY ABNORMAL SPIKE — SAME WEEKLY RULES
# -------------------------------------------------
def monthly_candle_close_utc(candle):
    """Use the next UTC calendar-month boundary, never a fixed 30-day period."""
    start = parse_candle_utc((candle or {}).get("datetime", ""))
    if start is None or start.day != 1:
        return None
    if start.month == 12:
        return start.replace(year=start.year + 1, month=1, day=1,
                             hour=0, minute=0, second=0, microsecond=0)
    return start.replace(month=start.month + 1, day=1,
                         hour=0, minute=0, second=0, microsecond=0)


def fully_closed_monthly_candles(candles, now_utc=None):
    """Twelve Data monthly bars include a still-forming current month: exclude it."""
    now_utc = now_utc or datetime.now(timezone.utc)
    return [c for c in (candles or [])
            if monthly_candle_close_utc(c) is not None
            and monthly_candle_close_utc(c) <= now_utc]


def detect_monthly_spike(closed_monthly):
    """Identical trend-before-spike and wick thresholds to existing Weekly rule."""
    result = detect_weekly_spike(closed_monthly)
    if not result:
        return None
    result = dict(result)
    result["message"] = (result["message"]
                         .replace("Weekly", "Monthly")
                         .replace("weekly", "monthly"))
    return result


def collect_monthly_spike(symbol, grp="FOREX"):
    """Forex only. Source is Twelve Data monthly data (FXCM service lacks M1)."""
    if grp != "FOREX":
        return None, None, "Monthly spikes are Forex-only."
    candles, error = get_ohlc(symbol, "1month", outputsize=80, grp="FOREX")
    if error:
        return None, None, error
    closed = fully_closed_monthly_candles(candles)
    if len(closed) < 14:
        return None, None, "Not enough fully closed Monthly candle history."
    return detect_monthly_spike(closed), closed[-1].get("datetime", ""), None


def notify_monthly_spike(symbol, spike):
    """A unique persistent record prevents repeated alerts for the same month."""
    if not spike or not spike.get("date") or not spike.get("side"):
        return False
    key = ("FOREX", symbol, spike["date"], spike["side"])
    try:
        with db_conn() as c:
            c.execute("""
                INSERT INTO monthly_spike_notifications
                (grp,symbol,candle_date,side,wick_ratio,sent_at)
                VALUES(?,?,?,?,?,?)
            """, (*key, float(spike.get("ratio",0)), datetime.now(timezone.utc).isoformat()))
            c.commit()
    except sqlite3.IntegrityError:
        return False
    sent = send_push(f"🟣 {symbol} [FOREX] — MONTHLY SPIKE", spike["message"])
    if not sent:
        # Allow a later check to retry an unsuccessful Pushover request.
        with db_conn() as c:
            c.execute("""DELETE FROM monthly_spike_notifications
                         WHERE grp=? AND symbol=? AND candle_date=? AND side=?""", key)
            c.commit()
    return bool(sent)


def monthly_spike_monitor():
    """Low-priority Forex-only scan, one saved pair every two minutes."""
    time.sleep(240)
    index = 0
    while True:
        try:
            if manual_api_priority_active():
                time.sleep(15)
                continue
            with db_conn() as c:
                rows = c.execute("SELECT symbol FROM favorites WHERE grp='FOREX' ORDER BY symbol").fetchall()
            if rows:
                index %= len(rows)
                symbol = rows[index]["symbol"]
                index += 1
                spike, latest_date, error = collect_monthly_spike(symbol)
                record_scan_health("Monthly Spike", symbol, "1month", error=error,
                    signal=f"{symbol}: {spike['label']} Monthly wick" if spike else "")
                if not error and latest_date:
                    with db_conn() as c:
                        state = c.execute("""SELECT last_closed_date FROM monthly_spike_state
                                             WHERE grp='FOREX' AND symbol=?""", (symbol,)).fetchone()
                        previous = state["last_closed_date"] if state else None
                        latest_close_utc = monthly_candle_close_utc({"datetime": latest_date})
                        # A restart must not replay an old monthly candle as a new alert.
                        if (previous is not None and latest_date != previous
                                and latest_close_utc is not None
                                and latest_close_utc <= PROCESS_STARTED_UTC):
                            c.execute("""UPDATE monthly_spike_state
                                         SET last_closed_date=?,updated=?
                                         WHERE grp='FOREX' AND symbol=?""",
                                      (latest_date, datetime.now(timezone.utc).isoformat(), symbol))
                            c.commit()
                            continue
                        if previous is None:
                            # First-ever observation is a baseline, not a historical alert.
                            c.execute("""INSERT INTO monthly_spike_state
                                         (grp,symbol,last_closed_date,updated) VALUES(?,?,?,?)""",
                                      ("FOREX", symbol, latest_date, datetime.now(timezone.utc).isoformat()))
                            c.commit()
                        elif latest_date != previous:
                            # Persist the new completed month before sending; reruns never replay it.
                            c.execute("""UPDATE monthly_spike_state SET last_closed_date=?,updated=?
                                         WHERE grp='FOREX' AND symbol=?""",
                                      (latest_date, datetime.now(timezone.utc).isoformat(), symbol))
                            c.commit()
                            if spike:
                                notify_monthly_spike(symbol, spike)
        except Exception as exc:
            print("monthly spike monitor error", exc)
        time.sleep(120)



def pullback_higher_tf_enabled(grp, interval):
    """Lower-timeframe pullback alignment: FX/CFD 4H+8H, Crypto 4H+12H."""
    return interval in (("4h", "12h") if str(grp).upper() == "CRYPTO"
                        else ("4h", "8h"))


def weekly_daily_direction_for_filters(symbol, grp):
    """All higher-timeframe strategy filters use Edo's NEW main trend."""
    # Prefer fresh calculations when available, rather than trusting an old
    # persisted label after the weekly direction has changed.
    weekly, we = get_candles(symbol, '1week', outputsize=100, grp=grp)
    daily, de = get_candles(symbol, '1day', outputsize=260, grp=grp)
    if we or de:
        return None, {}, we or de
    status, _, weekly_event = weekly_daily_main_trend_from_candles(weekly, daily)
    direction = ('bullish' if status == 'FULL BULLISH' else
                 'bearish' if status == 'FULL BEARISH' else None)
    states = {'1W': weekly_event['direction'].capitalize() if weekly_event else 'Mixed',
              '1D': direction.capitalize() if direction else 'Mixed',
              'Used': 'Weekly→Daily 65% confirmation',
              'Market': 'Trending' if direction else 'Ranging'}
    return direction, states, None


def strong_higher_timeframe_trend(symbol, grp='FOREX', interval='4h'):
    """Pullback continuation direction from the new Weekly→Daily main trend."""
    if not pullback_higher_tf_enabled(grp, interval):
        return None, {}, None
    return weekly_daily_direction_for_filters(symbol, grp)


def eight_hour_gap_higher_trend(symbol, grp='FOREX'):
    """8H/12H Gap Retest trend context from the same Weekly→Daily method."""
    return weekly_daily_direction_for_filters(symbol, grp)


def apply_8h_gap_trend_filter(symbol, grp, interval, setups):
    """
    Keep the existing 8H S/R Gap-Retest exactly as detected, but when Daily
    (or Weekly fallback) has a clear trend, allow only Gap-Retests in that
    direction. If both are mixed/ranging, allow the normal 8H range signals
    in either direction. Other setup types and other timeframes are untouched.
    """
    filter_interval = "12h" if str(grp or "").upper() == "CRYPTO" else "8h"
    if interval != filter_interval:
        return setups, None, None

    gap_setups = [p for p in setups if p.get("name") == "S/R GAP RETEST SETUP"]
    if not gap_setups:
        return setups, None, None

    higher_direction, states, error = eight_hour_gap_higher_trend(symbol, grp)
    if error:
        return [], states, error

    filtered = []
    for p in setups:
        if p.get("name") != "S/R GAP RETEST SETUP":
            filtered.append(p)
            continue

        # Ranging/mixed higher timeframes: preserve Edo's existing 8H
        # Gap-Retest exactly, including BUY support and SELL resistance setups.
        if higher_direction is None:
            q = dict(p)
            q["gap_trend_filter"] = "ranging"
            q["gap_higher_tf_states"] = dict(states)
            filtered.append(q)
            continue

        # Clear higher-timeframe trend: continuation direction only.
        if p.get("direction") == higher_direction:
            q = dict(p)
            q["gap_trend_filter"] = "with_trend"
            q["gap_higher_tf_direction"] = higher_direction
            q["gap_higher_tf_states"] = dict(states)
            filtered.append(q)

    return filtered, states, None


def apply_strong_trend_filter(symbol, grp, interval, setups):
    """Apply Daily/Weekly alignment ONLY to lower-TF Trend Pullbacks.

    Established trend: continuation only. Weekly/Daily conflict: Daily wins,
    flagged MIXED. Both ranging: either direction, flagged RANGING — CAUTION.
    Never changes Gap Retests, higher-timeframe Pullbacks or other strategies.
    """
    if not pullback_higher_tf_enabled(grp, interval):
        return setups, None, None
    if not any(p.get("name") == "TREND PULLBACK SETUP" for p in setups):
        return setups, None, None

    higher_direction, states, error = strong_higher_timeframe_trend(symbol, grp, interval)
    if error:
        return [], states, error

    filtered = []
    for p in setups:
        if p.get("name") != "TREND PULLBACK SETUP":
            filtered.append(p)
            continue
        if higher_direction is not None and p.get("direction") != higher_direction:
            continue
        q = dict(p)
        q["higher_tf_filter"] = True
        q["higher_tf_direction"] = higher_direction
        q["higher_tf_states"] = dict(states)
        q["higher_tf_warning"] = (
            "RANGING — CAUTION" if states.get("Market") == "Ranging" else
            "MIXED — DAILY DIRECTION" if states.get("Market") == "Mixed" else ""
        )
        filtered.append(q)
    return filtered, states, None


def confirmation_room_filter(candles, setup, interval):
    """
    Edo's 'do not chase the confirmation candle into S/R' filter.

    Applied ONLY to 4H and 8H Trend Pullback trading signals.

    The original setup still requires:
      2+ same-colour retracement candles
      opposite-colour CLOSED confirmation
      opposite-colour fully CLOSED confirmation candle

    This extra filter REJECTS the trade signal when the confirmation candle
    has already travelled too far and closes at/very near the next important
    historical swing level in the continuation direction.

    It also flags an unusually oversized confirmation body as an extra reason
    when that candle is already pressing into the historical level.
    """
    if interval in ("4h", "8h") and setup.get("name") == "TREND PULLBACK SETUP":
        return True, None  # No support/resistance requirement for 4H/8H pullbacks.

    if setup.get("name") != "TREND PULLBACK SETUP":
        return True, None

    i = None
    confirmation_date = setup.get("confirmation_date", "")
    for idx, c in enumerate(candles):
        if c.get("datetime", "") == confirmation_date:
            i = idx
            break

    if i is None or i < 10:
        return True, None

    run_count = int(setup.get("run_count", 2))
    run_start = max(0, i - run_count)
    direction = setup.get("direction")
    confirm = candles[i]
    confirm_close = float(confirm["close"])
    confirm_body = abs(float(confirm["close"]) - float(confirm["open"]))

    # Use only history BEFORE the retracement started to find the old level.
    history = candles[max(0, run_start - 70):run_start]
    if len(history) < 8:
        return True, None

    recent_before = candles[max(0, run_start - 24):run_start]
    ranges = [
        max(0.0, float(c["high"]) - float(c["low"]))
        for c in recent_before
    ]
    bodies = [
        abs(float(c["close"]) - float(c["open"]))
        for c in recent_before
    ]

    positive_ranges = sorted(x for x in ranges if x > 0)
    positive_bodies = sorted(x for x in bodies if x > 0)

    if not positive_ranges:
        return True, None

    med_range = positive_ranges[len(positive_ranges)//2]
    med_body = (
        positive_bodies[len(positive_bodies)//2]
        if positive_bodies else med_range * 0.5
    )

    # The 'near level' zone is deliberately fairly tight: we only reject
    # when the confirmation is effectively arriving at the old turning point.
    near_tol = med_range * 0.35

    if direction == "bullish":
        pts = swing_points(history, "high")
        if not pts:
            return True, None

        levels = sorted(float(v) for _, v in pts if float(v) > float(candles[run_start]["low"]))
        if not levels:
            return True, None

        # Nearest historical resistance at/above the confirmation close,
        # otherwise the closest resistance just crossed by the candle.
        above = [v for v in levels if v >= confirm_close]
        level = min(above) if above else max(levels)

        distance = level - confirm_close
        at_or_near = abs(distance) <= near_tol or confirm_close >= level
        oversized = med_body > 0 and confirm_body >= med_body * 1.8

        if at_or_near:
            reason = (
                f"REJECTED: bullish confirmation moved too far and closed at/near "
                f"historical resistance {level:.5f}. "
                f"Confirmation close {confirm_close:.5f}; "
                f"only {abs(distance):.5f} room remained."
            )
            if oversized:
                reason += " Confirmation body was also unusually large."
            return False, reason

    elif direction == "bearish":
        pts = swing_points(history, "low")
        if not pts:
            return True, None

        levels = sorted(float(v) for _, v in pts if float(v) < float(candles[run_start]["high"]))
        if not levels:
            return True, None

        below = [v for v in levels if v <= confirm_close]
        level = max(below) if below else min(levels)

        distance = confirm_close - level
        at_or_near = abs(distance) <= near_tol or confirm_close <= level
        oversized = med_body > 0 and confirm_body >= med_body * 1.8

        if at_or_near:
            reason = (
                f"REJECTED: bearish confirmation moved too far and closed at/near "
                f"historical support {level:.5f}. "
                f"Confirmation close {confirm_close:.5f}; "
                f"only {abs(distance):.5f} room remained."
            )
            if oversized:
                reason += " Confirmation body was also unusually large."
            return False, reason

    return True, None


def apply_confirmation_room_filter(candles, interval, setups):
    """
    Remove overextended 4H/8H trading signals from notification eligibility,
    while keeping the rejection reason so the manual Signal page can explain
    exactly what Edo does not like about the setup.
    """
    accepted = []
    rejected = []

    for p in setups:
        ok, reason = confirmation_room_filter(candles, p, interval)
        if ok:
            accepted.append(p)
        else:
            rp = dict(p)
            rp["rejected"] = True
            rp["rejection_reason"] = reason
            rejected.append(rp)

    return accepted, rejected


def attach_pattern_push_history(symbol, interval, patterns):
    """Annotate the displayed patterns with Pushover request history (DB only).

    A successful Pushover HTTP response is NOT confirmation of phone delivery.
    Historical rows created by older app versions have no reliable outcome.
    """
    if not patterns:
        return patterns
    try:
        with db_conn() as c:
            rows = c.execute(
                """SELECT pattern_name, direction, confirmation_date, sent_at,
                          push_attempted_at, push_accepted_at, push_status
                   FROM pattern_notifications WHERE symbol=? AND interval=?""",
                (symbol, interval)
            ).fetchall()
    except Exception as exc:
        print("notification history lookup error", symbol, interval, exc)
        return patterns

    by_key = {(r["pattern_name"], r["direction"], r["confirmation_date"]): r for r in rows}
    for p in patterns:
        original_name = ("TREND PULLBACK SETUP" if p.get("name") == "4H PULLBACK ENTRY"
                         else p.get("name", ""))
        key = (original_name, p.get("direction", ""), p.get("confirmation_date", ""))
        row = by_key.get(key)
        if row is None:
            p["notification_note"] = "Phone alert: No automatic Pushover request recorded for this setup."
        elif row["push_status"] == "ACCEPTED":
            when = format_signal_time_perth(row["push_accepted_at"])
            p["notification_note"] = (f"Pushover accepted request: {when}. "
                                      "This does not prove the iPhone displayed it.")
        elif row["push_status"] == "FAILED":
            when = format_signal_time_perth(row["push_attempted_at"])
            p["notification_note"] = f"Pushover request failed: {when}. No phone delivery confirmed."
        elif row["push_status"] == "ATTEMPTING":
            when = format_signal_time_perth(row["push_attempted_at"])
            p["notification_note"] = f"Pushover request started: {when}. Final outcome not recorded."
        else:
            p["notification_note"] = ("Older alert record: actual send time and delivery "
                                      "cannot be verified (previous script saved timestamps before sending).")
    return patterns


def build_pattern_signal(symbol, interval, grp="FOREX", force_refresh=False):
    if interval == "1month" and str(grp).upper() not in {"FOREX", "CRYPTO"}:
        return None, "Monthly Trend Pullback is supported for Forex and Crypto only."
    cache_key = f"{grp}|{symbol}|{interval}"
    now = time.time()
    cached = PATTERN_SIGNAL_CACHE.get(cache_key)

    if cached and not force_refresh and now - cached["saved_at"] < PATTERN_SIGNAL_CACHE_SECONDS:
        return cached["data"], None

    candles, error = get_candles(symbol, interval, outputsize=140, grp=grp)

    if error:
        if "credits" in error.lower() or "limit" in error.lower():
            return None, "Twelve Data is temporarily busy. EdoSignal is protecting your API limit. Wait a moment and press Scan Again."
        return None, error

    # Use timestamp-based closure checking instead of blindly dropping
    # only the last returned candle.
    closed_candles = fully_closed_candles(candles, interval)

    if len(closed_candles) < 40:
        return None, f"Not enough fully closed {interval} candle history returned."

    found = []

    # Independent trendline star/rejection signals (3H/4H/Daily/Weekly).
    if interval in STAR_PATTERN_INTERVALS:
        for star_i in range(max(35,len(closed_candles)-9), len(closed_candles)):
            star = detect_trendline_star(closed_candles, star_i)
            if star:
                found.append(star)

    # AUD/USD only: separate Daily RR (Railway Tracks) reversal signal.
    # This does not alter any existing Trend Pullback or Gap-Retest rules.
    if str(grp).upper() == "FOREX" and str(symbol).upper() == "AUD/USD" and interval == "1day":
        for rr_conf in recent_confirmations(closed_candles, lookback=9):
            rr = detect_audusd_daily_railway_tracks(closed_candles, rr_conf)
            if rr:
                found.append(rr)

    # A) NORMAL Edo Trend Pullback — 4H, 8H/12H, Daily, Weekly, Forex/Crypto Monthly.
    #    Minimum 2 same-colour fully CLOSED pullback candles,
    #    then an opposite-colour fully CLOSED confirmation.
    #    NO 50% rule applies to this signal.
    #
    #    Every normal pullback must be a clean retracement against an established
    #    local trend.
    #    4H is Edo's entry/re-entry tool: it does NOT require S/R proximity,
    #    but it MUST align with the larger 8H trend (Daily fallback only when
    #    8H is structurally unclear).
    #    Daily / Weekly Trend Pullbacks still require meaningful S/R.
    if pullback_interval_enabled(grp, interval):
        for conf in recent_confirmations(closed_candles, lookback=7):
            pullback = detect_trend_pullback(
                closed_candles,
                conf,
                allow_sr_exception=False,
                require_local_trend=True
            )
            if not pullback:
                continue

            # Edo rule:
            # 4H is the entry/re-entry pullback and S/R is context only, not a blocker.
            # Daily / Weekly still require meaningful pre-existing S/R.
            if interval not in ("4h", "8h"):
                near_sr, sr_kind, sr_level = trend_pullback_near_structural_sr(
                    closed_candles, pullback, interval
                )
                if not near_sr:
                    continue

            found.append(pullback)

    # B) Edo S/R GAP-AND-RETEST — 8H, Daily and Weekly.
    #    If the structure is messy on a lower timeframe, it is suppressed there
    #    so the independently scanned higher timeframe can provide a cleaner setup.
    #    Established high/low on the left -> clear move away / separation ->
    #    later retest of the same zone -> opposite-colour CLOSED confirmation.
    #    The 50% previous-candle BODY rule applies ONLY to this signal.
    if sr_gap_retest_interval_enabled(grp, interval):
        for sr_conf in recent_sr_confirmations(closed_candles, lookback=9, grp=grp):
            sr_setup = detect_bounce_retest(closed_candles, sr_conf)
            if sr_setup:
                found.append(add_turning_point_gap_strength(closed_candles, sr_setup, interval))
            diagonal_setup = detect_diagonal_gap_retest(closed_candles, sr_conf)
            if diagonal_setup:
                found.append(add_turning_point_gap_strength(closed_candles, diagonal_setup, interval))

    # Avoid duplicate descriptions of the same setup/direction/confirmation.
    unique = {}
    for p in found:
        key = (p["name"], p["direction"], p["confirmation_date"])
        if key not in unique or p.get("score", 0) > unique[key].get("score", 0):
            unique[key] = p

    found = list(unique.values())

    star_found = [p for p in found if p.get('name') in STAR_PATTERN_NAMES]
    # Hard whitelist: ONLY Edo's requested signals.
    if interval == "4h":
        found = [p for p in found if p.get("name") == "TREND PULLBACK SETUP"]
    elif interval == "8h":
        found = [
            p for p in found
            if p.get("name") in (("TREND PULLBACK SETUP",) if str(grp).upper() == "CRYPTO" else ("TREND PULLBACK SETUP", "S/R GAP RETEST SETUP"))
        ]
    elif interval == "12h":
        found = [p for p in found if str(grp).upper() == "CRYPTO" and p.get("name") in ("TREND PULLBACK SETUP", "S/R GAP RETEST SETUP")]
    elif interval == "1day":
        found = [
            p for p in found
            if p.get("name") in ("TREND PULLBACK SETUP", "S/R GAP RETEST SETUP", "RR — RAILWAY TRACKS")
            and (p.get("name") != "RR — RAILWAY TRACKS" or (str(grp).upper() == "FOREX" and str(symbol).upper() == "AUD/USD"))
        ]
    elif interval == "1week":
        found = [
            p for p in found
            if p.get("name") in ("TREND PULLBACK SETUP", "S/R GAP RETEST SETUP")
        ]
    elif interval == "1month":
        found = [p for p in found if p.get("name") == "TREND PULLBACK SETUP"]
    else:
        found = []

    if interval in STAR_PATTERN_INTERVALS:
        found.extend(star_found)

    # Edo rule:
    #   All Trend Pullbacks -> established local trend + clean 2+ candle retracement.
    #   4H / 8H (Crypto 12H) -> higher-timeframe direction (Daily first, Weekly fallback); S/R is context
    #   only and does not block the entry/re-entry signal.
    #   Daily / Weekly -> meaningful pre-existing S/R remains mandatory.
    higher_tf_states = None
    if pullback_higher_tf_enabled(grp, interval):
        normal_found = [p for p in found if p.get("name") == "TREND PULLBACK SETUP"]
        other_found = [p for p in found if p.get("name") != "TREND PULLBACK SETUP"]

        normal_found, higher_tf_states, htf_error = apply_strong_trend_filter(
            symbol, grp, interval, normal_found
        )
        if htf_error:
            return None, htf_error

        found = normal_found + other_found

    # Edo 8H S/R Gap-Retest direction filter ONLY. The Gap-Retest itself is
    # unchanged. In a clear Daily trend (Weekly fallback when Daily is mixed),
    # keep only setups with that trend. If both are mixed/ranging, keep the
    # normal 8H range setups in either direction.
    if interval == ("12h" if str(grp).upper() == "CRYPTO" else "8h"):
        found, gap_higher_tf_states, gap_htf_error = apply_8h_gap_trend_filter(
            symbol, grp, interval, found
        )
        if gap_htf_error:
            return None, gap_htf_error

    # Use the same final confirmation-room rule as the automatic monitor.
    # This keeps the manual SIGNAL page and phone alerts in agreement.
    found, rejected_room_setups = apply_confirmation_room_filter(
        closed_candles, interval, found
    )

    # Most recent closed candle first; on the same candle, Gap Retest wins.
    found.sort(
        key=lambda p: (
            p.get("confirmation_date", ""),
            1 if p.get("name") == "S/R GAP RETEST SETUP" else 0,
            p.get("score", 0)
        ),
        reverse=True
    )

    latest_closed_date = closed_candles[-1].get("datetime", "")
    current_patterns = [
        p for p in found
        if p.get("confirmation_date", "") == latest_closed_date
    ]

    # Edo Forex weekend rule:
    # During the normal spot-Forex weekend closure, never present the newest
    # candle as a NEW actionable Price Action trigger. Automatic pattern pushes
    # are already suppressed/baselined separately. Keep only older historical
    # setups visible for reference until the market reopens.
    forex_weekend_blocked = (
        str(grp).upper() == "FOREX" and forex_weekend_closed()
        and not forex_friday_daily_weekend_exception(
            grp, interval, latest_closed_date
        )
    )
    if forex_weekend_blocked:
        current_patterns = []
        found = [
            p for p in found
            if p.get("confirmation_date", "") != latest_closed_date
        ]

    bullish = [p for p in current_patterns if p["direction"] == "bullish"]
    bearish = [p for p in current_patterns if p["direction"] == "bearish"]
    current_rr = [p for p in current_patterns if p.get("name") == "RR — RAILWAY TRACKS"]

    if current_rr and len(current_patterns) == len(current_rr):
        rr = current_rr[0]
        rr_side = "BUY" if rr.get("direction") == "bullish" else "SELL"
        signal = f"RR DAILY — {rr_side}"
        icon, css = "🔵", "rrblue"
        summary = "Railway Tracks confirmed"
    elif bullish and not bearish:
        star_only = [p for p in bullish if p.get('name') in STAR_PATTERN_NAMES]
        if star_only and len(star_only) == len(current_patterns):
            signal = "MORNING STAR — BUY" if star_only[0]['name'] == 'MORNING STAR SETUP' else "HAMMER — BUY"
            icon, css = "💠", "starcyan"
            summary = "Trendline reversal confirmed"
        elif interval == "4h" and all(p.get("name") == "TREND PULLBACK SETUP" for p in bullish):
            signal = "4H PULLBACK ENTRY — BUY"
            icon, css = "⚪", "entry4h"
            summary = "4H pullback confirmed"
        else:
            signal = "READY TO REVIEW — BUY"
            icon, css = "🟢", "buy"
            summary = "BUY setup confirmed"
    elif bearish and not bullish:
        star_only = [p for p in bearish if p.get('name') in STAR_PATTERN_NAMES]
        if star_only and len(star_only) == len(current_patterns):
            signal = "EVENING STAR — SELL" if star_only[0]['name'] == 'EVENING STAR SETUP' else "SHOOTING STAR — SELL"
            icon, css = "💠", "starcyan"
            summary = "Trendline rejection confirmed"
        elif interval == "4h" and all(p.get("name") == "TREND PULLBACK SETUP" for p in bearish):
            signal = "4H PULLBACK ENTRY — SELL"
            icon, css = "⚪", "entry4h"
            summary = "4H pullback confirmed"
        else:
            signal = "READY TO REVIEW — SELL"
            icon, css = "🔴", "sell"
            summary = "SELL setup confirmed"
    elif bullish and bearish:
        signal = "WAIT — MIXED PRICE ACTION"
        icon, css = "🟡", "wait"
        summary = (
            "The newest fully CLOSED candle produced conflicting valid setup evidence. "
            "Review the naked chart before trading."
        )
    else:
        signal = "WAIT"
        icon, css = "🟡", "wait"
        if forex_weekend_blocked:
            summary = (
                "Forex market is closed for the weekend. New Price Action signals "
                "are paused until the normal Forex session reopens. Older valid "
                "setups may be shown below for reference only."
            )
        elif found:
            summary = (
                "No new trigger • Previous setup shown below"
            )
        else:
            if rejected_room_setups:
                summary = rejected_room_setups[0].get(
                    "rejection_reason",
                    "Pattern detected, but rejected because the confirmation candle moved too far into historical support/resistance."
                )
            elif pullback_higher_tf_enabled(grp, interval) and higher_tf_states:
                state_text = " | ".join(f"{k} {v}" for k, v in higher_tf_states.items())
                summary = (
                    f"No {interval.upper()} setup passed the higher-timeframe direction filter. "
                    f"Daily is used first; Weekly is fallback when Daily is unclear; both ranging allow either direction. "
                    f"Current higher-timeframe state: {state_text}."
                )
            else:
                summary = "No qualifying closed-candle setup"

    # Weekly Spike disabled: Edo wants ONLY his requested trading signals.
    weekly_spike = None

    data = {
        "price": closed_candles[-1]["close"],
        "latest_closed_date": latest_closed_date,
        "market_source": closed_candles[-1].get("_source_label", ""),
        "weekly_spike": weekly_spike,
        "signal": signal,
        "signal_icon": icon,
        "signal_css": css,
        "summary": summary,
        "patterns": attach_pattern_push_history(
            symbol, interval, [describe_setup(p, interval) for p in found[:4]]
        ),
        "rejected_setups": [
            p.get("rejection_reason", "")
            for p in rejected_room_setups[:3]
            if p.get("rejection_reason")
        ],
        "updated": datetime.now(ZoneInfo("Australia/Perth")).strftime("%d %b %Y • %H:%M Perth"),
    }

    PATTERN_SIGNAL_CACHE[cache_key] = {"saved_at": now, "data": data}
    return data, None




def pattern_signal_family(p):
    """
    Group signals that mean the same thing to Edo so only one phone push
    of that type is sent for the same pair/direction on the same Perth day.

    Strategy families:
      TREND PULLBACK = normal minimum-2-candle setup, NO 50% rule.
      S/R GAP RETEST = separated historical support/resistance retest,
                       WITH the 50% confirmation rule.
    """
    name = str(p.get("name", "")).upper()

    if name in STAR_PATTERN_NAMES:
        return "TRENDLINE_STAR"
    if "RR" in name and "RAILWAY" in name:
        return "RR_RAILWAY_TRACKS"
    if "S/R GAP RETEST" in name:
        return "SR_GAP_RETEST"
    if "TREND PULLBACK" in name:
        return "TREND_PULLBACK"
    if "RANGE" in name and "REVERSAL" in name:
        return "RANGE_REVERSAL"

    return name.replace(" ", "_") or "OTHER"


def pattern_push_priority(p):
    """
    If two equivalent signals are found on the same scan, prefer the stronger
    confirmation so Edo receives one useful notification instead of two.
    """
    name = str(p.get("name", "")).upper()

    if "S/R GAP RETEST" in name:
        return 40
    if name in STAR_PATTERN_NAMES:
        return 25
    if "RR" in name and "RAILWAY" in name:
        return 30
    if "TREND PULLBACK" in name:
        return 20
    if "RANGE" in name and "REVERSAL" in name:
        return 20
    return 10


def perth_day_string():
    try:
        return datetime.now(ZoneInfo("Australia/Perth")).strftime("%Y-%m-%d")
    except Exception:
        # Perth is UTC+8 year-round; fallback only if timezone data is unavailable.
        return datetime.utcnow().strftime("%Y-%m-%d")


def reserve_daily_pattern_push(grp, symbol, p):
    """
    Edo rule:
      ONE automatic pattern/watch Pushover per market pair per Perth day.

    Example:
      if GBP/USD already sent any Trend Pullback or S/R Watch today,
      no second automatic pattern/watch Pushover for GBP/USD is sent today.

    Signal type and direction do NOT matter for the daily limit.
    The limit is persisted in SQLite, so restart/redeploy does not reset it.
    """
    local_day = perth_day_string()

    try:
        with db_conn() as c:
            c.execute(
                """
                INSERT INTO pair_daily_pushes(
                    grp, symbol, local_day, signal_name, direction, sent_at
                )
                VALUES(?,?,?,?,?,?)
                """,
                (
                    grp,
                    symbol,
                    local_day,
                    p.get("name", ""),
                    str(p.get("direction", "")),
                    datetime.utcnow().isoformat(),
                )
            )
            c.commit()
        return True
    except sqlite3.IntegrityError:
        return False


def forex_weekend_closed(now_utc=None):
    """
    True while the normal spot-Forex weekend session is closed.

    Forex closes at about 5pm New York Friday and reopens about 5pm
    New York Sunday. Using America/New_York automatically follows DST.
    Crypto is never affected by this helper.
    """
    now_utc = now_utc or datetime.now(timezone.utc)
    if now_utc.tzinfo is None:
        now_utc = now_utc.replace(tzinfo=timezone.utc)

    ny = now_utc.astimezone(ZoneInfo("America/New_York"))
    weekday = ny.weekday()  # Monday=0 ... Sunday=6
    minutes = ny.hour * 60 + ny.minute
    close_minutes = 17 * 60

    if weekday == 4 and minutes >= close_minutes:  # Friday after 17:00 NY
        return True
    if weekday == 5:  # Saturday
        return True
    if weekday == 6 and minutes < close_minutes:  # Sunday before 17:00 NY
        return True
    return False


def forex_friday_daily_weekend_exception(grp, interval, candle_date, now_utc=None):
    """Allow a genuine Friday FXCM D1 close to be processed on Saturday.

    FXCM-native candle labels can be broker-session timestamps rather than
    generic UTC start times. This exception only removes the blanket weekend
    veto; all existing candle, pattern, freshness and restart checks still run.
    """
    if str(grp).upper() != "FOREX" or interval != "1day" or not candle_date:
        return False
    now_utc = now_utc or datetime.now(timezone.utc)
    if now_utc.tzinfo is None:
        now_utc = now_utc.replace(tzinfo=timezone.utc)
    ny_now = now_utc.astimezone(ZoneInfo("America/New_York"))
    # Limit the exception to the actual Friday close and the following Saturday.
    if ny_now.weekday() not in (4, 5):
        return False
    if ny_now.weekday() == 4 and ny_now.hour < 17:
        return False
    candle_utc = parse_candle_utc(candle_date)
    if candle_utc is None:
        return False
    ny_candle = candle_utc.astimezone(ZoneInfo("America/New_York"))
    # FXCM broker labels may use Friday's date in UTC or New York.
    friday_date = (ny_now.date() if ny_now.weekday() == 4
                   else (ny_now - timedelta(days=1)).date())
    return ny_candle.date() == friday_date or candle_utc.date() == friday_date


def pattern_candle_close_utc(candle_start, interval):
    """Return the UTC close time for a candle-start timestamp when possible."""
    try:
        start = parse_candle_utc(candle_start)
        if start is None:
            return None
        if interval == "1month":
            return monthly_candle_close_utc({"datetime": candle_start})
        seconds = interval_seconds(interval)
        if not seconds:
            return None
        return start + timedelta(seconds=seconds)
    except Exception:
        return None


def _save_pattern_monitor_baseline(grp, symbol, interval, latest_closed_date):
    """Advance the persistent monitor state without generating a phone push."""
    with db_conn() as c:
        c.execute(
            """
            INSERT INTO pattern_monitor_state(
                grp, symbol, interval, last_closed_date, updated
            ) VALUES(?,?,?,?,?)
            ON CONFLICT(grp, symbol, interval) DO UPDATE SET
                last_closed_date=excluded.last_closed_date,
                updated=excluded.updated
            """,
            (
                grp,
                symbol,
                interval,
                latest_closed_date,
                datetime.utcnow().isoformat(),
            )
        )
        c.commit()


def notify_new_pattern_setups(symbol, interval, patterns, latest_closed_date, grp="FOREX"):
    """
    Notify only for a genuinely NEW fully closed candle.

    Safety rules:
      * A Railway restart/redeploy must never replay a candle that had already
        closed before this Python process started.
      * FOREX weekend pushes are suppressed, except a genuine Friday Daily
        close detected after Friday's New York market close. The existing
        freshness, restart and duplicate checks still apply.
      * CRYPTO remains 24/7.
    """
    if not latest_closed_date:
        return

    # Final fail-safe: an automatic alert must belong to a recent candle.
    # Even if persistent monitor state was delayed, never send a historical
    # H4/H8/Daily FXCM setup as though it had just happened.
    if str(grp).upper() in {"FOREX", "CFD"} and interval in {"4h", "8h", "1day"}:
        close_utc = pattern_candle_close_utc(latest_closed_date, interval)
        if close_utc is not None:
            now_utc = datetime.now(timezone.utc)
            seconds = interval_seconds(interval) or 0
            age_seconds = (now_utc - close_utc).total_seconds()
            if age_seconds > seconds + 120:
                _save_pattern_monitor_baseline(grp, symbol, interval, latest_closed_date)
                print(
                    "stale FXCM pattern push suppressed/baselined",
                    grp, symbol, interval, latest_closed_date,
                    "age_seconds", int(age_seconds)
                )
                return

    # TIMELY ALERT SAFEGUARD (all automatic pattern families): Never describe
    # a setup discovered hours after its expected candle close as a NEW alert.
    # FXCM-native timestamps are broker session labels; the existing
    # pattern_candle_close_utc interpretation is retained rather than
    # guessing a new broker candle boundary here. Validate exact FXCM session
    # alignment separately against the Railway candle helper.
    close_utc = pattern_candle_close_utc(latest_closed_date, interval)
    maximum_alert_lag_seconds = {
        "3h": 2 * 3600, "4h": 2 * 3600, "8h": 2 * 3600,
        "12h": 2 * 3600, "1day": 2 * 3600,
        "1week": 6 * 3600, "1month": 12 * 3600,
    }.get(interval, 2 * 3600)
    if close_utc is not None:
        actual_lag = (datetime.now(timezone.utc) - close_utc).total_seconds()
        if actual_lag > maximum_alert_lag_seconds:
            _save_pattern_monitor_baseline(grp, symbol, interval, latest_closed_date)
            print('late pattern push suppressed', grp, symbol, interval,
                  latest_closed_date, 'lag_minutes', int(actual_lag / 60),
                  flush=True)
            return

    # Never turn an old candle into a "new" push just because Railway restarted.
    if close_utc is not None and close_utc <= PROCESS_STARTED_UTC:
        _save_pattern_monitor_baseline(
            grp, symbol, interval, latest_closed_date
        )
        print(
            "pattern baseline after restart",
            grp, symbol, interval, latest_closed_date
        )
        return

    # Edo rule: no delayed Forex pattern alerts over the closed weekend.
    # Advance the state silently so Friday candles cannot replay on Saturday,
    # Sunday, or after the Sunday reopen.
    if (str(grp).upper() == "FOREX" and forex_weekend_closed()
            and not forex_friday_daily_weekend_exception(
                grp, interval, latest_closed_date
            )):
        _save_pattern_monitor_baseline(
            grp, symbol, interval, latest_closed_date
        )
        print(
            "forex weekend pattern push suppressed/baselined",
            symbol, interval, latest_closed_date
        )
        return

    with db_conn() as c:
        row = c.execute(
            """
            SELECT last_closed_date
            FROM pattern_monitor_state
            WHERE grp=? AND symbol=? AND interval=?
            """,
            (grp, symbol, interval)
        ).fetchone()

        previous_closed = row["last_closed_date"] if row else None

        # First-ever observation after installing this version: create one
        # persistent baseline so historical setups are not replayed.
        if previous_closed is None:
            c.execute(
                """
                INSERT INTO pattern_monitor_state(
                    grp, symbol, interval, last_closed_date, updated
                ) VALUES(?,?,?,?,?)
                """,
                (grp, symbol, interval, latest_closed_date, datetime.utcnow().isoformat())
            )
            c.commit()
            return

        if latest_closed_date == previous_closed:
            return

        # A genuinely new fully closed candle has appeared. Save the state
        # before sending so a restart cannot cause the same candle to replay.
        c.execute(
            """
            UPDATE pattern_monitor_state
            SET last_closed_date=?, updated=?
            WHERE grp=? AND symbol=? AND interval=?
            """,
            (latest_closed_date, datetime.utcnow().isoformat(), grp, symbol, interval)
        )
        c.commit()

    if not patterns:
        return

    tf_labels = {x["value"]: x["label"] for x in PATTERN_TIMEFRAMES}
    tf_label = tf_labels.get(interval, interval)

    # First keep only the strongest signal in each equivalent signal family
    # for this newest closed candle. This prevents e.g. SUPPORT BOUNCE WATCH
    # and BOUNCE / RETEST SETUP both firing for the same USD/CHF reaction.
    newest_patterns = [
        p for p in patterns
        if p.get("confirmation_date", "") == latest_closed_date
    ]

    best_by_family = {}
    for p in newest_patterns:
        family_key = (pattern_signal_family(p), str(p.get("direction", "")).lower())
        current = best_by_family.get(family_key)
        if current is None or pattern_push_priority(p) > pattern_push_priority(current):
            best_by_family[family_key] = p

    # Daily per-pair push limit remains unchanged; reserve it for Gap Retest
    # when multiple families confirm on this newest closed candle.
    prioritized_patterns = sorted(
        best_by_family.values(),
        key=lambda p: (pattern_push_priority(p), p.get("score", 0)),
        reverse=True,
    )
    for p in prioritized_patterns:
        confirmation_date = p.get("confirmation_date", "")
        if not confirmation_date:
            continue

        # Edo rule: once this pair has produced ANY automatic pattern/watch
        # Pushover today (Perth day), do not send another for this pair today.
        if not reserve_daily_pattern_push(grp, symbol, p):
            print(
                "daily pair push suppressed",
                grp, symbol, p.get("name"), p.get("direction"), perth_day_string()
            )
            continue

        try:
            with db_conn() as c:
                c.execute(
                    """
                    INSERT INTO pattern_notifications(
                        symbol, interval, pattern_name, direction,
                        confirmation_date, sent_at
                    ) VALUES(?,?,?,?,?,?)
                    """,
                    (
                        symbol, interval, p["name"], p["direction"],
                        confirmation_date, datetime.utcnow().isoformat()
                    )
                )
                c.commit()
        except sqlite3.IntegrityError:
            continue

        try:
            with db_conn() as c:
                c.execute(
                    """UPDATE pattern_notifications
                       SET push_status='ATTEMPTING', push_attempted_at=?
                       WHERE symbol=? AND interval=? AND pattern_name=?
                         AND direction=? AND confirmation_date=?""",
                    (datetime.now(timezone.utc).isoformat(), symbol, interval,
                     p["name"], p["direction"], confirmation_date)
                )
                c.commit()
        except Exception as exc:
            print("push attempt audit error", exc)

        bullish = p["direction"] == "bullish"
        icon = "🔵" if p.get("name") == "RR — RAILWAY TRACKS" else ("🟢" if bullish else "🔴")
        direction_word = "BULLISH" if bullish else "BEARISH"

        if p.get("higher_tf_filter"):
            htf = p.get("higher_tf_states", {})
            used_tf = htf.get("Used", "")
            used_state = htf.get(used_tf, "") if used_tf else ""
            trend_line = (
                f"Higher-timeframe context: Daily {htf.get('1D', 'unknown')}, "
                f"Weekly {htf.get('1W', 'unknown')}. "
                f"Direction source: {used_tf} {used_state}. "
                f"{p.get('higher_tf_warning', '')}. "
            )
        else:
            trend_line = ""

        if p.get("name") == "RR — RAILWAY TRACKS":
            rr_side = "BUY" if bullish else "SELL"
            push_body = (
                f"RR — RAILWAY TRACKS confirmed on AUD/USD DAILY "
                f"({format_signal_time_perth(confirmation_date)}). "
                f"Two adjacent fully CLOSED opposite-colour Daily candles formed at the end of a clear "
                f"{p.get('run_direction','')} run with roughly similar real bodies "
                f"({p.get('body_similarity_pct',0):.0f}% size match). "
                f"Possible {rr_side} reversal. Review the chart before trading."
            )
        elif p.get("name") == "S/R GAP RETEST SETUP":
            zone_word = "SUPPORT" if p["direction"] == "bullish" else "RESISTANCE"
            target_lines = ""
            if p.get("target1") is not None:
                src = p.get("target1_source", "structural")
                target_lines += f" Target 1: {p['target1']:.5f} ({src})."
            if p.get("take_profit") is not None:
                src = p.get("take_profit_source", "structural")
                target_lines += f" Take Profit: {p['take_profit']:.5f} ({src})."
            if p.get("turning_point_strength"):
                target_lines += " Extra turning-point confirmation: " + p["turning_point_strength"] + "."
            if p.get("diagonal"):
                push_body = (
                    f"DIAGONAL {zone_word} Gap-Retest on the NEWEST CLOSED {tf_label} candle "
                    f"({format_signal_time_perth(confirmation_date)}). "
                    f"At least two separated historical swing touches establish a clear trendline; "
                    f"price moved away and retested it (touch {p.get('trendline_touches',3)}). "
                    f"Opposite-colour confirmation closed {p.get('penetration', 0):.0f}% "
                    f"through the previous body. {direction_word} possibility."
                    f"{target_lines} Review chart before trading."
                )
            else:
                push_body = (
                f"{p['name']} confirmed on the NEWEST CLOSED {tf_label} candle "
                f"({format_signal_time_perth(confirmation_date)}). "
                f"Established {zone_word} on the left, price moved clearly away, "
                f"then returned after separation to retest the same zone. "
                f"Second-touch depth: {p.get('retest_depth_pct', 0):.0f}% back toward the original level. "
                f"The opposite-colour confirmation closed {p.get('penetration', 0):.0f}% "
                f"through the previous candle body. "
                f"{direction_word} possibility.{target_lines} Review the chart before trading."
            )
        elif p.get("name") == "TREND PULLBACK SETUP":
            pullback_colour = str(p.get("run_colour", "")).upper()
            confirmation_colour = "GREEN" if bullish else "RED"
            continuation_word = "BUY" if bullish else "SELL"
            structure_word = str(p.get("required_trend", p.get("direction", ""))).upper()
            run_count = int(p.get("run_count", 2))

            if p.get("context") == "second_sr_reaction" or p.get("trend") == "developing":
                market_text = f"This is a developing {structure_word} setup at structural S/R. "
            else:
                market_text = f"The larger price structure is {structure_word}. "

            push_body = (
                f"TREND PULLBACK SETUP confirmed on the NEWEST CLOSED {tf_label} candle "
                f"({format_signal_time_perth(confirmation_date)}). "
                f"{market_text}"
                f"{run_count} {pullback_colour} CLOSED candles pulled against that direction, "
                f"then the opposite-colour {confirmation_colour} confirmation candle fully CLOSED. "
                f"{trend_line}"
                f"Possible {continuation_word} continuation. Review the chart before trading."
            )
        else:
            push_body = (
                f"{p['name']} confirmed on the NEWEST CLOSED {tf_label} candle "
                f"({format_signal_time_perth(confirmation_date)}). "
                f"{trend_line}"
                f"{direction_word} possibility. Review the chart before trading."
            )

        # HOME Price Action READY alert:
        # A new CLOSED 4H setup is the event that makes the small HOME icon blink.
        # Give that event one distinctive Pushover siren ("whoop-whoop") sound.
        # Duplicate protection in pattern_notifications means the same confirmed
        # setup cannot make the phone sound repeatedly. Other timeframe pattern
        # notifications keep the normal Pushover sound.
        ready_sound = READY_PUSH_SOUND
        ready_priority = 1

        accepted = send_push(
            f"{icon} {symbol} [{grp}] — {p['name']}",
            push_body,
            sound=ready_sound,
            priority=ready_priority
        )
        try:
            with db_conn() as c:
                c.execute(
                    """UPDATE pattern_notifications
                       SET push_status=?, push_accepted_at=?
                       WHERE symbol=? AND interval=? AND pattern_name=?
                         AND direction=? AND confirmation_date=?""",
                    ('ACCEPTED' if accepted else 'FAILED',
                     datetime.now(timezone.utc).isoformat() if accepted else None,
                     symbol, interval, p['name'], p['direction'], confirmation_date)
                )
                c.commit()
        except Exception as exc:
            print("push result audit error", exc)


def collect_closed_pattern_setups(symbol, interval, grp="FOREX"):
    if interval == "1month" and str(grp).upper() not in {"FOREX", "CRYPTO"}:
        return None, None, "Monthly Trend Pullback is supported for Forex and Crypto only."
    """
    Collect Edo's trading setups from fully closed candles only: normal Trend Pullback (4H trend-filtered; 8H/Daily/Weekly near S/R, no 50%) and S/R Gap-Retest (8H/Daily/Weekly, 50% rules).

    Returns:
      setups, latest_closed_date, error
    """
    candles, error = get_candles(symbol, interval, outputsize=140, grp=grp)
    if error:
        return None, None, error
    if not candles or len(candles) < 41:
        return None, None, f"Not enough fully closed {interval} candle history returned."

    # Use the same timestamp-based closure logic as the manual Signal page.
    closed_candles = fully_closed_candles(candles, interval)
    if len(closed_candles) < 40:
        return None, None, f"Not enough fully closed {interval} candle history returned."

    latest_closed_date = closed_candles[-1].get("datetime", "")

    # HARD FRESHNESS RULE FOR FXCM SIGNALS:
    # Never turn an old broker candle into a current READY/phone alert.
    # This specifically protects US30/SPX500/NAS100 (and FXCM Forex) from
    # delayed/stale helper data after a Railway/API interruption.  The newest
    # fully closed broker candle must still be fresh for this timeframe.
    if str(grp).upper() in {"FOREX", "CFD"} and interval in {"4h", "8h", "1day"}:
        newest_closed = closed_candles[-1]
        if not closed_candle_is_fresh(newest_closed, interval):
            print(
                "stale FXCM candle suppressed",
                grp, symbol, interval, latest_closed_date
            )
            return [], latest_closed_date, None

    found = []

    # Independent trendline star/rejection signals (3H/4H/Daily/Weekly).
    if interval in STAR_PATTERN_INTERVALS:
        for star_i in range(max(35,len(closed_candles)-9), len(closed_candles)):
            star = detect_trendline_star(closed_candles, star_i)
            if star:
                found.append(star)

    # AUD/USD only: separate Daily RR (Railway Tracks) reversal signal.
    if str(grp).upper() == "FOREX" and str(symbol).upper() == "AUD/USD" and interval == "1day":
        for rr_conf in recent_confirmations(closed_candles, lookback=9):
            rr = detect_audusd_daily_railway_tracks(closed_candles, rr_conf)
            if rr:
                found.append(rr)

    # A) NORMAL Trend Pullback — through Monthly for Forex/Crypto, NO 50% rule.
    #    4H is the entry/re-entry signal: higher-timeframe trend alignment is
    #    required, but S/R proximity is NOT a mandatory blocker.
    #    Daily / Weekly must still be at/near meaningful S/R.
    if pullback_interval_enabled(grp, interval):
        for conf in recent_confirmations(closed_candles, lookback=7):
            pullback = detect_trend_pullback(
                closed_candles,
                conf,
                allow_sr_exception=False,
                require_local_trend=True
            )
            if not pullback:
                continue

            # Edo rule:
            # 4H is the entry/re-entry pullback and S/R is context only, not a blocker.
            # Daily / Weekly still require meaningful pre-existing S/R.
            if interval not in ("4h", "8h"):
                near_sr, sr_kind, sr_level = trend_pullback_near_structural_sr(
                    closed_candles, pullback, interval
                )
                if not near_sr:
                    continue

            found.append(pullback)

    # B) S/R GAP-AND-RETEST — 8H, Daily and Weekly, WITH 50% rule.
    #    Messy lower-timeframe structures are suppressed so Daily/Weekly can
    #    supply the cleaner version of the same price structure.
    if sr_gap_retest_interval_enabled(grp, interval):
        for sr_conf in recent_sr_confirmations(closed_candles, lookback=9, grp=grp):
            sr_setup = detect_bounce_retest(closed_candles, sr_conf)
            if sr_setup:
                found.append(add_turning_point_gap_strength(closed_candles, sr_setup, interval))
            diagonal_setup = detect_diagonal_gap_retest(closed_candles, sr_conf)
            if diagonal_setup:
                found.append(add_turning_point_gap_strength(closed_candles, diagonal_setup, interval))

    unique = {}
    for p in found:
        key = (p["name"], p["direction"], p["confirmation_date"])
        if key not in unique or p.get("score", 0) > unique[key].get("score", 0):
            unique[key] = p

    setups = list(unique.values())

    star_setups = [p for p in setups if p.get('name') in STAR_PATTERN_NAMES]
    # Hard whitelist for automatic phone notifications.
    if interval == "4h":
        setups = [p for p in setups if p.get("name") == "TREND PULLBACK SETUP"]
    elif interval == "8h":
        setups = [
            p for p in setups
            if p.get("name") in (("TREND PULLBACK SETUP",) if str(grp).upper() == "CRYPTO" else ("TREND PULLBACK SETUP", "S/R GAP RETEST SETUP"))
        ]
    elif interval == "12h":
        setups = [p for p in setups if str(grp).upper() == "CRYPTO" and p.get("name") in ("TREND PULLBACK SETUP", "S/R GAP RETEST SETUP")]
    elif interval == "1day":
        setups = [
            p for p in setups
            if p.get("name") in ("TREND PULLBACK SETUP", "S/R GAP RETEST SETUP", "RR — RAILWAY TRACKS")
            and (p.get("name") != "RR — RAILWAY TRACKS" or (str(grp).upper() == "FOREX" and str(symbol).upper() == "AUD/USD"))
        ]
    elif interval == "1week":
        setups = [
            p for p in setups
            if p.get("name") in ("TREND PULLBACK SETUP", "S/R GAP RETEST SETUP")
        ]
    else:
        setups = []

    if interval in STAR_PATTERN_INTERVALS:
        setups.extend(star_setups)

    # Edo rule:
    #   4H / 8H (Crypto 12H) Trend Pullback -> Daily first, Weekly fallback; range permits both.
    #   S/R is useful context on 4H but is NOT a mandatory blocker.
    #   Daily / Weekly Trend Pullback -> must be near meaningful S/R and do
    #   not use the 4H higher-timeframe alignment requirement.
    # The separate S/R Gap-Retest setup remains independent.

    if pullback_higher_tf_enabled(grp, interval):
        normal_setups = [p for p in setups if p.get("name") == "TREND PULLBACK SETUP"]
        other_setups = [p for p in setups if p.get("name") != "TREND PULLBACK SETUP"]

        normal_setups, higher_tf_states, htf_error = apply_strong_trend_filter(
            symbol, grp, interval, normal_setups
        )
        if htf_error:
            return None, latest_closed_date, htf_error

        setups = normal_setups + other_setups

    # Gap-Retest higher-timeframe direction filter only:
    # Forex/CFD use 8H; Bybit Crypto uses 12H. Detection rules are unchanged.
    if interval == ("12h" if str(grp).upper() == "CRYPTO" else "8h"):
        setups, gap_higher_tf_states, gap_htf_error = apply_8h_gap_trend_filter(
            symbol, grp, interval, setups
        )
        if gap_htf_error:
            return None, latest_closed_date, gap_htf_error

    # Reject overextended 4H/8H confirmations that have already arrived at
    # the next important historical S/R level. Rejected setups do NOT Push.
    setups, rejected_room_setups = apply_confirmation_room_filter(
        closed_candles, interval, setups
    )
    for rp in rejected_room_setups:
        print(
            "pattern rejected - confirmation too far into S/R",
            symbol, interval, rp.get("rejection_reason", "")
        )

    return setups, latest_closed_date, None


def save_price_action_status(grp, symbol, setups, latest_closed_date):
    """Save the newest CLOSED 4H Price Action state for the small HOME icon."""
    current = [p for p in (setups or []) if p.get("confirmation_date", "") == latest_closed_date]
    bullish = any(p.get("direction") == "bullish" for p in current)
    bearish = any(p.get("direction") == "bearish" for p in current)

    if bullish and not bearish:
        status, direction = "READY", "BUY"
    elif bearish and not bullish:
        status, direction = "READY", "SELL"
    else:
        status, direction = "WAIT", ""

    with db_conn() as c:
        c.execute(
            """
            INSERT INTO price_action_status(grp,symbol,status,direction,confirmation_date,updated)
            VALUES(?,?,?,?,?,?)
            ON CONFLICT(grp,symbol) DO UPDATE SET
                status=excluded.status,
                direction=excluded.direction,
                acknowledged_date=CASE
                    WHEN price_action_status.confirmation_date = excluded.confirmation_date
                    THEN price_action_status.acknowledged_date
                    ELSE ''
                END,
                confirmation_date=excluded.confirmation_date,
                updated=excluded.updated
            """,
            (grp, symbol, status, direction, latest_closed_date or "", datetime.utcnow().isoformat())
        )
        c.commit()


def save_timeframe_ready_status(grp, symbol, interval, setups, latest_closed_date):
    """Store independent unread status; only fully closed current-candle setups count."""
    current = [p for p in (setups or []) if p.get('confirmation_date') == latest_closed_date]
    buy = any(p.get('direction') == 'bullish' for p in current)
    sell = any(p.get('direction') == 'bearish' for p in current)
    status = 'READY' if buy != sell else 'WAIT'
    direction = 'BUY' if buy and not sell else ('SELL' if sell and not buy else '')
    with db_conn() as c:
        c.execute("""
            INSERT INTO price_action_timeframe_status
                (grp,symbol,interval,status,direction,confirmation_date,updated)
            VALUES(?,?,?,?,?,?,?)
            ON CONFLICT(grp,symbol,interval) DO UPDATE SET
                status=excluded.status, direction=excluded.direction,
                acknowledged_date=CASE
                    WHEN price_action_timeframe_status.confirmation_date=excluded.confirmation_date
                    THEN price_action_timeframe_status.acknowledged_date ELSE '' END,
                confirmation_date=excluded.confirmation_date, updated=excluded.updated
        """, (grp,symbol,interval,status,direction,latest_closed_date or '',datetime.utcnow().isoformat()))
        c.commit()


def acknowledge_timeframe_ready(grp, symbol, interval):
    """Opening one timeframe clears only its unread indicator."""
    with db_conn() as c:
        c.execute("""
            UPDATE price_action_timeframe_status SET acknowledged_date=confirmation_date,updated=?
            WHERE grp=? AND symbol=? AND interval=? AND status='READY'
        """, (datetime.utcnow().isoformat(),grp,symbol,interval))
        c.commit()


def acknowledge_home_blink(grp, symbol):
    """Stop blinking for currently visible signals without clearing any NEW labels."""
    with db_conn() as c:
        c.execute("""
            INSERT INTO price_action_blink_ack(grp,symbol,interval,confirmation_date)
            SELECT grp,symbol,interval,confirmation_date
            FROM price_action_timeframe_status
            WHERE grp=? AND symbol=? AND status='READY'
            ON CONFLICT(grp,symbol,interval) DO UPDATE SET
                confirmation_date=excluded.confirmation_date
        """, (grp,symbol))
        c.commit()


def unread_timeframes(grp, symbol):
    with db_conn() as c:
        rows=c.execute("""
            SELECT interval FROM price_action_timeframe_status
            WHERE grp=? AND symbol=? AND status='READY'
              AND confirmation_date != acknowledged_date
        """,(grp,symbol)).fetchall()
    return {r['interval'] for r in rows}


def acknowledge_price_action(grp, symbol):
    """Stop HOME icon blinking for the current READY setup after Edo opens it."""
    with db_conn() as c:
        c.execute(
            """
            UPDATE price_action_status
            SET acknowledged_date=confirmation_date, updated=?
            WHERE grp=? AND symbol=? AND status='READY'
            """,
            (datetime.utcnow().isoformat(), grp, symbol)
        )
        c.commit()


def pattern_signal_monitor():
    """
    Grow-55 background pattern scheduler.

    Goal:
      - scan 4H/8H/Daily for Edo's normal Trend Pullback
      - scan 8H/Daily/Weekly for Edo's S/R Gap-Retest
      - NEVER crowd out manual Trend / Signal page requests

    Protection:
      - manual_api_priority_active() always wins
      - only ONE background API job is processed at a time
      - 3-second gap between background jobs
      - each symbol/timeframe is checked only when its due interval expires

    Check cadence per saved market:
      3H/4H/8H/12H  every 10 minutes
      Daily           every 10 minutes
      Weekly          every 45 minutes
      Monthly         every 3 hours

    These are scan frequencies only. Signals still require a NEW fully CLOSED
    candle, so repeated scans cannot create duplicate signals.
    """
    # Start promptly after deployment; the persistent baseline/restart rules
    # below still prevent replaying old candle alerts.
    time.sleep(15)

    # Check more often after candle closes without altering ANY pattern rules.
    # One API job at a time still protects the FXCM/Bybit services.
    due_seconds = {
        "1h": 15 * 60,  # raw hourly data is never a trading signal
        "3h": 10 * 60,
        "4h": 10 * 60,
        "8h": 10 * 60,
        "12h": 10 * 60,
        "1day": 10 * 60,
        "1week": 45 * 60,
        "1month": 3 * 60 * 60,
    }

    last_checked = {}

    while True:
        try:
            # Manual Trend/Signal page requests have absolute priority.
            if manual_api_priority_active():
                time.sleep(10)
                continue

            with db_conn() as c:
                rows = c.execute(
                    "SELECT symbol, grp FROM favorites "
                    "WHERE grp IN ('FOREX','CRYPTO','CFD') "
                    "ORDER BY grp,symbol"
                ).fetchall()

            now_ts = time.time()
            jobs = []

            for row in rows:
                symbol = row["symbol"]
                grp = row["grp"]

                for tf in PATTERN_TIMEFRAMES:
                    interval = tf["value"]
                    # 12H automatic pattern scan is only for Bybit Crypto Gap-Retest.
                    if interval == "12h" and grp != "CRYPTO":
                        continue
                    if interval == "8h" and grp == "CRYPTO":
                        continue
                    if interval == "1month" and grp not in {"FOREX", "CRYPTO"}:
                        continue
                    # Do not waste the serial scan queue on timeframe/group
                    # combinations that have NO active signal family.
                    if not (pullback_interval_enabled(grp, interval)
                            or sr_gap_retest_interval_enabled(grp, interval)
                            or interval in STAR_PATTERN_INTERVALS
                            or (interval == "1day" and grp == "FOREX"
                                and symbol.upper() == "AUD/USD")):
                        continue
                    key = (grp, symbol, interval)
                    previous = last_checked.get(key, 0.0)
                    due = due_seconds.get(interval, 30 * 60)

                    if now_ts - previous >= due:
                        # Oldest/most-overdue jobs first.
                        overdue = now_ts - previous - due
                        jobs.append((overdue, symbol, grp, interval, key))

            jobs.sort(reverse=True, key=lambda x: x[0])

            if not jobs:
                time.sleep(20)
                continue

            # Process only ONE job, then yield. This is deliberate so a user
            # opening Trend or Signal is not stuck behind a large background batch.
            _, symbol, grp, interval, key = jobs[0]

            # Check again immediately before consuming an API call.
            if manual_api_priority_active():
                time.sleep(10)
                continue

            setups, latest_closed_date, error = collect_closed_pattern_setups(
                symbol, interval, grp
            )

            # Mark checked even on a normal API/data error so a broken symbol
            # cannot spin rapidly and monopolise background capacity.
            last_checked[key] = time.time()

            if error:
                print("pattern monitor error", symbol, interval, error)
                if pullback_interval_enabled(grp, interval):
                    record_scan_health("Trend Pullback", symbol, interval, error=error)
                if sr_gap_retest_interval_enabled(grp, interval):
                    record_scan_health("Gap Retest", symbol, interval, error=error)
            else:
                # The same candle batch is scanned by both detectors; a valid
                # empty result is still a successful scan, not a failure.
                names = [str(p.get('name', '')) for p in (setups or [])]
                for family, enabled, token in (
                    ("Trend Pullback", pullback_interval_enabled(grp, interval), "PULLBACK"),
                    ("Gap Retest", sr_gap_retest_interval_enabled(grp, interval), "RETEST"),
                ):
                    if enabled:
                        found = next((n for n in names if token in n.upper()), '')
                        record_scan_health(family, symbol, interval,
                                           signal=f"{symbol} {interval}: {found}" if found else '')
                save_timeframe_ready_status(grp, symbol, interval, setups, latest_closed_date)
                if interval == "4h":
                    save_price_action_status(grp, symbol, setups, latest_closed_date)
                notify_new_pattern_setups(
                    symbol,
                    interval,
                    setups,
                    latest_closed_date,
                    grp
                )

        except Exception as e:
            print("pattern signal monitor error", e)

        # Small yield between API requests. Previous 20-second gap multiplied
        # across all saved markets could delay Daily notifications for hours.
        # Manual pages still take priority above and API work stays serial.
        time.sleep(3)


def get_daily_candles_for_alignment(symbol, outputsize=1800, grp=None):
    if not TWELVE_KEY:
        return None, "Twelve Data API key is not configured."

    last_error = "Could not download daily alignment data."

    try:
        for resolved_symbol in twelve_symbol_candidates(symbol, grp):
            j = twelve_get_json(
                "https://api.twelvedata.com/time_series",
                {
                    "symbol": resolved_symbol,
                    "interval": "1day",
                    "outputsize": outputsize,
                    "apikey": TWELVE_KEY,
                    "format": "JSON",
                    "timezone": "UTC",
                },
                timeout=20
            )

            if j.get("status") == "error":
                last_error = j.get("message", "Twelve Data returned an error.")
                continue

            values = j.get("values") or []
            rows = []

            for row in reversed(values):
                try:
                    dt = datetime.fromisoformat(row["datetime"])
                    rows.append((dt, float(row["close"])))
                except Exception:
                    pass

            if len(rows) < 300:
                last_error = f"Not enough daily history for {resolved_symbol}."
                continue

            if grp == "CFD":
                print("CFD alignment source", symbol, "->", resolved_symbol)

            return rows, None

        return None, last_error

    except TwelveDataCoolingDown:
        return None, "API cooling down — please try again in a few seconds."
    except Exception as e:
        print("daily alignment error", symbol, e)
        return None, "Could not download daily alignment data."


def resample_closes(rows, mode):
    buckets = {}

    for dt, close in rows:
        if mode == "week":
            year, week, _ = dt.isocalendar()
            key = (year, week)
        else:
            key = (dt.year, dt.month)

        buckets[key] = close

    return list(buckets.values())


def save_trend_snapshot(symbol, states):
    """Persist latest closed-candle states for Active Alerts display."""
    with db_conn() as c:
        c.execute(
            """
            INSERT INTO trend_snapshot(symbol,weekly,daily,h12,h8,h4,h3,updated)
            VALUES(?,?,?,?,?,?,?,?)
            ON CONFLICT(symbol) DO UPDATE SET
                weekly=excluded.weekly,
                daily=excluded.daily,
                h12=excluded.h12,
                h8=excluded.h8,
                h4=excluded.h4,
                h3=excluded.h3,
                updated=excluded.updated
            """,
            (
                symbol,
                states.get("Weekly", ""),
                states.get("Daily", ""),
                states.get("12H", ""),
                states.get("8H", ""),
                states.get("4H", ""),
                states.get("3H", ""),
                datetime.utcnow().isoformat(),
            )
        )
        c.commit()


def full_trend_at_structural_sr(symbol, grp, direction):
    """Edo FULL TREND S/R gate.

    FULL BULLISH is actionable only when the newest fully CLOSED candle is
    confirming a meaningful SUPPORT retest/bounce. FULL BEARISH is actionable
    only at a meaningful RESISTANCE retest/rejection.

    Check 4H first, then Daily. These are structural context timeframes; 8H is not used by FULL TREND.
    """
    wanted = "bullish" if str(direction).upper() == "BULLISH" else "bearish"
    wanted_name = "SUPPORT" if wanted == "bullish" else "RESISTANCE"

    for label, interval in (("4H", "4h"), ("Daily", "1day")):
        candles, err = get_candles(symbol, interval, outputsize=140, grp=grp)
        if err:
            continue
        closed = fully_closed_candles(candles, interval)
        if len(closed) < 30:
            continue
        reactions = detect_support_resistance_signal(closed)
        for reaction in reactions:
            if reaction.get("direction") == wanted:
                return True, {
                    "kind": wanted_name,
                    "level": reaction.get("level"),
                    "timeframe": label,
                    "confirmation_date": reaction.get("confirmation_date", ""),
                }

    return False, None


_FULL_TREND_CONFIRMED_EVENTS = {}


# Full Trend pivot confirmation requires one CLOSED Daily candle on each side.
# This is intentionally more sensitive than Gap Retest swing selection:
# a modest local turn can define Edo's Daily 50%-wick trend trigger.
FULL_TREND_SWING_LEFT = 1
FULL_TREND_SWING_RIGHT = 1


def full_trend_clear_daily_swings(daily, kind, left=FULL_TREND_SWING_LEFT,
                                  right=FULL_TREND_SWING_RIGHT):
    """FULL TREND ONLY: keep even small, genuine confirmed Daily local swings.

    A Daily high must exceed neighbouring Daily highs; a Daily low must be
    below neighbouring Daily lows. No ATR/range/prominence test applies here.
    The right-side candle must be closed before the pivot can be used.
    Separate, stricter pivots for Gap Retests and other patterns are unchanged.
    """
    key = "high" if kind == "high" else "low"
    points = []
    for i in range(left, len(daily) - right):
        price = float(daily[i][key])
        neighbours = [float(daily[j][key])
                      for j in range(i - left, i + right + 1) if j != i]
        if kind == "high" and price > max(neighbours):
            points.append((i, price))
        elif kind == "low" and price < min(neighbours):
            points.append((i, price))
    return points


def full_trend_body_break_percent(candle, level, direction):
    """Percentage of the CLOSED candle's real body beyond a Daily mid-wick level.

    Wicks do not count.  A bullish confirmation must close ABOVE the level;
    a bearish confirmation must close BELOW it.  A doji has no valid body.
    """
    opening = float(candle["open"])
    closing = float(candle["close"])
    body = abs(closing - opening)
    if body <= 0:
        return 0.0
    if direction == "BULLISH" and closing > level:
        return 100.0 * max(0.0, closing - max(min(opening, closing), level)) / body
    if direction == "BEARISH" and closing < level:
        return 100.0 * max(0.0, min(max(opening, closing), level) - closing) / body
    return 0.0


FULL_TREND_MIN_BODY_BREAK_PCT = 25.0


def daily_structure_break_state(daily_candles, eight_hour_candles, confirmation_interval="8h"):
    """FULL TREND ONLY: Daily confirmed swing mid-wicks, 8H closed-candle breaks.

    A Daily pivot is usable only after its right-hand Daily confirmation candle has closed.
    Replaying the 8H history never uses a Daily pivot that was not yet known.
    The main trend persists until an opposite confirmed 8H break.
    """
    from datetime import timedelta

    daily = fully_closed_candles(daily_candles, "1day")
    eight = fully_closed_candles(eight_hour_candles, confirmation_interval)
    if len(daily) < 12 or len(eight) < 2:
        return "", None

    highs = full_trend_clear_daily_swings(daily, "high")
    lows = full_trend_clear_daily_swings(daily, "low")
    daily_starts = [parse_candle_utc(c.get("datetime")) for c in daily]
    eight_starts = [parse_candle_utc(c.get("datetime")) for c in eight]
    state, event = "", None
    # Optional FULL TREND replay audit; never changes the trading decision.
    # Enable EDO_FULL_TREND_AUDIT=1 in Railway to inspect historical crossings.
    import os
    audit = os.environ.get("EDO_FULL_TREND_AUDIT", "").strip() == "1"
    audit_rows = []

    for i, candle in enumerate(eight):
        start = eight_starts[i]
        if start is None:
            continue
        close_time = start + timedelta(hours=12 if confirmation_interval == "12h" else 8)
        # The required right-hand Daily confirmation candle must have closed first.
        known_highs = [(j, v) for j, v in highs
                       if j + FULL_TREND_SWING_RIGHT < len(daily) and daily_starts[j + FULL_TREND_SWING_RIGHT] is not None
                       and daily_starts[j + FULL_TREND_SWING_RIGHT] + timedelta(days=1) <= close_time]
        known_lows = [(j, v) for j, v in lows
                      if j + FULL_TREND_SWING_RIGHT < len(daily) and daily_starts[j + FULL_TREND_SWING_RIGHT] is not None
                      and daily_starts[j + FULL_TREND_SWING_RIGHT] + timedelta(days=1) <= close_time]
        # A bullish break needs a confirmed high, not an unrelated confirmed
        # low (and vice versa). Requiring both silently skips valid breakouts.
        hi_idx = known_highs[-1][0] if known_highs else None
        lo_idx = known_lows[-1][0] if known_lows else None
        high_mid = None
        low_mid = None
        if hi_idx is not None:
            high_c = daily[hi_idx]
            high_mid = (float(high_c["high"]) + max(float(high_c["open"]), float(high_c["close"]))) / 2.0
        if lo_idx is not None:
            low_c = daily[lo_idx]
            low_mid = (float(low_c["low"]) + min(float(low_c["open"]), float(low_c["close"]))) / 2.0
        close = float(candle["close"])
        previous_close = float(eight[i - 1]["close"]) if i else None

        # A Full Trend confirmation marks the START of a directional regime.
        # Repeated breaks of later same-direction swing levels are continuation,
        # not a fresh Full Trend start. Replay history chronologically so a
        # restart or rescan cannot replace the original event with today's date.
        # The pivot is already confirmed at this candle's close. The prior
        # 8H close only establishes which side of the level price came from;
        # it need not precede the instant the Daily pivot became confirmed.
        bullish_pct = (full_trend_body_break_percent(candle, high_mid, "BULLISH")
                       if high_mid is not None else 0.0)
        bearish_pct = (full_trend_body_break_percent(candle, low_mid, "BEARISH")
                       if low_mid is not None else 0.0)

        # The first close over/under the Daily level can be too shallow (<25%).
        # Give the immediately FOLLOWING closed confirmation candle a chance
        # to qualify; do not demand that it crosses the line for a second time.
        # Only the real candle body counts, never the wick.
        prior_bull_weak = (
            i >= 2 and high_mid is not None
            and float(eight[i-2]["close"]) <= high_mid
            and float(eight[i-1]["close"]) > high_mid
            and full_trend_body_break_percent(eight[i-1], high_mid, "BULLISH")
            < FULL_TREND_MIN_BODY_BREAK_PCT
        )
        prior_bear_weak = (
            i >= 2 and low_mid is not None
            and float(eight[i-2]["close"]) >= low_mid
            and float(eight[i-1]["close"]) < low_mid
            and full_trend_body_break_percent(eight[i-1], low_mid, "BEARISH")
            < FULL_TREND_MIN_BODY_BREAK_PCT
        )
        # A pivot cannot be used until its right-hand Daily confirmation candle closes.
        # If its 50%-wick level was already crossed before that moment, the
        # previous logic demanded a SECOND crossing and left FULL TREND stuck
        # in the old direction. The first eligible 8H/12H candle can instead
        # confirm with >=25% of ITS OWN body beyond the newly available level.
        # This never backdates a signal to before the pivot was known.
        previous_candle_end = (
            eight_starts[i - 1] + timedelta(hours=12 if confirmation_interval == "12h" else 8)
            if i and eight_starts[i - 1] is not None else None
        )
        high_first_eligible = (
            hi_idx is not None and previous_candle_end is not None
            and daily_starts[hi_idx + FULL_TREND_SWING_RIGHT] is not None
            and previous_candle_end < daily_starts[hi_idx + FULL_TREND_SWING_RIGHT] + timedelta(days=1) <= close_time
        )
        low_first_eligible = (
            lo_idx is not None and previous_candle_end is not None
            and daily_starts[lo_idx + FULL_TREND_SWING_RIGHT] is not None
            and previous_candle_end < daily_starts[lo_idx + FULL_TREND_SWING_RIGHT] + timedelta(days=1) <= close_time
        )
        # If a small Daily pivot is confirmed after an earlier shallow crossing,
        # allow the NEXT qualifying closed candle to establish the missing state.
        # Do not demand a second crossing of the same level.
        # Never flip merely because price remains beyond an OLD pivot level.
        # Demand an actual crossing, immediate follow-up to a shallow break,
        # or the first closed confirmation candle after pivot eligibility.
        # Shared by Forex/CFD 8H and Crypto 12H trend identification.
        bullish_cross = (high_mid is not None and previous_close is not None
                         and (previous_close <= high_mid or prior_bull_weak or high_first_eligible)
                         and bullish_pct >= FULL_TREND_MIN_BODY_BREAK_PCT)
        bearish_cross = (low_mid is not None and previous_close is not None
                         and (previous_close >= low_mid or prior_bear_weak or low_first_eligible)
                         and bearish_pct >= FULL_TREND_MIN_BODY_BREAK_PCT)
        if audit and (bullish_cross or bearish_cross):
            audit_rows.append((str(start), "BULLISH" if bullish_cross else "BEARISH",
                               "NEW" if (bullish_cross and state != "FULL BULLISH") or
                               (bearish_cross and state != "FULL BEARISH") else "CONTINUATION",
                               round(close, 6),
                               round(high_mid if bullish_cross else low_mid, 6),
                               str(daily_starts[hi_idx if bullish_cross else lo_idx]),
                               round(bullish_pct if bullish_cross else bearish_pct, 2)))
        if bullish_cross and state != "FULL BULLISH":
            state = "FULL BULLISH"
            event = {"direction": "BULLISH", "level": high_mid,
                     "swing_index": hi_idx, "break_index": i,
                     "break_body_percent": bullish_pct,
                     "break_candle": candle, "level_method": f"daily_high_upper_wick_50pct_{confirmation_interval}_body25_close"}
        elif bearish_cross and state != "FULL BEARISH":
            state = "FULL BEARISH"
            event = {"direction": "BEARISH", "level": low_mid,
                     "swing_index": lo_idx, "break_index": i,
                     "break_body_percent": bearish_pct,
                     "break_candle": candle, "level_method": f"daily_low_lower_wick_50pct_{confirmation_interval}_body25_close"}
    if audit:
        print("EDO FULL TREND REPLAY AUDIT: crossings (UTC candle start, side, event, 8H close, Daily wick midpoint, swing date):", audit_rows, flush=True)
        print("EDO FULL TREND REPLAY AUDIT: final state:", state,
              "start:", event["break_candle"].get("datetime") if event else None,
              "daily bars:", len(daily), "confirmation bars:", len(eight), flush=True)
    return state, event


def aligned_full_trend_status(daily_break_status, weekly_state):
    """Use FULL only when Weekly and confirmed Daily/8H (Crypto 12H) agree.

    Preserve the independent daily breakout state; the weekly filter changes
    the displayed classification, not the breakout detector itself.
    """
    daily = ("Bullish" if daily_break_status == "FULL BULLISH" else
             "Bearish" if daily_break_status == "FULL BEARISH" else "Mixed")
    weekly = str(weekly_state or "").strip().capitalize()
    if daily == "Mixed":
        return "MIXED / WAIT"
    if weekly not in ("Bullish", "Bearish"):
        return f"{daily.upper()} — UNCONFIRMED"
    if weekly == daily:
        return f"FULL {daily.upper()}"
    return f"{daily.upper()} — MIXED"


# -------------------------------------------------
# WEEKLY -> DAILY BODY-BREAK / RETEST ALIGNMENT (MAIN TREND)
# Replaces CCI arrows. Entirely independent of FULL trend and trading signals.
# 1) First fully closed Weekly opposite-colour reversal candle CLOSES past
#    the prior Weekly candle's body top (bull) or body bottom (bear).
# 2) That prior body boundary becomes the horizontal Weekly trigger line.
# 3) AFTER that Weekly confirmation, Daily returns into the vicinity of
#    the line and prints a fully closed opposite-colour confirming candle
#    that closes at least 65% through the previous Daily body AND beyond
#    BOTH the previous Daily body boundary and Weekly line.
# No forming candles, no retrospective confirmation before a Weekly close.
# -------------------------------------------------


def weekly_daily_inline_event(closed_weekly):
    """Newest confirmed Weekly reversal; price level is prior body's edge."""
    if not closed_weekly or len(closed_weekly) < 3:
        return None
    for i in range(len(closed_weekly) - 1, 0, -1):
        prev, curr = closed_weekly[i-1], closed_weekly[i]
        previous_top = max(float(prev['open']), float(prev['close']))
        previous_bottom = min(float(prev['open']), float(prev['close']))
        prev_colour, curr_colour = candle_colour(prev), candle_colour(curr)
        if prev_colour == 'red' and curr_colour == 'green' and float(curr['close']) > previous_top:
            direction, level = 'BULLISH', previous_top
        elif prev_colour == 'green' and curr_colour == 'red' and float(curr['close']) < previous_bottom:
            direction, level = 'BEARISH', previous_bottom
        else:
            continue
        start = parse_candle_utc(curr.get('datetime'))
        if start is None:
            continue
        return {'direction': direction, 'level': level,
                'weekly_closed_at': start + timedelta(days=7),
                'weekly_start': start}
    return None


def weekly_daily_inline_from_candles(weekly, daily, now_utc=None):
    """Pure signal check for an already downloaded pair of candle histories.

    Return the latest confirmed Weekly-level/Daily-retest event. It is now
    the main FULL trend method and remains active until a newer reversal or
    a completed Daily candle crosses back over the Weekly reference level.
    """
    if now_utc is None:
        now_utc = datetime.now(timezone.utc)
    w_closed = weekly_card_completed_candles(weekly, now_utc=now_utc)
    d_closed = fully_closed_candles(daily, '1day', now_utc=now_utc)
    event = weekly_daily_inline_event(w_closed)
    if not event or len(d_closed) < 5:
        return '', None, None
    direction, level = event['direction'], event['level']
    after = []
    for c in d_closed:
        dt = parse_candle_utc(c.get('datetime'))
        if dt is not None and dt >= event['weekly_closed_at']:
            after.append(c)
    if len(after) < 2:
        return '', None, None
    # A line may be approached rather than touched to the exact pip.
    ar = avg_range(d_closed, end=len(d_closed), length=20)
    tolerance = max(ar * 0.35, abs(level) * 0.00035)
    confirmation = None
    for i in range(1, len(after)):
        prev, curr = after[i-1], after[i]
        prev_top = max(float(prev['open']), float(prev['close']))
        prev_bottom = min(float(prev['open']), float(prev['close']))
        previous_body = prev_top - prev_bottom
        if previous_body <= 0:
            continue
        # Edo's Daily confirmation: the first opposite-colour candle must
        # recover/reject at least 65% of the previous candle's REAL body.
        # It must also CLOSE beyond the entire previous body and Weekly level,
        # as illustrated in the live chart example (not a wick-only break).
        if direction == 'BULLISH':
            retest = float(prev['low']) <= level + tolerance and float(prev['low']) >= level - max(ar * 1.25, tolerance)
            body_recovered_pct = 100.0 * (float(curr['close']) - prev_bottom) / previous_body
            valid = (candle_colour(prev) == 'red' and candle_colour(curr) == 'green'
                     and body_recovered_pct >= 65.0
                     and float(curr['close']) > max(level, prev_top) and retest)
        else:
            retest = float(prev['high']) >= level - tolerance and float(prev['high']) <= level + max(ar * 1.25, tolerance)
            body_rejected_pct = 100.0 * (prev_top - float(curr['close'])) / previous_body
            valid = (candle_colour(prev) == 'green' and candle_colour(curr) == 'red'
                     and body_rejected_pct >= 65.0
                     and float(curr['close']) < min(level, prev_bottom) and retest)
        if valid:
            confirmation = curr
    if confirmation is None:
        return '', None, None
    confirm_start = parse_candle_utc(confirmation.get('datetime'))
    if confirm_start is None:
        return '', None, None
    # This is now the MAIN market trend, not a seven-day signal. It holds
    # until the latest completed Weekly reversal needs a new Daily confirmation
    # or a closed Daily candle returns across its Weekly trigger level.
    latest_close = float(d_closed[-1]['close'])
    if (direction == 'BULLISH' and latest_close <= level) or (direction == 'BEARISH' and latest_close >= level):
        return '', None, None
    return direction, level, confirm_start.isoformat()


def update_weekly_daily_alignment(symbol, grp):
    """Mirror main-trend arrow; alert once when the confirmed direction changes."""
    state, level, confirmed_at = '', None, None
    try:
        weekly, we = get_candles(symbol, '1week', outputsize=100, grp=grp)
        daily, de = get_candles(symbol, '1day', outputsize=260, grp=grp)
        if we or de or not weekly or not daily:
            print('Weekly/Daily inline feed:', symbol, we or de, flush=True)
            return   # Do not overwrite last known status on transient feed outage.
        main_status, main_event, _ = weekly_daily_main_trend_from_candles(weekly, daily)
        if main_event:
            state = 'BULLISH' if main_status == 'FULL BULLISH' else 'BEARISH'
            level = main_event['level']
            confirmed_at = main_event['break_candle'].get('datetime')
    except Exception as exc:
        print('Weekly/Daily inline check:', symbol, exc, flush=True)
        return
    should_alert = False
    with db_conn() as c:
        prior = c.execute('SELECT state,confirmed_at FROM weekly_daily_inline WHERE symbol=? AND grp=?',
                          (symbol, grp)).fetchone()
        c.execute("""INSERT INTO weekly_daily_inline(symbol,grp,state,level,confirmed_at,updated)
                     VALUES(?,?,?,?,?,?) ON CONFLICT(symbol,grp) DO UPDATE SET
                     state=excluded.state, level=excluded.level,
                     confirmed_at=excluded.confirmed_at, updated=excluded.updated""",
                  (symbol, grp, state, level, confirmed_at, datetime.now(timezone.utc).isoformat()))
        # First deployment creates a baseline; do not announce historic signals.
        if prior is not None and state and prior['state'] != state:
            confirmed_dt = parse_candle_utc(confirmed_at)
            # Pushover only for newly reversed directions, not historical repeats.
            if confirmed_dt and datetime.now(timezone.utc) - (confirmed_dt + timedelta(days=1)) <= timedelta(hours=12):
                key = f'{state}|{confirmed_at}'
                inserted = c.execute("""INSERT OR IGNORE INTO weekly_daily_inline_sound_log
                    (symbol,grp,direction,event_key,sent_at) VALUES(?,?,?,?,?)""",
                    (symbol,grp,state,key,datetime.now(timezone.utc).isoformat()))
                should_alert = inserted.rowcount == 1
        c.commit()
    if should_alert:
        label = 'BULLISH — INLINE' if state == 'BULLISH' else 'BEARISH — INLINE'
        ok = send_push(f'{label} • Weekly/Daily',
                       f'{symbol} • Main trend: Weekly body breakout + Daily 65% confirmation at {level:.5f}.',
                       sound='magic')
        if not ok:
            print('Weekly/Daily inline Pushover not accepted:', symbol, flush=True)


def weekly_daily_main_trend_from_candles(weekly, daily, now_utc=None):
    """Edo's ONE main trend method: latest Weekly body break + Daily confirmation.

    The most recent closed Weekly opposite-colour body breakout sets the active
    trigger line. A confirmed Daily opposite-colour body breakout of >=65%
    must close beyond that Weekly line following a retest. The Daily candle
    must be fully closed and must occur AFTER the Weekly reversal closed.
    An unconfirmed newer Weekly reversal yields MIXED / WAIT, not a stale FULL.
    """
    if now_utc is None:
        now_utc = datetime.now(timezone.utc)
    weekly_closed = weekly_card_completed_candles(weekly, now_utc=now_utc)
    daily_closed = fully_closed_candles(daily, '1day', now_utc=now_utc)
    weekly_event = weekly_daily_inline_event(weekly_closed)
    if weekly_event is None or len(daily_closed) < 5:
        return 'MIXED / WAIT', None, weekly_event
    direction, level, confirmed_at = weekly_daily_inline_from_candles(
        weekly, daily, now_utc=now_utc)
    if direction != weekly_event['direction'] or confirmed_at is None:
        return 'MIXED / WAIT', None, weekly_event
    # Find actual fully closed Daily confirmation to save its REAL timestamp.
    confirmation = next((c for c in reversed(daily_closed)
                         if parse_candle_utc(c.get('datetime')) == parse_candle_utc(confirmed_at)), None)
    if confirmation is None:
        return 'MIXED / WAIT', None, weekly_event
    status = 'FULL BULLISH' if direction == 'BULLISH' else 'FULL BEARISH'
    return status, {'break_candle': confirmation, 'level': level,
                    'level_method': '1day', 'weekly_event': weekly_event}, weekly_event


def build_full_alignment(symbol, grp=None):
    """Main trend: ONLY confirmed Weekly body reversal + Daily 65% confirmation."""
    clear_ohlc_cache_for_symbol(symbol, grp, intervals={'1week', '1day'})
    weekly, we = get_candles(symbol, '1week', outputsize=100, grp=grp)
    if we:
        return '', we
    daily, de = get_candles(symbol, '1day', outputsize=260, grp=grp)
    if de:
        return '', de
    status, event, weekly_event = weekly_daily_main_trend_from_candles(weekly, daily)
    _FULL_TREND_CONFIRMED_EVENTS[symbol] = (status, event)
    weekly_state = (weekly_event['direction'].capitalize() if weekly_event else 'Mixed')
    daily_state = ('Bullish' if status == 'FULL BULLISH' else
                   'Bearish' if status == 'FULL BEARISH' else 'Mixed')
    save_trend_snapshot(symbol, {'Weekly': weekly_state, 'Daily': daily_state})
    return status, None


def save_trend_status(symbol, status):
    """
    Atomically save trend status and return the previously stored status.

    The `updated` timestamp is now the time the CURRENT trend state began,
    not the time of the latest background check.  If the state is unchanged
    we preserve the existing timestamp so the Trend page can display
    "FULL BULLISH since ..." / "FULL BEARISH since ...".

    BEGIN IMMEDIATE serialises competing Railway/Gunicorn workers so two
    workers cannot both read the same old state and send the same FULL TREND
    Pushover twice.
    """
    now_iso = datetime.utcnow().isoformat()
    cached_status, event = _FULL_TREND_CONFIRMED_EVENTS.get(symbol, (None, None))
    # A scan timestamp is not a historical break timestamp.  Do not invent a
    # confirmation date when the detector has no verified break candle.
    if status in ("FULL BULLISH", "FULL BEARISH") and not (cached_status == status and event and event.get("break_candle")):
        return None
    if cached_status == status and event and event.get("break_candle"):
        from datetime import timedelta
        candle_start = parse_candle_utc(event["break_candle"].get("datetime"))
        if candle_start is not None:
            now_iso = (candle_start + (timedelta(days=1) if event.get('level_method') == '1day' else timedelta(hours=12 if '12h' in event.get('level_method', '') else 8))).replace(tzinfo=None).isoformat()
    with db_conn() as c:
        c.execute("BEGIN IMMEDIATE")
        row = c.execute(
            "SELECT status, updated FROM trend_status WHERE symbol=?",
            (symbol,)
        ).fetchone()
        previous = row["status"] if row else None

        if row is None:
            c.execute(
                "INSERT INTO trend_status(symbol,status,updated) VALUES(?,?,?)",
                (symbol, status, now_iso)
            )
        elif previous != status:
            c.execute(
                "UPDATE trend_status SET status=?, updated=? WHERE symbol=?",
                (status, now_iso, symbol)
            )
        elif (status in ("FULL BULLISH", "FULL BEARISH") and
              cached_status == status and event and row["updated"] != now_iso):
            # Repair old scan-time timestamps from previous deployments.
            c.execute("UPDATE trend_status SET updated=? WHERE symbol=?", (now_iso, symbol))
        # If unchanged, preserve the actual candle confirmation timestamp.
        c.commit()

    return previous


def active_trend_monitor():
    # Start two minutes after boot, then keep TRIGGERED alert trend data fresh.
    time.sleep(120)
    index = 0

    while True:
        try:
            if manual_api_priority_active():
                time.sleep(15)
                continue

            with db_conn() as c:
                # FULL TREND now uses Weekly→Daily confirmation. Monitor all saved
                # favourites, not only symbols whose price alert was already
                # triggered. Keep triggered-alert symbols too in case a user
                # later removes a favourite while an alert is still active.
                rows = c.execute(
                    """
                    SELECT symbol, grp FROM favorites
                    UNION
                    SELECT symbol, grp FROM alerts WHERE triggered=1
                    ORDER BY symbol
                    """
                ).fetchall()

            markets = [(r["symbol"], r["grp"]) for r in rows]

            if markets:
                if index >= len(markets):
                    index = 0

                symbol, grp = markets[index]
                index = (index + 1) % len(markets)

                # Weekend safety: spot Forex is closed. Do not calculate or
                # push FULL TREND states from stale Friday candles. Crypto is
                # intentionally NOT blocked here and remains active 24/7,
                # including Saturday and Sunday. CFDs are left unchanged.
                if str(grp).upper() == "FOREX" and forex_weekend_closed():
                    print("forex weekend full-trend monitor suppressed", symbol)
                    time.sleep(1)
                    continue

                status, error = build_full_alignment(symbol, grp)

                if error:
                    print("active trend error", symbol, error)
                else:
                    # trend_status is persistent in SQLite, so restart/redeploy
                    # does not erase the previously processed trend state.
                    previous = save_trend_status(symbol, status)

                    # Matching Weekly/Daily reversal arrow; refresh at most
                    # every 30 minutes to protect broker/API rate limits.
                    try:
                        with db_conn() as c:
                            last_row = c.execute(
                                'SELECT updated FROM weekly_daily_inline WHERE symbol=? AND grp=?',
                                (symbol, grp)
                            ).fetchone()
                        last_dt = parse_candle_utc(last_row['updated']) if last_row else None
                        due = (last_dt is None or
                               (datetime.now(timezone.utc) - last_dt).total_seconds() >= 1800)
                        if due:
                            update_weekly_daily_alignment(symbol, grp)
                    except Exception as inline_exc:
                        print('Weekly/Daily inline monitor:', symbol, inline_exc, flush=True)

                    # FULL TREND is now based on Weekly→Daily and is a dashboard indicator.
                    # Keep the persistent state fresh for Saved Pairs / Trend pages,
                    # but do NOT send FULL BULLISH / FULL BEARISH Pushover alerts.

        except Exception as e:
            print("active trend monitor error", e)

        # One market per minute keeps API use modest while making FULL TREND
        # notifications much more responsive across all saved favourites.
        time.sleep(60)


