def trailing_legacy_distance_value(symbol, grp, distance_pips):
    """Compatibility only for trails created before PRICE-entry mode."""
    d=float(distance_pips)
    if str(grp).upper()=='FOREX':
        compact=str(symbol).upper().replace('/','').replace(' ','')
        return d*(0.01 if compact.endswith('JPY') else 0.0001)
    return d


@APP.get('/trailing/live-price')
def trailing_live_price():
    symbol=request.args.get('symbol','').upper().strip(); grp=request.args.get('group','FOREX').upper().strip()
    if not symbol or grp not in {'FOREX','CRYPTO','CFD'}:
        return jsonify(ok=False, error='Select a valid pair'), 400
    price=latest_price(symbol, grp, force_refresh=True)
    if price is None:
        return jsonify(ok=False, error='Live price temporarily unavailable'), 503
    return jsonify(ok=True, symbol=symbol, group=grp, price=price)


@APP.post('/trailing/add')
def trailing_add():
    symbol=request.form.get('symbol','').upper().strip(); grp=request.form.get('group','FOREX').upper().strip()
    side=request.form.get('side','BUY').upper().strip(); interval=request.form.get('interval','1h').strip(); note=request.form.get('note','').strip()
    try:
        stop=float(request.form.get('stop_price','0'))
    except Exception: return redirect('/')
    if not symbol or stop<=0 or side not in {'BUY','SELL'} or interval not in {'1h','4h','8h','1day'}: return redirect('/')
    # Take a fresh quote at the exact ARM action and permanently lock that raw price distance.
    arm_price=latest_price(symbol, grp, force_refresh=True)
    if arm_price is None or arm_price<=0: return redirect('/?trail_error=price')
    if side=='BUY' and stop>=arm_price: return redirect('/?trail_error=buy_stop')
    if side=='SELL' and stop<=arm_price: return redirect('/?trail_error=sell_stop')
    distance_price=abs(float(arm_price)-stop)
    if distance_price<=0: return redirect('/')

    # Baseline the newest candle that was ALREADY fully closed when Edo arms the trail.
    # That candle belongs to the past and must never move/hit a newly-created trail.
    # The monitor will therefore act only after a DIFFERENT candle closes later.
    baseline_start=''
    baseline_time=''
    try:
        arm_candles, arm_error = get_candles(symbol, interval, outputsize=8, grp=grp)
        if not arm_error and arm_candles:
            baseline = last_closed_candle(arm_candles, interval)
            if baseline:
                baseline_start = str(baseline.get('datetime',''))
                baseline_time = format_closed_candle_close_perth(baseline, interval)
    except Exception as e:
        print('trailing arm baseline error', symbol, e)

    # Do not arm without a closed-candle baseline: otherwise the monitor could process
    # the previous candle as though it closed after the trail was created.
    if not baseline_start:
        return redirect('/?trail_error=baseline')

    with db_conn() as c:
        # distance_pips is retained as the DB column name for backwards-compatible schema;
        # ARM_PRICE records store the permanent raw PRICE distance here. entry_price stores arm quote.
        c.execute("INSERT INTO trailing_stops(symbol,grp,side,interval,distance_pips,stop_price,last_candle_start,last_candle_time,created,note,distance_mode,entry_price) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)", (symbol,grp,side,interval,distance_price,stop,baseline_start,baseline_time,datetime.now(timezone.utc).isoformat(),note,'ARM_PRICE',float(arm_price))); c.commit()
    return redirect('/')

