@APP.route('/signal/<int:i>')
def signal(i):
    # Manual screen request gets priority over background API scans.
    give_manual_api_priority(90)

    with db_conn() as c:
        f = c.execute(
            'SELECT * FROM favorites WHERE id=?',
            (i,)
        ).fetchone()

    if not f or f['grp'] not in ('FOREX', 'CRYPTO', 'CFD'):
        return redirect('/')

    # Edo UI rule: Crypto no longer exposes the 8H manual signal timeframe.
    # This is display/navigation only; no other market group's timeframes change.
    signal_timeframes = [
        x for x in PATTERN_TIMEFRAMES
        if not (f['grp'] == 'CRYPTO' and x['value'] == '8h')
        and not (f['grp'] == 'CFD' and x['value'] == '1month')
        and not (f['grp'] != 'CRYPTO' and x['value'] == '12h')
    ]
    allowed = {x["value"]: x["label"] for x in signal_timeframes}
    unread_on_entry = unread_timeframes(f['grp'], f['symbol'])
    default_tf = next((x["value"] for x in signal_timeframes if x["value"] in unread_on_entry), "4h" if f['grp'] == 'CRYPTO' else "8h")
    selected_tf = request.args.get("tf", default_tf)

    if selected_tf not in allowed:
        selected_tf = "4h" if f['grp'] == 'CRYPTO' else "8h"

    force_refresh = request.args.get('refresh') == '1'
    data, error = build_pattern_signal(
        f['symbol'],
        selected_tf,
        grp=f['grp'],
        force_refresh=force_refresh
    )

    if not error:
        setups, latest_closed_date, setup_error = collect_closed_pattern_setups(
            f['symbol'],
            selected_tf,
            f['grp']
        )
        if setup_error:
            print("manual pattern notification error", f['symbol'], selected_tf, setup_error)
        else:
            save_timeframe_ready_status(f['grp'], f['symbol'], selected_tf, setups, latest_closed_date)
            if request.args.get("view") == "1":
                if "tf" in request.args:
                    # Only an explicit timeframe button click clears its NEW label.
                    acknowledge_timeframe_ready(f['grp'], f['symbol'], selected_tf)
                else:
                    # Opening the HOME icon stops blinking, but leaves NEW labels.
                    acknowledge_home_blink(f['grp'], f['symbol'])
                    acknowledge_price_action(f['grp'], f['symbol'])
            if selected_tf == "4h":
                save_price_action_status(f['grp'], f['symbol'], setups, latest_closed_date)
                if request.args.get("view") == "1":
                    acknowledge_price_action(f['grp'], f['symbol'])
            notify_new_pattern_setups(
                f['symbol'],
                selected_tf,
                setups,
                latest_closed_date,
                f['grp']
            )


    new_timeframes = unread_timeframes(f['grp'], f['symbol'])

    if error:
        return render_template_string(
            SIGNAL_HTML,
            symbol=f['symbol'],
            group=f['grp'],
            fav_id=f['id'],
            timeframes=signal_timeframes,
            new_timeframes=new_timeframes,
            selected_tf=selected_tf,
            selected_label=allowed[selected_tf],
            price='—',
            latest_closed_date='—',
            latest_closed_perth='—',
            market_source='',
            weekly_spike=None,
            signal='',
            signal_icon='',
            signal_css='neutral',
            summary='',
            patterns=[],
            updated='—',
            error=error
        )

    return render_template_string(
        SIGNAL_HTML,
        symbol=f['symbol'],
        group=f['grp'],
        fav_id=f['id'],
        timeframes=signal_timeframes,
        new_timeframes=new_timeframes,
        selected_tf=selected_tf,
        selected_label=allowed[selected_tf],
        price=f"{data['price']:.5f}",
        latest_closed_date=data.get('latest_closed_date', ''),
        latest_closed_perth=format_signal_time_perth(data.get('latest_closed_date', '')),
        market_source=data.get('market_source', ''),
        weekly_spike=data.get('weekly_spike'),
        signal=data['signal'],
        signal_icon=data['signal_icon'],
        signal_css=data['signal_css'],
        summary=data['summary'],
        patterns=attach_pattern_push_history(f['symbol'], selected_tf, data['patterns']),
        updated=data['updated'],
        error=''
    )


@APP.route('/trend/<int:i>')
def trend(i):
    # Manual screen request gets priority over background API scans.
    give_manual_api_priority(90)

    with db_conn() as c:
        f = c.execute(
            'SELECT * FROM favorites WHERE id=?',
            (i,)
        ).fetchone()

    if not f:
        return redirect('/')

    scan, error = build_trend_scan(f['symbol'], f['grp'])

    # The background monitor stores when the current FULL TREND state began.
    # If the manual Trend page discovers a changed state before the background
    # loop gets to this market, record it here as well (without sending a push).
    full_trend_since = ''
    if not error:
        current_full = scan['summary']  # FULL, MIXED, UNCONFIRMED or WAIT
        with db_conn() as c:
            row = c.execute(
                'SELECT status, updated FROM trend_status WHERE symbol=?',
                (f['symbol'],)
            ).fetchone()
        stored_status = row['status'] if row else None
        # Reconcile the historical confirmation timestamp on every successful
        # manual scan, even when the trend direction has not changed.  The old
        # status-only guard left previously stored scan dates untouched.
        if (stored_status != current_full or
                (current_full and _FULL_TREND_CONFIRMED_EVENTS.get(f['symbol'], (None, None))[1])):
            save_trend_status(f['symbol'], current_full)
            with db_conn() as c:
                row = c.execute(
                    'SELECT status, updated FROM trend_status WHERE symbol=?',
                    (f['symbol'],)
                ).fetchone()
        if row and row['status'] == current_full and current_full:
            try:
                dt = datetime.fromisoformat(row['updated'])
                full_trend_since = dt.strftime('%Y-%m-%d %H:%M UTC')
            except Exception:
                full_trend_since = str(row['updated'] or '')

    if error:
        return render_template_string(
            TREND_HTML,
            symbol=f['symbol'],
            grp=f['grp'],
            results=[],
            summary='',
            summary_icon='',
            summary_css='mixed',
            detail='',
            full_trend_since='',
            error=error
        )

    return render_template_string(
        TREND_HTML,
        symbol=f['symbol'],
        grp=f['grp'],
        results=scan['results'],
        summary=scan['summary'],
        summary_icon=scan['summary_icon'],
        summary_css=scan['summary_css'],
        detail=scan['detail'],
        full_trend_since=full_trend_since,
        error=''
    )


